// Rehost server — serves Ben's v16.7 artefact with LIVE Supabase data injected at request time.
// Mirrors build_v4.py's placeholder approach, but pulls from Supabase per load instead of baked-in.
// Phase 1: DATA (sales summary) injected live.
// Phase 2 (this step): the forecast read-write loop —
//   READ  : FC_CURRENT injected live from planner.forecast_inputs (drives FC_SEED -> IV).
//   WRITE : POST /api/save-forecasts upserts edited subcat inputs back to forecast_inputs.
import 'dotenv/config';
import express from 'express';
import { AsyncLocalStorage } from 'node:async_hooks';
import { readFileSync, readdirSync, appendFile } from 'fs';
import pg from 'pg';
import { buildInvoice, buildDtcPackingList } from './lib/invoice.mjs';
import { buildAsnLabelsPdf } from './lib/asnpdf.mjs';
import { coghlansSftpList, coghlansSftpReady } from './lib/coghlans_sftp.mjs';

// pdf.js (bundled by pdf-parse) constructs DOMMatrix while extracting text from some invoice PDFs (e.g. US Geneva —
// fonts / transforms). It's a browser API absent in the Node/serverless runtime → "DOMMatrix is not defined". Provide
// a functional 2D polyfill (guarded — only if the runtime lacks it) so Geneva allocation parses server-side.
if (typeof globalThis.DOMMatrix === 'undefined') {
  class DOMMatrixPolyfill {
    constructor(init) { this.a = 1; this.b = 0; this.c = 0; this.d = 1; this.e = 0; this.f = 0;
      if (typeof init === 'string') { const n = init.replace(/matrix\(|\)/g, '').split(',').map(Number); if (n.length === 6)[this.a, this.b, this.c, this.d, this.e, this.f] = n; }
      else if (Array.isArray(init)) { if (init.length === 6)[this.a, this.b, this.c, this.d, this.e, this.f] = init; else if (init.length === 16) { this.a = init[0]; this.b = init[1]; this.c = init[4]; this.d = init[5]; this.e = init[12]; this.f = init[13]; } } }
    get m11() { return this.a } get m12() { return this.b } get m21() { return this.c } get m22() { return this.d } get m41() { return this.e } get m42() { return this.f }
    get is2D() { return true } get isIdentity() { return this.a === 1 && this.b === 0 && this.c === 0 && this.d === 1 && this.e === 0 && this.f === 0 }
    multiply(o) { o = o || new DOMMatrixPolyfill(); const r = new DOMMatrixPolyfill();
      r.a = this.a * o.a + this.c * o.b; r.b = this.b * o.a + this.d * o.b; r.c = this.a * o.c + this.c * o.d; r.d = this.b * o.c + this.d * o.d;
      r.e = this.a * o.e + this.c * o.f + this.e; r.f = this.b * o.e + this.d * o.f + this.f; return r; }
    multiplySelf(o) { const r = this.multiply(o); Object.assign(this, { a: r.a, b: r.b, c: r.c, d: r.d, e: r.e, f: r.f }); return this; }
    preMultiplySelf(o) { const r = (o || new DOMMatrixPolyfill()).multiply(this); Object.assign(this, { a: r.a, b: r.b, c: r.c, d: r.d, e: r.e, f: r.f }); return this; }
    translate(tx, ty) { return this.multiply(Object.assign(new DOMMatrixPolyfill(), { e: tx || 0, f: ty || 0 })); }
    translateSelf(tx, ty) { return this.multiplySelf(Object.assign(new DOMMatrixPolyfill(), { e: tx || 0, f: ty || 0 })); }
    scale(sx, sy) { sy = (sy == null ? sx : sy); return this.multiply(Object.assign(new DOMMatrixPolyfill(), { a: sx, d: sy })); }
    scaleSelf(sx, sy) { sy = (sy == null ? sx : sy); return this.multiplySelf(Object.assign(new DOMMatrixPolyfill(), { a: sx, d: sy })); }
    rotate(deg) { const r = (deg || 0) * Math.PI / 180, c = Math.cos(r), s = Math.sin(r); return this.multiply(Object.assign(new DOMMatrixPolyfill(), { a: c, b: s, c: -s, d: c })); }
    inverse() { const det = this.a * this.d - this.b * this.c; const r = new DOMMatrixPolyfill(); if (!det) return r; r.a = this.d / det; r.b = -this.b / det; r.c = -this.c / det; r.d = this.a / det; r.e = (this.c * this.f - this.d * this.e) / det; r.f = (this.b * this.e - this.a * this.f) / det; return r; }
    transformPoint(p) { p = p || { x: 0, y: 0 }; return { x: this.a * p.x + this.c * p.y + this.e, y: this.b * p.x + this.d * p.y + this.f }; }
    toString() { return 'matrix(' + [this.a, this.b, this.c, this.d, this.e, this.f].join(', ') + ')'; }
  }
  DOMMatrixPolyfill.fromMatrix = m => new DOMMatrixPolyfill([m.a, m.b, m.c, m.d, m.e, m.f]);
  globalThis.DOMMatrix = DOMMatrixPolyfill;
  if (typeof globalThis.DOMPoint === 'undefined') globalThis.DOMPoint = class { constructor(x, y, z, w) { this.x = x || 0; this.y = y || 0; this.z = z || 0; this.w = (w == null ? 1 : w); } };
}

// On Vercel (serverless) use Supabase's TRANSACTION pooler (port 6543) — built for many
// short-lived serverless connections — with a tiny per-instance pool. Session pooler (5432)
// caps at 15 clients and serverless instances exhaust it. Locally, keep 5432 + a larger pool.
let CONN = process.env.DATABASE_URL || '';
if (process.env.VERCEL || process.env.USE_TXN_POOLER) CONN = CONN.replace(':5432/', ':6543/');   // USE_TXN_POOLER: local dev escape hatch when the session pooler (cap 15) is exhausted
// v27.799 (review item 9): on Vercel (prod) refuse to boot silently mis-configured. Without PLANNER_KEY the access gate
// (GATE, ~L852) disables and the app serves open; without DATABASE_URL / N8N_WEBHOOK_SECRET the DB and n8n webhooks fail.
if (process.env.VERCEL) {
  const _missingEnv = ['DATABASE_URL', 'PLANNER_KEY', 'N8N_WEBHOOK_SECRET'].filter(k => !String(process.env[k] || '').trim());
  if (_missingEnv.length) { console.error('[FATAL] Missing required prod env: ' + _missingEnv.join(', ') + ' — refusing to start.'); throw new Error('Missing required prod env: ' + _missingEnv.join(', ')); }
}
// Environment marker: show a SANDBOX banner unless we're pointed at the PRODUCTION Supabase (ref oolwklahstnvocaugryg).
// Keyed off the real prod DB ref so it's correct wherever it runs — live never shows it, any non-prod DB does.
const IS_SANDBOX = !String(CONN).includes('oolwklahstnvocaugryg');
const SANDBOX_BANNER = '<div id="sbx-banner" style="position:fixed;top:0;left:0;right:0;height:20px;line-height:20px;background:#f97316;color:#fff;font:700 11px/20px system-ui,-apple-system,sans-serif;text-align:center;letter-spacing:.14em;z-index:100001">SANDBOX ONLY — test data, not live</div><style>body{padding-top:20px}#hz-topbar,#hz-leftrail,#hz-drawer,#app #view-tabs-row,[id$="-drawer"],[id$="-bg"],#insights-panel,#narrative-panel,#ask-dw,[style*="position:fixed;top:0"],[style*="position:fixed;inset:0"]{top:20px!important}[id$="-drawer"],#hz-drawer,#ask-dw,#insights-panel,#narrative-panel,[style*="position:fixed;top:0"]{max-height:calc(100% - 20px)!important}@media (min-width:641px){:root{--hz-sticky-top:90px}html{scroll-padding-top:82px}#app #product-root .smp-rail{top:82px}}html body #sbx-banner,html body #sbx-fulfil{top:0!important;max-height:none!important}</style>';   // v28.172 (Ben): EVERYTHING fixed sits below the sandbox banner (top bar, rail, drawers, popups, backdrops, sticky offsets)
// v28.193 (Ben): sandbox-only "Fulfil: Sandbox | Live" switch in the orange banner (writes app_settings fulfil_env via
// /api/app-settings, which refuses it on production). Live is shown in red so it's obvious reads/pushes hit real Fulfil
// (live WRITES still also need FULFIL_LIVE_WRITES=true in the server env).
const SANDBOX_FULFIL_TOGGLE = '<div id="sbx-fulfil" style="position:fixed;top:0;right:8px;height:20px;z-index:100002;display:flex;align-items:center;gap:4px;font:700 10.5px/18px system-ui,-apple-system,sans-serif;color:#fff">'
  + '<span>Fulfil:</span><button type="button" data-env="sandbox" style="font:inherit;border:1px solid #fff;border-radius:4px;padding:0 7px;cursor:pointer;background:transparent;color:#fff">Sandbox</button>'
  + '<button type="button" data-env="live" style="font:inherit;border:1px solid #fff;border-radius:4px;padding:0 7px;cursor:pointer;background:transparent;color:#fff">Live</button></div>'
  + '<script>(function(){var w=document.getElementById("sbx-fulfil");if(!w)return;function paint(env){w.querySelectorAll("button").forEach(function(b){var on=b.dataset.env===env;b.style.background=on?(env==="live"?"#b91c1c":"#fff"):"transparent";b.style.color=on&&env!=="live"?"#c2410c":"#fff";b.title=on?"Active":(b.dataset.env==="live"?"Switch reads and pushes to LIVE Fulfil":"Switch to the Fulfil sandbox");});}'
  + 'fetch("/api/supply/erp-status").then(function(r){return r.json();}).then(function(j){paint(j&&j.fulfil_env||"sandbox");}).catch(function(){});'
  + 'w.querySelectorAll("button").forEach(function(b){b.onclick=function(){var env=b.dataset.env;fetch("/api/app-settings",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({key:"fulfil_env",value:env})}).then(function(r){return r.json();}).then(function(j){if(j&&j.error){alert(j.error);return;}paint(env);}).catch(function(e){alert("Switch failed: "+e.message);});};});})();</script>';
// Sandbox favicon: the normal app logo (favicon.png) wrapped in an orange border, so sandbox tabs are visually
// distinct from live. Served at /favicon-sbx.svg and swapped into the page only when IS_SANDBOX.
const FAVICON_SBX_SVG = (() => {
  try { const b = readFileSync(new URL('./favicon.png', import.meta.url)).toString('base64');
    return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><rect x="3.5" y="3.5" width="93" height="93" rx="18" fill="#fff7ed" stroke="#f97316" stroke-width="9"/><image href="data:image/png;base64,' + b + '" x="17" y="17" width="66" height="66" preserveAspectRatio="xMidYMid meet"/></svg>'; }
  catch (e) { return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><rect x="4" y="4" width="92" height="92" rx="18" fill="#f97316"/><text x="50" y="66" font-size="46" font-weight="700" text-anchor="middle" fill="#fff" font-family="system-ui">S</text></svg>'; }
})();
const pool = new pg.Pool({
  connectionString: CONN,
  ssl: { rejectUnauthorized: false },
  // Runaway-query cap at the POOL level (startup option). This is a BELT to the real fix, which is removing the
  // BEGIN…COMMIT transaction from queryCapped (below): the transaction — not the timeout — was what stranded pooled
  // connections on frozen Vercel containers (~1,128 idle-in-transaction reaps/day, Diviyaj 01-Sep). Autocommit single
  // statements can't strand a connection, so the reap fix holds regardless of whether this cap applies.
  // ⚠ Pooler caveat (verified on the sandbox session pooler 01-Sep): `options` is SILENTLY IGNORED there
  // (SHOW statement_timeout stays at the 2min default). Supavisor (live) forwards startup options, so it should apply
  // there — Diviyaj to confirm `SHOW statement_timeout` = 30s on a live pooled connection; the bulletproof fallback is
  // role-level `ALTER ROLE … SET statement_timeout='30s'` (pooler-agnostic). A DB-level 60s
  // idle_in_transaction_session_timeout backstop also still exists — leave it alone.
  options: '-c statement_timeout=30000',
  // Session-mode Supabase pooler caps the whole session at ~15 server connections. Keep `max` well under
  // that so a stranded generation (after a restart/crash) plus the live process can't blow the cap.
  // Sandbox (non-Vercel) uses 8 so multi-query endpoints (e.g. po-detail's ~13 parallel queries) run in fewer
  // waves over the high-latency remote pooler — closer to live's behaviour. Still well under the ~15 cap.
  max: process.env.VERCEL ? 4 : 8,
  allowExitOnIdle: true,
  // Sandbox keeps connections warm longer (30s) so working continuously doesn't keep paying the ~1.7s reconnect to
  // the remote pooler — the residual per-query ~300ms is network RTT to the remote sandbox (not present on live).
  idleTimeoutMillis: process.env.VERCEL ? 8000 : 30000,
  keepAlive: true,
  // v28.151 (review E1): fail fast instead of piling up. A checkout that can't get a connection in 10s errors (no
  // unbounded queue behind a saturated 4-conn pool = the death-spiral mechanism); a query with no reply in 35s
  // errors client-side (belt to the 30s server statement_timeout, which the pooler may drop: see E2 / ALTER ROLE).
  // Sandbox (non-Vercel) gets 120s: its session pooler ignores the startup statement_timeout (2-min server default) and the
  // remote eu-central-1 round trips make the heavy PO builds legitimately run 35s+ there. PG_QUERY_TIMEOUT_MS overrides.
  connectionTimeoutMillis: process.env.VERCEL ? 10000 : 30000,   // sandbox boot warm queues ~20 builds on 8 conns over a ~1.7s remote connect
  query_timeout: Number(process.env.PG_QUERY_TIMEOUT_MS) || (process.env.VERCEL ? 35000 : 120000),
});
// ── Resilience guards ─────────────────────────────────────────────────────────
// A dropped idle DB connection makes the pool emit 'error'; with no listener Node treats it as
// fatal and exits (the repeated EADDRNOTAVAIL crashes in dev). Log it and let the pool recycle the
// client — the next query opens a fresh connection.
pool.on('error', (err) => { console.error('[pg pool] idle client error (ignored):', err && err.message); });
// v28.151 (review E6): ROLLBACK that can't throw. A bare `await client.query('ROLLBACK')` in a catch rethrows on a dead or
// timed-out connection (the request then never answers) and hands a mid-transaction client back to the pool. Here a failed
// ROLLBACK ends the client so the finally's release() sees _ending and the pool discards it instead of reusing it.
async function _rollback(client) {
  try { await client.query('ROLLBACK'); }
  catch (e) { console.error('[pg] ROLLBACK failed, discarding client:', e && e.message); try { client.end().catch(() => {}); } catch (_) {} }
}
// v28.151 (review D3): bounded outbound fetch. ~30 integration calls (Fulfil, Xero, Flexport, DHL, FedEx, BLADE, Cin7,
// Anthropic, Resend, KV, DriveHQ) had no timeout, so one hung upstream held the request (and often a pool client) until the
// 300s function limit. AbortSignal.timeout covers headers AND body; a caller's own signal is still honoured. The abort
// surfaces as an Error naming the host so the existing catch blocks report it. No retries added (existing ones unchanged).
async function _fetchT(url, opts, ms) {
  const o = Object.assign({}, opts || {}); const t = AbortSignal.timeout(ms || 20000); const t0 = Date.now();
  o.signal = o.signal ? AbortSignal.any([o.signal, t]) : t;
  try { const r = await fetch(url, o); if (!r.ok) hzIntegNote(url, o, r.status, Date.now() - t0, false, null); return r; }   // v28.163 (Ben): health log integration_error on non-2xx
  catch (e) { if (e && (e.name === 'TimeoutError' || (e.name === 'AbortError' && t.aborted))) { let h = ''; try { h = new URL(String(url)).host; } catch (_) {} const x = new Error('Timed out after ' + Math.round((ms || 20000) / 1000) + 's calling ' + h); x.code = 'FETCH_TIMEOUT'; hzIntegNote(url, o, 0, Date.now() - t0, true, x.message); throw x; }
    hzIntegNote(url, o, 0, Date.now() - t0, false, (e && e.message) || String(e)); throw e; }
}
// v28.163 (Ben): INTEGRATION HEALTH. Every outbound call above goes through _fetchT, so ONE hook covers Fulfil, Xero (incl. the
// identity.xero.com token refresh), Flexport, DHL, FedEx, BLADE, Anthropic (/api/ai + Ask Claude), Resend and KV. A non-2xx, a
// network error or a timeout is noted into the health buffer as integration_error (no DB round trip; flushed with the rest),
// grouped by service + method + normalised path + status. Logged: host-derived service, method, path with ids replaced by :id and
// NO query string (DHL puts the tracking number there, keys never travel in our URLs but a query is dropped regardless), status,
// ms, timeout flag, and for KV the command name only. Never headers or bodies. DHL 404 = "tracking number not found" (normal).
const HZ_INTEG_HOSTS = [[/fulfil\.io$/, 'fulfil'], [/^identity\.xero\.com$/, 'xero-token'], [/xero\.com$/, 'xero'], [/flexport\.com$/, 'flexport'], [/dhl\.com$/, 'dhl'], [/fedex\.com$/, 'fedex'],
  [/bladepro\.io$/, 'blade'], [/anthropic\.com$/, 'anthropic'], [/resend\.com$/, 'resend'], [/upstash\.io$/, 'kv'], [/drivehq\.com$/, 'drivehq'], [/dearsystems\.com$|cin7\.com$/, 'cin7']];
const hzIdSeg = s => (/^(v\d{1,2}|\d{1,2}\.\d{1,2})$/.test(s)) ? s : (s.length > 24 || /^\d+$/.test(s) || (/\d/.test(s) && s.length >= 5)) ? ':id' : s;   // ids -> :id; keeps API versions (v1, 2.0) and short names (3pl, b2b)
function hzIntegNote(url, o, status, ms, timeout, msg) {
  try {
    let u; try { u = new URL(String(url)); } catch (_) { return; }
    let svc = null; for (const [re, s] of HZ_INTEG_HOSTS) if (re.test(u.host)) { svc = s; break; }
    if (!svc && KV_URL && String(url).startsWith(KV_URL)) svc = 'kv'; if (!svc) svc = u.host.slice(0, 60);
    if (svc === 'dhl' && status === 404) return;
    const method = String((o && o.method) || 'GET').toUpperCase();
    let op = u.pathname.split('/').map(hzIdSeg).join('/').slice(0, 160) || '/';
    if (svc === 'kv') { try { const c = JSON.parse(String(o.body || '')); if (Array.isArray(c) && typeof c[0] === 'string') op = c[0].slice(0, 20); } catch (_) {} }
    const message = msg ? String(msg).replace(/\?[^\s]*/g, '').slice(0, 300) : (svc + ' HTTP ' + status);
    hzHealthEvt('integration_error', svc + '|' + method + '|' + op + '|' + status + '|' + (timeout ? 1 : 0), { path: svc + ' ' + method + ' ' + op, method, status: status || null, ms, message,
      meta: { service: svc, op, status: status || 0, timeout: !!timeout } });
  } catch (_) { /* measurement must never throw */ }
}
// v27.886 (perf measurement): count DB queries per request. The per-request store (_reqStore, defined further down —
// only read at call time) gets s.q incremented on every pool.query; the finish-hook logs it. Behaviour otherwise identical.
{ const _origQuery = pool.query.bind(pool);
  // v28.083: HZ_QLOG=<ms> logs every query slower than <ms> as "[q 123ms] GET /api/... :: <sql head>" (diagnostic only; off by default).
  const _QLOG = Math.max(0, Number(process.env.HZ_QLOG || 0));
  pool.query = function () { let s = null; try { s = (typeof _reqStore !== 'undefined') ? _reqStore.getStore() : null; if (s) s.q = (s.q || 0) + 1; } catch (_) {}
    const p = _origQuery.apply(pool, arguments);
    if (_QLOG && p && typeof p.then === 'function') { const t0 = Date.now(); const sql = String((arguments[0] && arguments[0].text) || arguments[0] || '').replace(/\s+/g, ' ').slice(0, 110); const path = (s && s.req) ? (s.req.method + ' ' + String(s.req.originalUrl || s.req.url || '').split('?')[0]) : '-';
      p.then(() => { const ms = Date.now() - t0; if (ms >= _QLOG) console.log('[q ' + ms + 'ms] ' + path + ' :: ' + sql); }, () => {}); }
    return p; }; }
// v28.163 (Ben): DB HEALTH for the health log. (1) Every physical client gets its query() wrapped ONCE (pool 'connect' event) and
// timed: a statement >= HZ_SLOW_QUERY_MS (default 2000) is noted as slow_query, grouped by its first 160 chars with string and
// number literals replaced by ? (never parameters or data). This times EXECUTION only (pool.query reaches client.query with a
// callback after the checkout), so a pool wait never shows up as a slow statement; waits are db_pool below. (2) pool.connect is
// wrapped (pool.query uses it internally) and any client query error is checked: the v28.152 fail-fast errors (connect
// "timeout exceeded when trying to connect", query_timeout "Query read timeout", server statement_timeout) are noted as db_pool.
// Cost per query: one Date.now() + one closure; the note itself only fires on a slow / failed statement. All via the buffer.
const HZ_SLOW_Q_MS = Math.max(200, Number(process.env.HZ_SLOW_QUERY_MS || 2000));
function hzSqlNorm(sql) { return String(sql || '').replace(/'(?:[^']|'')*'/g, '?').replace(/(?<![$\w])\d+(?:\.\d+)?/g, '?').replace(/\s+/g, ' ').trim().slice(0, 160); }
function hzDbErr(e, op) { try { const m = String((e && e.message) || e || '');
  if (!/timeout exceeded when trying to connect|Query read timeout|statement timeout|Connection terminated due to connection timeout|ECHECKOUTTIMEOUT|EMAXCONNSESSION|max clients reached/i.test(m)) return;
  const kind = /ECHECKOUTTIMEOUT|EMAXCONNSESSION|max clients/i.test(m) ? 'pooler_saturated' : /connect/i.test(m) ? 'connect_timeout' : /statement timeout/i.test(m) ? 'statement_timeout' : 'query_timeout';   // pooler_saturated = Supabase pooler out of sessions / checkouts
  hzHealthEvt('db_pool', kind, { path: 'db ' + kind.replace('_', ' '), message: m.slice(0, 300), meta: { op, error: kind, max_waiting: pool.waitingCount, total: pool.totalCount, idle: pool.idleCount } });
} catch (_) {} }
pool.on('connect', (client) => { try { if (client.__hzQ) return; client.__hzQ = 1; const oq = client.query;
  client.query = function (cfg) {
    if (cfg && typeof cfg.submit === 'function') return oq.apply(this, arguments);   // Cursor / Submittable: untouched
    const t0 = Date.now(), n = arguments.length, cb = n && typeof arguments[n - 1] === 'function' ? arguments[n - 1] : null;
    let st = this.__hzSt || null; if (!st) { try { st = _reqStore.getStore(); } catch (_) {} }
    const done = (err) => { try { const ms = Date.now() - t0; if (err) hzDbErr(err, 'query'); _hzDbTot.n++; _hzDbTot.ms += ms; if (st) st.dbms = (st.dbms || 0) + ms;   // v28.167 (Ben): process-wide DB execution totals (GET /api/perf/recent). v28.175 (Ben): + DB ms per request (ring row `db`)
      if (ms >= HZ_SLOW_Q_MS) { const sql = hzSqlNorm((cfg && cfg.text) || cfg); const r = st && st.req;
        hzHealthEvt('slow_query', sql, { path: sql, ms, message: 'Slow SQL ' + ms + 'ms', meta: { example: r ? (r.method + ' ' + String(r.originalUrl || r.url || '').split('?')[0]).slice(0, 200) : 'background' } }); } } catch (_) {} };
    if (cb) { const a = Array.prototype.slice.call(arguments); a[n - 1] = function (err) { done(err); return cb.apply(this, arguments); }; return oq.apply(this, a); }
    const p = oq.apply(this, arguments); if (p && typeof p.then === 'function') p.then(() => done(null), done); return p; };
} catch (_) {} });
{ const _oc = pool.connect.bind(pool);   // also tags the checked-out client with the caller's request (pg-pool may hand it over from another request's async context)
  pool.connect = function (cb) { let st = null; try { st = _reqStore.getStore() || null; } catch (_) {}
    if (typeof cb === 'function') return _oc(function (err, client) { if (err) hzDbErr(err, 'connect'); else if (client) client.__hzSt = st; return cb.apply(this, arguments); });
    const p = _oc(); p.then(c => { if (c) c.__hzSt = st; }, e => hzDbErr(e, 'connect')); return p; }; }
// Keep one pooled connection WARM. idleTimeoutMillis (8s) closes idle clients, so a request after any short idle gap
// otherwise pays the remote Supabase pooler's ~8s cold-connect stall — which is what made SUPPLY (Actions etc.) feel
// slow on the sandbox even with the response caches (every request still runs one small query). A 5s SELECT 1 keeps a
// connection alive so requests reuse it. Long-lived server only; on Vercel the process is ephemeral (keepalive would
// be pointless and would fight allowExitOnIdle). unref() so it never itself holds the process open.
if (!process.env.VERCEL) {
  const _ka = setInterval(() => { pool.query('SELECT 1').catch(() => {}); }, 5000);
  _ka.unref?.();
}
// Last-resort process guards so a single malformed request or stray async rejection can't take the
// whole server down (we saw an ERR_OUT_OF_RANGE kill it once). This harness holds no critical
// in-memory state — it's a stateless proxy to Postgres — so logging and staying up beats crashing.
process.on('unhandledRejection', (reason) => { console.error('[unhandledRejection]', reason && (reason.stack || reason.message || reason)); });
