// Replace the value of a top-level `let/const/var NAME = <literal>;` by balancing brackets.
function replaceGlobal(html, name, jsonText) {
  const m = html.match(new RegExp('(?:const|let|var)\\s+' + name + '\\s*=\\s*([\\[{])'));
  if (!m) throw new Error(`global ${name} not found`);
  const start = m.index + m[0].length - 1;
  const open = html[start], close = open === '[' ? ']' : '}';
  let depth = 0, i = start, inStr = false, esc = false, q = '';
  for (; i < html.length; i++) {
    const ch = html[i];
    if (inStr) { if (esc) esc = false; else if (ch === '\\') esc = true; else if (ch === q) inStr = false; }
    else if (ch === '"' || ch === "'") { inStr = true; q = ch; }
    else if (ch === open) depth++;
    else if (ch === close) { depth--; if (depth === 0) { i++; break; } }
  }
  // Harden inline-script injection (H2): a baked DB string containing "</script>" (or a raw U+2028/U+2029 line
  // separator) would otherwise break out of the inline <script> and inject HTML into every staff page load. The
  // injected value is JSON, which only emits these characters INSIDE string values, so unicode-escaping them keeps
  // the decoded value byte-identical while making break-out impossible.
  const safe = String(jsonText).replace(/</g, '\\u003c').replace(/>/g, '\\u003e').replace(/\u2028/g, '\\u2028').replace(/\u2029/g, '\\u2029');
  return html.slice(0, start) + safe + html.slice(i);
}

// Latest change across the ETL-fed SOURCE data that gets BAKED into the page (and is otherwise frozen for an
// open tab): sales, inventory/products, on-order/inbound, Flexport. Deliberately EXCLUDES user-edited tables
// (forecast_inputs, purchase_orders, deposits) — their updated_at bumps on the user's own edits, which would
// otherwise force a reload on every edit. Drives EXTRACT_TS + the client's data-freshness auto-reload.
async function freshness() {
  const SRC = { sales_actuals: 'loaded_at', products: 'updated_at', inbound_shipments: 'updated_at', flexport_shipments: 'updated_at' };
  try {
    const have = (await pool.query(`SELECT table_name, column_name FROM information_schema.columns
      WHERE table_schema='planner' AND table_name=ANY($1) AND column_name=ANY($2)`,
      [Object.keys(SRC), [...new Set(Object.values(SRC))]])).rows;
    const parts = Object.keys(SRC).filter(t => have.some(r => r.table_name === t && r.column_name === SRC[t]))
      .map(t => `SELECT max(${SRC[t]}) ts FROM planner.${t}`);
    if (!parts.length) return null;
    const { rows } = await pool.query(`SELECT max(ts) AS ts FROM (${parts.join(' UNION ALL ')}) x`);
    return rows[0].ts ? new Date(rows[0].ts).toISOString() : null;
  } catch (e) { return null; }
}
// 60s-cached freshness for the frequently-polled /api/version (avoids re-scanning on every client poll).
let _freshCache = { at: 0, val: null };
async function freshnessCached() {
  const now = Date.now();
  if (now - _freshCache.at < 60000) return _freshCache.val;
  _freshCache = { at: now, val: await freshness() };
  return _freshCache.val;
}

// The plan's subcategory rows are driven by AVAILABILITY (v_product_availability), not just sales history — so an
// available-but-never-sold subcategory (e.g. a Non-Core line only sold in one market) still shows in every market
// it's available. Sales history (category_sales_summary) fills the month cells where it exists. SKUs/subcats with no
// category/subcategory (or the view's 'Unknown') roll up under a synthetic "Undefined sub category" (the client
// sorts it to the top). (Ben, v26.833.)
const UNDEF_SUBCAT = 'Undefined sub category';
function _normCat(v) { const t = (v == null ? '' : String(v).trim()); return (t === '' || t === 'Unknown') ? UNDEF_SUBCAT : t; }
// Non-SKUs / data artefacts that must never appear in the planner (Ben: GIFTWRAP-BOX is not a real SKU). Excluded at the
// data-load queries below. The complete fix is removing them from the PIM; this is a hard guard so they can't leak through.
const NON_SKUS = ['GIFTWRAP-BOX', 'FAIRE-COMMISSION'];   // FAIRE-COMMISSION is a commission line, not a product (Ben, 26-Aug)
const NON_SKU_LIST = NON_SKUS.map(s => `'${String(s).replace(/'/g, "''")}'`).join(',');
// Erroneous POs that must never be treated as inbound / on-order (bad Cin7 data: PO-56UKXR2A carries ~10.7k phantom
// unreceived units into uk_3pl; its sibling PO-56UKXR2 is COMPLETE). Hard-coded exclude at the data-load queries (Ben, 26-Aug).
const EXCLUDED_INBOUND_REFS = ['PO-56UKXR2', 'PO-56UKXR2A'];
const EXCL_REF_LIST = EXCLUDED_INBOUND_REFS.map(s => `'${String(s).replace(/'/g, "''")}'`).join(',');
async function buildDATA() {
  const [salesR, availR] = await Promise.all([
    pool.query(`SELECT category c, subcategory s, country co, channel ch,
                       is_excluded_category x, to_char(month,'YYYY_MM') ym, units::int u, revenue::float r
                FROM planner.category_sales_summary WHERE subcategory IS NOT NULL`),
    // one row per (category, subcategory, country, channel) that has ≥1 AVAILABLE SKU in planning scope
    pool.query(`SELECT DISTINCT p.category c, p.subcategory s, upper(a.country) co, a.channel ch
                FROM planner.v_product_availability a JOIN planner.products p ON p.sku = a.sku
                WHERE a.available_no_disc AND p.in_planning_scope AND p.sku NOT IN (${NON_SKU_LIST})`),
  ]);
  const byKey = {};
  for (const row of salesR.rows) {
    const c = _normCat(row.c), s = _normCat(row.s), k = c + '|' + s + '|' + row.co + '|' + row.ch;
    if (!byKey[k]) byKey[k] = { c, s, co: row.co, ch: row.ch, x: row.x, m: {} };
    byKey[k].m[row.ym] = [row.u, row.r];
  }
  for (const row of availR.rows) {   // available but unsold → add the row with an empty history so it still shows
    const c = _normCat(row.c), s = _normCat(row.s), k = c + '|' + s + '|' + row.co + '|' + row.ch;
    if (!byKey[k]) byKey[k] = { c, s, co: row.co, ch: row.ch, x: false, m: {} };
  }
  return Object.values(byKey);
}

// value_raw is the raw IV string the user typed: a growth decimal ("0.3"), an absolute
// (">=4"), or an apostrophe-prefixed literal ("'2"). FC_CURRENT bakes the *encoded number*
// that FC_SEED -> IV decodes back to that string (the .0001 sentinel marks small literals).
// This mirrors buildSavePayload()'s save-encoding exactly so the artefact round-trips unchanged.
function encodeRaw(raw) {
  if (raw == null) return null;
  const s = String(raw);
  if (s.charAt(0) === "'") {
    const n = parseInt(s.slice(1), 10);
    if (!isNaN(n)) return n >= 4 ? n : (n + 0.0001);
  }
  const f = parseFloat(s);
  return isNaN(f) ? null : f;
}

async function buildFC_CURRENT() {
  const { rows } = await pool.query(`
    SELECT subcategory s, country co, channel ch, to_char(month,'YYYY_MM') ym, value_raw
    FROM planner.forecast_inputs`);
  const out = {};
  for (const row of rows) {
    const v = encodeRaw(row.value_raw);
    if (v == null) continue;
    const k = row.s + '|' + row.co + '|' + row.ch;
    if (!out[k]) out[k] = {};
    out[k][row.ym] = v;
  }
  return out;
}

// SKU-level forecast: rebuild FC_OUTPUTS {"sku|warehouse|channel":{ym:units}} from
// planner.forecast_outputs (the editable SKU plan). Mirrors the baked global's shape.
async function buildFC_OUTPUTS() {
  const { rows } = await pool.query(`
    SELECT sku, warehouse wh, channel ch, to_char(month,'YYYY_MM') ym, units::int u
    FROM planner.forecast_outputs`);
  const out = {};
  for (const row of rows) {
    const k = row.sku + '|' + row.wh + '|' + row.ch;
    if (!out[k]) out[k] = {};
    out[k][row.ym] = row.u;
  }
  return out;
}

// _SKU_RAW: the keystone SKU global. Three parts (matches the baked shape exactly):
