// Un-allocated "China Stock" holding stock per SKU = qty on open China Stock branch POs (the MOQ top-ups). The buy
// plan flags this as available to allocate. Display-only (does NOT alter buy quantities — allocation is a later step).
async function buildChinaStock() {
  try {
    const r = await pool.query(`SELECT upper(l.sku) sku, sum(l.qty)::int qty
      FROM planner.purchase_order_lines l JOIN planner.purchase_orders p ON p.po=l.po
      WHERE p.branch ILIKE 'China Stock' AND coalesce(p.status,'') NOT ILIKE '%complete%' AND coalesce(l.qty,0)>0
      GROUP BY upper(l.sku)`);
    const o = {}; r.rows.forEach(x => { o[x.sku] = Number(x.qty) || 0; }); return o;
  } catch (e) { return {}; }
}
// Zalando (ZFS) stock-on-hand from the uploaded inventory file → {sku: qty}. Keyed by the raw SKU (same source as
// ZAL_FC), so ZAL_STOCK[sku] lines up with the Zalando forecast keys. Empty ⇒ Zalando buy-feed stays OFF.
async function buildZalStock() {
  try {
    const r = await pool.query(`SELECT sku, sum(qty)::int qty FROM planner.zalando_stock WHERE coalesce(qty,0)>0 GROUP BY sku`);
    const o = {}; r.rows.forEach(x => { o[x.sku] = Number(x.qty) || 0; }); return o;
  } catch (e) { return {}; }
}
// Zalando forecast from the DB (forecast_outputs, channel ZAL) → {sku:{YYYY_MM:units}}. Replaces the baked
// zalando_data.json map — the Zalando forecast is now stored in Supabase like DTC/FBA (Ben, 2026-08-08).
async function buildZalFc() {
  try {
    const r = await pool.query(`SELECT sku, to_char(month,'YYYY_MM') ym, units::int u FROM planner.forecast_outputs WHERE channel='ZAL' AND units IS NOT NULL`);
    const fc = {}; r.rows.forEach(x => { (fc[x.sku] || (fc[x.sku] = {}))[x.ym] = x.u; }); return fc;
  } catch (e) { return {}; }
}
// EU Zalando channel scope: SKUs we track Zalando stock for (the upload) ∪ SKUs with a ZAL forecast.
async function buildZalSkus() {
  try {
    const r = await pool.query(`SELECT DISTINCT sku FROM planner.zalando_stock UNION SELECT DISTINCT sku FROM planner.forecast_outputs WHERE channel='ZAL'`);
    return r.rows.map(x => x.sku);
  } catch (e) { return []; }
}
// Modular channel registry (planner.channels + channel_countries) → array with a countries[] each. Phase 1: injected
// but not yet read by the app logic (see Claude Analyses/MODULAR_CHANNELS_ANALYSIS.md). Powers CONFIG▸Admin▸Channels.
async function buildChannels() {
  try {
    const ch = (await pool.query(`SELECT code,label,stock_source,forecast_mode,cover_months,ext_stock_source,sku_scope,rt_factor,no_urgent,sort,active FROM planner.channels ORDER BY sort,code`)).rows;
    const cc = (await pool.query(`SELECT channel_code, country_code FROM planner.channel_countries`)).rows;
    const byCh = {}; cc.forEach(r => (byCh[r.channel_code] || (byCh[r.channel_code] = [])).push(r.country_code));
    ch.forEach(c => { c.countries = (byCh[c.code] || []).sort(); c.cover_months = c.cover_months != null ? Number(c.cover_months) : null; c.rt_factor = c.rt_factor != null ? Number(c.rt_factor) : null; });
    return ch;
  } catch (e) { return []; }
}
async function buildCountries() {
  try { return (await pool.query(`SELECT code,label,sort,active FROM planner.countries ORDER BY sort,code`)).rows; }
  catch (e) { return []; }
}
