  if ((Number(l.qty_shipped) || 0) > 0 || l.move_done) return 'Line already shipped';
  if (pr && pr.purchase_line) return 'Already on purchase order ' + (pr.po_number || ('#' + pr.purchase)) + ' (' + (pr.po_state || pr.state) + '): change it on the PO in Fulfil';
