// ── PRICE LISTS (SUPPLY ▸ Purchase Orders ▸ Price Lists) ─────────────────────────────────────────────
// Cost price per product × supplier, grouped by products.price_type (type-level base + per-SKU exceptions),
// with quantity tiers and "from production N" versioning. Supplier-portal submissions arrive as status='pending'.
async function plAdminData() {
    const entries = (await pool.query(`
      SELECT e.id, e.supplier, e.scope, coalesce(e.price_type,'') price_type, coalesce(e.sku,'') sku,
             e.currency, e.effective_from_production, e.status, e.source, coalesce(e.note,'') note,
             coalesce(e.submitted_by,'') submitted_by, to_char(e.submitted_at,'YYYY-MM-DD HH24:MI') submitted_at,
             coalesce(e.approved_by,'') approved_by,
             coalesce((SELECT json_agg(json_build_object('min_qty',t.min_qty,'unit_cost',t.unit_cost) ORDER BY t.min_qty)
                       FROM planner.price_list_tiers t WHERE t.entry_id=e.id),'[]') tiers
      FROM planner.price_list_entries e
      WHERE e.status IN ('active','pending')
      ORDER BY e.price_type, e.scope DESC, e.sku, e.supplier`)).rows;
    // supplier columns = active suppliers (so admin can add a price for any), currency from suppliers
    const suppliers = (await pool.query(`SELECT name, coalesce(default_currency,'USD') currency FROM planner.suppliers WHERE coalesce(active,true) ORDER BY name`)).rows;
    // ONLY variant_type='MASTER' (SETs + variant children excluded), minus the user-managed exclude list.
    const excluded = (await pool.query(`SELECT sku FROM planner.price_list_excluded_skus ORDER BY sku`)).rows.map(r => r.sku);
    const exclSet = new Set(excluded);
    const pt = (await pool.query(`SELECT coalesce(price_type,'') price_type, sku, coalesce(product_name_final,product_name,'') name,
             coalesce(nullif(category_name_final,''),category,'') category,
             coalesce(main_supplier_final,'') main_supplier, coalesce(supplier_multiple_all,'') multi, cost,
             coalesce(colour_long,'') colour, coalesce(nullif(size_long,''),size,'') size,
             (lower(coalesce(status,'')) NOT LIKE '%discont%' AND NOT (coalesce(discontinue_date_final,'') ~ '^\d{4}-\d{2}-\d{2}' AND to_date(discontinue_date_final,'YYYY-MM-DD') <= current_date)) active
      FROM planner.products WHERE coalesce(sku,'')<>'' AND coalesce(variant_type,'')='MASTER' AND upper(coalesce(status,''))<>'NON STOCKED'
        AND upper(coalesce(price_type,''))<>'NA' ORDER BY price_type, sku`)).rows
      .filter(r => !exclSet.has(r.sku));
    // suppliers a SKU can be bought from, per planner.products (main_supplier_final + supplier_multiple_all)
    const supListOf = (main, multi) => { const seen = {}, out = [];
      [main].concat(String(multi || '').split(',')).map(x => String(x || '').trim()).filter(Boolean)
        .forEach(nm => { const k = nm.toLowerCase(); if (!seen[k]) { seen[k] = 1; out.push(nm); } }); return out; };
    const ptMeta = {}; (await pool.query(`SELECT price_type, coalesce(size,'') size FROM planner.price_type_meta`)).rows.forEach(r => { ptMeta[r.price_type] = r.size; });
    // MANUAL / no price_type → per-SKU pricing, shown grouped by supplier at the bottom (no type inherit)
    const isManual = (v) => (v === '' || String(v).toUpperCase() === 'MANUAL');
    const typeMap = {}, manualSkus = [];
    const num = v => { const n = Number(v); return isFinite(n) && n > 0 ? n : null; };
    const modeCost = arr => { const c = {}; arr.forEach(v => { if (v != null) c[v] = (c[v] || 0) + 1; }); const k = Object.keys(c).sort((a, b) => c[b] - c[a])[0]; return k != null ? Number(k) : null; };
    pt.forEach(r => {
      const sups = supListOf(r.main_supplier, r.multi), cost = num(r.cost);
      if (isManual(r.price_type)) { manualSkus.push({ sku: r.sku, name: r.name, active: !!r.active, colour: r.colour, size: r.size, category: r.category, main_supplier: r.main_supplier, suppliers: sups, cost, price_type: r.price_type }); return; }
      const t = (typeMap[r.price_type] = typeMap[r.price_type] || { skus: [], mc: {}, sizes: {}, cats: {}, sc: {}, costs: [] }); t.skus.push({ sku: r.sku, name: r.name, active: !!r.active, colour: r.colour, size: r.size, category: r.category, main_supplier: r.main_supplier, suppliers: sups, cost }); if (r.main_supplier) t.mc[r.main_supplier] = (t.mc[r.main_supplier] || 0) + 1; sups.forEach(nm => t.sc[nm] = (t.sc[nm] || 0) + 1); if (cost != null) t.costs.push(cost); if (r.size) t.sizes[r.size] = 1; if (r.category) t.cats[r.category] = (t.cats[r.category] || 0) + 1;
    });
    const priceTypes = Object.keys(typeMap).sort().map(k => { const t = typeMap[k]; const main = Object.keys(t.mc).sort((a, b) => t.mc[b] - t.mc[a])[0] || '';
      const prodSuppliers = Object.keys(t.sc).sort((a, b) => t.sc[b] - t.sc[a] || (a < b ? -1 : 1));   // suppliers from products, dominant first (= the columns)
      const seedCost = modeCost(t.costs);   // representative generic product cost for the type (seed source)
      const uniq = Object.keys(t.sizes); const defaultSize = uniq.length === 1 ? uniq[0] : '';   // common SKU size only when uniform
      const category = Object.keys(t.cats).sort((a, b) => t.cats[b] - t.cats[a])[0] || '';   // dominant category across the type's SKUs
      const override = (ptMeta[k] != null && ptMeta[k] !== '');
      return { price_type: k, skus: t.skus, category, mainSupplier: main, prodSuppliers, seedCost, size: override ? ptMeta[k] : defaultSize, sizeOverride: override, sizeDefault: defaultSize }; });
    // current production = latest IN-PRODUCTION number; the "from production" picker offers this + higher (future only)
    const cpRow = (await pool.query(`SELECT max(regexp_replace(prod_no,'[^0-9]','','g')::int) mx FROM planner.purchase_orders
      WHERE lower(coalesce(status,'')) LIKE '%production%' AND regexp_replace(coalesce(prod_no,''),'[^0-9]','','g')<>''`)).rows[0];
    const currentProduction = (cpRow && cpRow.mx) ? cpRow.mx : 0;
    const prods = (await pool.query(`SELECT prod_no FROM planner.prod_numbers WHERE coalesce(status,'')='ACTIVE'`)).rows
      .map(r => parseInt(String(r.prod_no).replace(/[^0-9]/g, ''), 10)).filter(n => !isNaN(n) && n >= currentProduction).sort((a, b) => b - a);   // future productions from the productions table
    const pending = entries.filter(e => e.status === 'pending').length;
    return { entries, suppliers, priceTypes, manualSkus, excluded, productions: [...new Set(prods)], currentProduction, pending };
}
app.get('/api/supply/price-list', async (_req, res) => {
  try { res.json(await plAdminData()); } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// Build a 2-sheet XLSX (Price types · SKUs) from a price-list data object (shared by admin + portal export).
async function plXlsxBuffer(data) {
  const ExcelJS = (await import('exceljs')).default;
  const entries = data.entries || [], priceTypes = data.priceTypes || [], manualSkus = data.manualSkus || [], curProd = data.currentProduction || 0;
  const byKey = {}; entries.forEach(e => { const k = e.supplier + '|' + e.scope + '|' + (e.scope === 'sku' ? e.sku : e.price_type); (byKey[k] = byKey[k] || []).push(e); });
  const curOf = (list) => { if (!list || !list.length) return null; const act = list.filter(e => e.status === 'active'); let p2 = act.filter(e => e.effective_from_production == null || e.effective_from_production <= curProd); if (!p2.length) p2 = act.filter(e => e.effective_from_production == null); let pick = null; p2.slice().sort((a, b) => (a.effective_from_production || 0) - (b.effective_from_production || 0)).forEach(e => pick = e); return pick; };
  const tl = (e) => (e && e.tiers && e.tiers.length) ? e.tiers.slice().sort((a, b) => a.min_qty - b.min_qty) : [];
  const tiersStr = (e) => tl(e).map(t => t.min_qty + ':' + Number(t.unit_cost)).join(' | ');
  const baseCost = (e) => { const t = tl(e); return t.length ? Number(t[0].unit_cost) : null; };
  const wb = new ExcelJS.Workbook(); wb.creator = 'HORIZON';
  const ptS = wb.addWorksheet('Price types');
  ptS.columns = [{ header: 'Price type', width: 26 }, { header: 'Category', width: 20 }, { header: 'Size', width: 12 },
    { header: 'Supplier', width: 22 }, { header: 'Currency', width: 9 }, { header: 'From production', width: 14 },
    { header: 'Base unit cost', width: 13 }, { header: 'Price tiers (qty:cost)', width: 30 }];
  priceTypes.forEach(t => { const pt = t.price_type; const supSet = {}; entries.forEach(e => { if (e.price_type === pt && e.scope === 'type' && e.status === 'active') supSet[e.supplier] = 1; });
    Object.keys(supSet).sort().forEach(sup => { const use = curOf(byKey[sup + '|type|' + pt]); if (!use) return;
      ptS.addRow([pt, t.category || '', t.size || '', sup, use.currency || '', use.effective_from_production || 'current', baseCost(use), tiersStr(use)]); }); });
  const skS = wb.addWorksheet('SKUs');
  skS.columns = [{ header: 'Price type', width: 22 }, { header: 'Category', width: 20 }, { header: 'SKU', width: 24 },
    { header: 'Product', width: 34 }, { header: 'Size', width: 12 }, { header: 'Colour', width: 16 },
    { header: 'Supplier', width: 22 }, { header: 'Currency', width: 9 }, { header: 'From production', width: 14 },
    { header: 'Base unit cost', width: 13 }, { header: 'Price tiers (qty:cost)', width: 30 }, { header: 'Price source', width: 18 }];
  priceTypes.forEach(t => { const pt = t.price_type; const supSet = {}; entries.forEach(e => { if (e.price_type === pt && e.status === 'active') supSet[e.supplier] = 1; }); const sups = Object.keys(supSet).sort();
    (t.skus || []).forEach(s => { sups.forEach(sup => { const ov = curOf(byKey[sup + '|sku|' + s.sku]), base = curOf(byKey[sup + '|type|' + pt]), use = ov || base; if (!use) return;
      skS.addRow([pt, s.category || t.category || '', s.sku, s.name || '', s.size || '', s.colour || '', sup, use.currency || '', use.effective_from_production || 'current', baseCost(use), tiersStr(use), ov ? 'SKU price' : 'inherited type price']); }); }); });
  manualSkus.forEach(s => { const sup = s.main_supplier || ''; const use = sup ? curOf(byKey[sup + '|sku|' + s.sku]) : null; if (!use) return;
    skS.addRow([s.price_type || 'MANUAL', s.category || '', s.sku, s.name || '', s.size || '', s.colour || '', sup, use.currency || '', use.effective_from_production || 'current', baseCost(use), tiersStr(use), 'SKU price']); });
  [ptS, skS].forEach(ws => { ws.getRow(1).font = { bold: true }; ws.views = [{ state: 'frozen', ySplit: 1 }]; });
  return await wb.xlsx.writeBuffer();
}
app.get('/api/supply/price-list/export.xlsx', async (_req, res) => {
  try { const buf = await plXlsxBuffer(await plAdminData());
    res.set('Content-Type', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')
       .set('Content-Disposition', 'attachment; filename="price-list.xlsx"').set('Cache-Control', 'no-store').send(Buffer.from(buf));
  } catch (e) { log500(e); res.status(500).send('export error: ' + e.message); }
});
// Inventory Status Report — full-page XLSX. Client posts the already-computed blocks (title/colour/headers/rows,
// all plain text) so the calc stays client-side (authoritative); the server just formats: coloured section-title
// bars, bold header rows, everything left-aligned, and the Core/Seasonal cell tinted by its classification.
app.post('/api/supply/inventory-status/export.xlsx', async (req, res) => {
  try {
    const ExcelJS = (await import('exceljs')).default;
    const { market = '', blocks = [] } = req.body || {};
    const wb = new ExcelJS.Workbook(); wb.creator = 'HORIZON';
    const ws = wb.addWorksheet(('Inventory ' + market).slice(0, 31));
    let maxCols = 1; blocks.forEach(b => { maxCols = Math.max(maxCols, (b.h || []).length); });
    ws.columns = Array.from({ length: maxCols }, (_, i) => ({ width: i === 1 ? 26 : (i === 0 ? 9 : 15) }));
    const left = { horizontal: 'left' };
    const csFill = (txt) => { const t = String(txt || '').toLowerCase(); if (t.includes('season')) return 'FFDCFCE7'; if (t.includes('non')) return 'FFFFEDD5'; if (t.includes('core')) return 'FFDBEAFE'; return null; };
    blocks.forEach(b => {
      const nc = Math.max(1, (b.h || []).length);
      const tr = ws.addRow([b.title || '']); tr.font = { bold: true, color: { argb: 'FF' + (b.fg || '0F172A') } };
      tr.getCell(1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF' + (b.bg || 'F1F5F9') } };
      tr.getCell(1).alignment = left; ws.mergeCells(tr.number, 1, tr.number, nc);
      const hr = ws.addRow(b.h || []); hr.font = { bold: true };
      hr.eachCell(c => { c.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFF1F5F9' } }; c.alignment = left; });
      (b.rows || []).forEach(rw => { const r = ws.addRow(rw); r.eachCell((c, ci) => { c.alignment = left;
        const hName = (b.h || [])[ci - 1] || '';
        if (/core\/seasonal/i.test(hName)) { const f = csFill(c.value); if (f) c.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: f } }; }
        if (/^status$/i.test(hName) && /discontinu/i.test(String(c.value || ''))) c.font = { color: { argb: 'FFB91C1C' } };
      }); });
      ws.addRow([]);
    });
    ws.views = [{ state: 'frozen', ySplit: 0 }];
    const buf = await wb.xlsx.writeBuffer();
    res.set('Content-Type', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')
       .set('Content-Disposition', 'attachment; filename="inventory_' + (market || 'report') + '.xlsx"').set('Cache-Control', 'no-store').send(Buffer.from(buf));
  } catch (e) { log500(e); res.status(500).send('export error: ' + e.message); }
});

// ── EDI LABELS (Dillards via EZY COM) — split SSCC label PDFs into SUPPLIER/PO/SKU folders ──────────────
// wc-asn.csv (no header): col4 = "<PO>-<store>", col107 (DC) = client SKU, col108 (DD) = our EAN, col129 = SSCC.
// Each uploaded PDF = one PO, one SSCC label per page. Match a page's SSCC (last 18 digits) → CSV row → PO +
// EAN → our SKU + supplier(s); split each page to its own PDF filed under SUPPLIER/PO/SKU. Read-only (no DB write).
// STATELESS: parse (preview) and generate (build) each re-parse from the request's own files — no cross-request
// cache, so it works on serverless / Vercel (Diviyaj). The PDF re-parse is cheap enough for D&B's volumes.
// Quote-aware CSV split (RFC4180): respects double-quoted fields that contain commas (Dillards ASNs have them in
// routing/address columns), so column indices stay aligned. A naive line.split(',') shifted the SSCC column for
// those rows → false "SSCC not in CSV". Also strips a leading/trailing apostrophe text-qualifier.
function _ediCsvSplit(line) {
  const out = []; let cur = '', q = false;
  for (let i = 0; i < line.length; i++) { const ch = line[i];
    if (q) { if (ch === '"') { if (line[i + 1] === '"') { cur += '"'; i++; } else q = false; } else cur += ch; }
    else { if (ch === '"') q = true; else if (ch === ',') { out.push(cur); cur = ''; } else cur += ch; } }
  out.push(cur);
  return out.map(s => s.replace(/^'|'$/g, '').trim());
}
function _ediBody(b) {
  const csvText = b.csv_base64 ? Buffer.from(String(b.csv_base64), 'base64').toString('utf8') : String(b.csv || '');
  const pdfs = Array.isArray(b.pdfs) ? b.pdfs : [];
  return { csvText, pdfs };
}
// Parse the ASN CSV + label PDFs into per-page items (each with its split single-page PDF buffer).
async function _ediParse(csvText, pdfs) {
  // 1) CSV → SSCC(last 18) → { po, store, clientSku, ean, qty }
  const bySscc = {}; const eans = new Set();
  csvText.split(/\r?\n/).filter(Boolean).forEach(line => {
    const c = _ediCsvSplit(line);
    const ps = c[3] || ''; const po = ps.split('-')[0]; const store = ps.split('-')[1] || '';
    const clientSku = c[106] || ''; const ean = String(c[107] || '').replace(/\D/g, ''); const sscc = String(c[128] || '').replace(/\D/g, '');
    const qty = parseInt(String(c[110] || '').replace(/\D/g, ''), 10) || 0;   // col 111 = carton qty per SSCC
    if (!sscc) return; bySscc[sscc.slice(-18)] = { po, store, clientSku, ean, sscc, qty };
    if (ean) eans.add(ean);
  });
  // 2) EAN → our SKU + supplier(s)
  const byEan = {};
  if (eans.size) {
    const { rows } = await pool.query(
      `SELECT replace(coalesce(product_ean,''),chr(39),'') ean, sku,
              coalesce(nullif(main_supplier_final,''),nullif(supplier,'')) main_supplier, supplier_multiple_all
       FROM planner.products WHERE replace(coalesce(product_ean,''),chr(39),'') = ANY($1)`, [[...eans]]);
    rows.forEach(r => {
      const opts = [...new Set(String(r.supplier_multiple_all || '').split(',').map(s => s.trim()).filter(Boolean).concat(r.main_supplier ? [r.main_supplier] : []))];
      byEan[r.ean] = { sku: r.sku, mainSupplier: r.main_supplier || opts[0] || '', suppliers: opts.length ? opts : (r.main_supplier ? [r.main_supplier] : []) };
    });
  }
  // 3) each PDF → per-page SSCC (text) → split page into its own PDF (pdf-lib)
  const pdfjs = await import('pdfjs-dist/legacy/build/pdf.mjs');
  const { PDFDocument } = await import('pdf-lib');
  const items = []; let skippedNoSscc = 0;
  for (const f of pdfs) {
    if (!f || (!f.b64 && !f.base64 && !f.storage_path)) continue;
    // Each label PDF arrives inline (b64) or already in Storage (storage_path + sig) — the big files go direct-to-Storage.
    let buf; try { buf = await resolveUploadBytes({ data_base64: f.b64 || f.base64, storage_path: f.storage_path, storage_sig: f.storage_sig }, { maxInline: 20 * 1024 * 1024 }); } catch (e) { continue; }
    if (!buf.length) continue;
    let src, doc;
    try { src = await PDFDocument.load(buf, { ignoreEncryption: true }); } catch (e) { continue; }
    try { doc = await pdfjs.getDocument({ data: new Uint8Array(buf), useSystemFonts: true }).promise; } catch (e) { continue; }
    for (let pg = 1; pg <= doc.numPages; pg++) {
      const p = await doc.getPage(pg); const tc = await p.getTextContent();
      const text = tc.items.map(i => i.str).join(' ');
      let extracted = null, key = null; const m = text.match(/\(00\)\s*([\d\s]{18,30})/);
      if (m) extracted = m[1].replace(/\D/g, '').slice(0, 18);
      if (extracted && bySscc[extracted]) key = extracted;
      else { const digits = text.replace(/\D/g, ''); for (const k in bySscc) { if (digits.includes(k)) { key = k; break; } } }
      const sscc = key || extracted;
      if (!sscc) { skippedNoSscc++; continue; }   // page has no SSCC label at all → skip it silently (not counted, not in the ZIP, never an error). (Ben)
      const row = key ? bySscc[key] : null;
      const prod = row && row.ean ? byEan[row.ean] : null;
      const out = await PDFDocument.create(); const [cp] = await out.copyPages(src, [pg - 1]); out.addPage(cp);
      const pageBuf = Buffer.from(await out.save());
      const matched = !!(row && prod);
      const reason = matched ? '' : (!row ? 'SSCC not in CSV' : ('EAN ' + (row.ean || '?') + ' not matched to a product'));
      items.push({ sscc: sscc, po: row ? row.po : '', store: row ? row.store : '', clientSku: row ? row.clientSku : '',
        ean: row ? row.ean : '', qty: row ? (row.qty || 0) : 0, sku: prod ? prod.sku : '', suppliers: prod ? prod.suppliers : [], mainSupplier: prod ? prod.mainSupplier : '',
        matched, reason, srcFile: f.name || '', buf: pageBuf });
    }
  }
  items.skippedNoSscc = skippedNoSscc;   // pages with no SSCC label at all — silently skipped (info only, never an error)
  return items;
}
function _ediPreview(items) {
  const skuMap = {};
  items.forEach(it => { if (!it.matched) return; (skuMap[it.sku] = skuMap[it.sku] || { sku: it.sku, options: it.suppliers, main: it.mainSupplier, count: 0 }).count++; });
  const skus = Object.values(skuMap).sort((a, b) => a.sku.localeCompare(b.sku));
  const byPo = {}; items.forEach(it => { if (it.matched) byPo[it.po] = (byPo[it.po] || 0) + 1; });
  return {
    ok: true, total: items.length, matched: items.filter(i => i.matched).length,
    unmatched: items.filter(it => !it.matched).map(it => ({ sscc: it.sscc, po: it.po, clientSku: it.clientSku, ean: it.ean, reason: it.reason, file: it.srcFile })),
    multiSuppliers: skus.filter(x => (x.options || []).length > 1),
    skippedNoSscc: items.skippedNoSscc || 0,   // pages with no SSCC — skipped silently (surfaced as info, not an error)
    skus, byPo,
  };
}
app.post('/api/supply/edi-labels/parse', async (req, res) => {
  try {
    const { csvText, pdfs } = _ediBody(req.body || {});
    if (!csvText.trim()) return res.status(400).json({ error: 'No CSV supplied' });
    if (!pdfs.length) return res.status(400).json({ error: 'No PDF files supplied' });
    res.json(_ediPreview(await _ediParse(csvText, pdfs)));
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
app.post('/api/supply/edi-labels/generate', async (req, res) => {
  try {
    const b = req.body || {};
    const { csvText, pdfs } = _ediBody(b);
    if (!csvText.trim() || !pdfs.length) return res.status(400).json({ error: 'Re-send the CSV + PDFs to generate.' });
    const items = await _ediParse(csvText, pdfs);
    const job = { items };
    const choices = b.choices || {}, refs = b.preorderRefs || {};
    const asEntries = !!b.as_entries;   // batched large sets: return split PDFs as JSON so the client assembles ONE ZIP (beats Vercel's ~4.5MB body cap)
    const san = s => String(s == null ? '' : s).replace(/[\/\\:*?"<>|\x00-\x1f]+/g, '_').replace(/\s+/g, ' ').trim().replace(/[. ]+$/, '') || '_';
    // Build the split entries + manifest rows + packing rows once, then either ZIP them (single request) or return
    // them as JSON (batched — the caller passes as_entries=true, dedupes paths ACROSS batches, and builds the ZIP).
    const fileEntries = [], manifestRows = [], packRows = [];
    const seen = {};
    job.items.forEach(it => {
      let path, supplier = '', ref = '';
      if (it.matched) {
        supplier = choices[it.sku] || it.mainSupplier || 'UNKNOWN_SUPPLIER';
        ref = String(refs[it.po] || '').trim();
        const poFolder = ref ? san(it.po + ' - ' + ref) : san(it.po);   // matches the proven <PO> - <PREORDER REF> layout
        path = san(supplier) + '/' + poFolder + '/' + san(it.sku) + '/' + san(it.sscc) + '.pdf';
      } else {
        const sub = it.reason === 'SSCC not in CSV' ? '_SSCC_NOT_IN_CSV' : (/EAN/.test(it.reason) ? '_EAN_NOT_MATCHED' : '_NO_SSCC_FOUND');
        path = '_UNMATCHED/' + sub + '/' + san(it.sscc) + '.pdf';
      }
      if (!asEntries) { if (seen[path]) { const n = ++seen[path]; path = path.replace(/\.pdf$/i, '_' + n + '.pdf'); } else seen[path] = 1; }   // single-request: dedupe here. Batched: client dedupes across batches.
      fileEntries.push({ path, buf: it.buf });
      manifestRows.push([it.sscc, it.po, ref, it.store, it.clientSku, it.ean, it.sku, supplier, it.matched ? 'yes' : ('no (' + it.reason + ')'), path]);
      if (it.matched) packRows.push([supplier, it.po, ref, it.sku, it.qty || '', it.sscc]);
    });
    if (asEntries) {   // batched mode: hand back this batch's pieces; the client merges + zips
      return res.set('Cache-Control', 'no-store').json({
        entries: fileEntries.map(f => ({ path: f.path, b64: f.buf.toString('base64') })),
        manifest: manifestRows, pack: packRows });
    }
    const JSZip = (await import('jszip')).default; const zip = new JSZip();
    const q = v => { v = String(v == null ? '' : v); return /[",\n]/.test(v) ? '"' + v.replace(/"/g, '""') + '"' : v; };
    fileEntries.forEach(f => zip.file(f.path, f.buf));
    zip.file('manifest.csv', [['sscc', 'po', 'preorder_ref', 'store', 'client_sku', 'ean', 'our_sku', 'supplier', 'matched', 'path']].concat(manifestRows).map(r => r.map(q).join(',')).join('\n') + '\n');
    const packBy = {}; packRows.forEach(r => { (packBy[r[0]] = packBy[r[0]] || []).push(r); });
    Object.keys(packBy).forEach(sup => {
      const rows = [['Supplier', 'Purchase Order', 'Preorder Ref', 'SKU', 'Quantity', 'SSCC Label']]
        .concat(packBy[sup].sort((a, b) => String(a[1]).localeCompare(String(b[1])) || String(a[3]).localeCompare(String(b[3])) || String(a[5]).localeCompare(String(b[5]))));
      zip.file(san(sup) + '/packing-list-' + san(sup) + '.csv', rows.map(r => r.map(q).join(',')).join('\n') + '\n');
    });
    const out = await zip.generateAsync({ type: 'nodebuffer', compression: 'DEFLATE' });
    res.set('Content-Type', 'application/zip').set('Content-Disposition', 'attachment; filename="edi-labels.zip"').set('Cache-Control', 'no-store').send(out);
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});

// EDI ▸ Step 7b — build the Cin7 sales-order upload CSV from the ASN alone (no PDFs). level 'po' = one order per PO
// (DILLARDS-<PO>); level 'store' = one order per PO-store (DILLARDS-<PO>-<store>) with price. Item Code via EAN→SKU,
// price = us_rt/2 (store level only), qty = summed units per line (SKUs summing to 0 are dropped). Read-only.
app.post('/api/supply/edi-labels/sales-orders', async (req, res) => {
  try {
    const b = req.body || {};
    // POST PACK document = the ASN (wc-asn) CSV. Optional PREPACK document = the EZCOM PO-detail CSV that carries a
    // per-SKU UnitPrice keyed by UPCCode; when supplied, the by-store item price comes from it (matched on UPC),
    // falling back to us_rt/2 for any UPC not in the PREPACK. (Ben)
    const csvText = b.csv_base64 ? Buffer.from(String(b.csv_base64), 'base64').toString('utf8') : String(b.csv || '');
    const prepackText = b.prepack_base64 ? Buffer.from(String(b.prepack_base64), 'base64').toString('utf8') : String(b.prepack || '');
    const level = (b.level === 'po') ? 'po' : 'store';
    if (!csvText.trim()) return res.status(400).json({ error: 'No POST PACK (ASN) CSV supplied' });
    // Build UPC → UnitPrice map from the PREPACK document (header-driven: UPCCode + UnitPrice columns).
    const prepackByUpc = {};
    if (prepackText.trim()) {
      const plines = prepackText.split(/\r?\n/).filter(Boolean);
      const phdr = _ediCsvSplit(plines[0] || []);
      const iUpc = phdr.indexOf('UPCCode'), iPrice = phdr.indexOf('UnitPrice');
      if (iUpc >= 0 && iPrice >= 0) plines.slice(1).forEach(line => {
        const c = _ediCsvSplit(line);
        const upc = String(c[iUpc] || '').replace(/\D/g, ''); const up = parseFloat(String(c[iPrice] || '').replace(/[^0-9.]/g, ''));
        if (upc && up > 0) prepackByUpc[upc] = up;   // last row wins (all stores carry the same UnitPrice per UPC)
      });
    }
    const havePrepack = Object.keys(prepackByUpc).length > 0;
    // 1) parse ASN rows: PO / store (col4), EAN (col108), qty (col111), ship-to DC block (cols 46/48/51/52/53/54)
    const eans = new Set(); const rows = [];
    csvText.split(/\r?\n/).filter(Boolean).forEach(line => {
      const c = _ediCsvSplit(line);
      const ps = c[3] || ''; const po = ps.split('-')[0]; const store = ps.split('-')[1] || '';
      const ean = String(c[107] || '').replace(/\D/g, ''); const qty = parseInt(String(c[110] || '').replace(/\D/g, ''), 10) || 0;
      if (!po || !ean) return;
      const dc = { name: c[45] || '', addr: c[47] || '', city: c[50] || '', state: c[51] || '', zip: c[52] || '', country: c[53] || '' };
      rows.push({ po, store, ean, qty, dc }); if (ean) eans.add(ean);
    });
    // 2) EAN → SKU + US retail (wholesale price = us_rt/2)
    const byEan = {};
    if (eans.size) (await pool.query(
      `SELECT replace(coalesce(product_ean,''),chr(39),'') ean, sku, us_rt FROM planner.products WHERE replace(coalesce(product_ean,''),chr(39),'') = ANY($1)`, [[...eans]]
    )).rows.forEach(r => { byEan[r.ean] = { sku: r.sku, us_rt: Number(r.us_rt) || 0 }; });
    // 3) aggregate qty per (PO×SKU) or (PO×store×SKU)
    const agg = {};
    rows.forEach(r => { const prod = byEan[r.ean]; if (!prod || !prod.sku) return;
      const key = level === 'po' ? (r.po + '|' + prod.sku) : (r.po + '|' + r.store + '|' + prod.sku);
      if (!agg[key]) agg[key] = { po: r.po, store: r.store, sku: prod.sku, us_rt: prod.us_rt, ean: r.ean, qty: 0, dc: r.dc };
      agg[key].qty += r.qty; });
    const items = Object.values(agg).filter(x => x.qty > 0)   // qty 0 → don't add the SKU (Ben)
      .sort((a, b) => a.po.localeCompare(b.po) || String(a.store).localeCompare(String(b.store)) || a.sku.localeCompare(b.sku));
    const q = v => { v = String(v == null ? '' : v); return /[",\n]/.test(v) ? '"' + v.replace(/"/g, '""') + '"' : v; };
    // Store-file item price: PREPACK UnitPrice (matched on UPC) when supplied, else us_rt/2 fallback.
    const price = it => { const pp = prepackByUpc[it.ean];
      if (pp != null && pp > 0) return pp.toFixed(2);
      return it.us_rt > 0 ? (Math.round(it.us_rt / 2 * 100) / 100).toFixed(2) : ''; };
    let hdr, body;
    if (level === 'po') {
      hdr = ['Order Ref', 'Item Code', 'Company', 'First Name', 'Last Name', 'Phone', 'Delivery Address 1', 'Delivery Address 2', 'Delivery City', 'Delivery State', 'Delivery Postal Code', 'Country', 'Customer PO No', 'Item Qty', 'Item Price', 'Branch', 'Freight Description', 'Freight Cost', 'Project Name', 'Xero Status', 'Stage', 'Alternative GL Account', 'Delivery Instructions', 'Billing Company', 'Email', 'Billing First Name', 'Billing Last Name', 'Billing Address 1', 'Billing Address 2', 'Billing City', 'Billing State', 'Billing Postal Code', 'Billing Country'];
      body = items.map(it => ['DILLARDS-' + it.po, it.sku, 'DILLARDS', it.dc.name, '', '', it.dc.addr, '', it.dc.city, it.dc.state, it.dc.zip, it.dc.country, it.po, it.qty, '', 'US Geneva', 'Labels', '0', 'Shopify USWS', 'Not Imported', 'New', 'COGS - US - Wholesale', 'Crossdock to Geneva then dispatch', '', '', '', '', '', '', '', '', '', '']);
    } else {
      hdr = ['Order Ref', 'Company', 'First Name', 'Last Name', 'Phone', 'Delivery Address 1', 'Delivery Address 2', 'Delivery City', 'Delivery State', 'Delivery Postal Code', 'Country', 'Branch', 'Freight Description', 'Freight Cost', 'Project Name', 'Xero Status', 'Stage', 'Alternative GL Account', 'Customer PO No', 'Delivery Instructions', 'Item Code', 'Item Qty', 'Item Price', 'Billing Company', 'Email', 'Billing First Name', 'Billing Last Name', 'Billing Address 1', 'Billing Address 2', 'Billing City', 'Billing State', 'Billing Postal Code', 'Billing Country'];
      body = items.map(it => { const ref = 'DILLARDS-' + it.po + '-' + it.store;
        return [ref, 'DILLARDS', it.dc.name, '', '', it.dc.addr, '', it.dc.city, it.dc.state, it.dc.zip, it.dc.country, 'US Geneva', 'Labels', '0', 'Shopify USWS', 'Not Imported', 'New', 'COGS - US - Wholesale', ref, 'Dillards Special Requirements to be provided', it.sku, it.qty, price(it), 'DILLARDS', 'keyaccounts@dockandbay.com', 'Dillards', 'Dillards', '', '', '', '', '', '']; });
    }
    const csv = [hdr].concat(body).map(r => r.map(q).join(',')).join('\n') + '\n';
    const nPre = (level === 'store' && havePrepack) ? items.filter(it => prepackByUpc[it.ean] > 0).length : 0;
    res.set('Content-Type', 'text/csv;charset=utf-8').set('Content-Disposition', 'attachment; filename="cin7-sales-orders-' + level + '.csv"')
      .set('X-Prepack-Priced', String(nPre) + '/' + items.length).set('Cache-Control', 'no-store').send(csv);
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});

// ── EDI projects — persist a named upload (ASN CSV + label PDFs as bytea) so users can return to it (mig 244) ──
app.get('/api/supply/edi-projects', async (_req, res) => {
  try {
    const r = await pool.query(`SELECT p.id, p.name, p.created_by, to_char(p.created_at,'YYYY-MM-DD HH24:MI') created_at,
        to_char(p.updated_at,'YYYY-MM-DD HH24:MI') updated_at, count(f.id)::int files, coalesce(sum(f.byte_size),0)::bigint bytes
      FROM planner.edi_projects p LEFT JOIN planner.edi_project_files f ON f.project_id=p.id
      GROUP BY p.id ORDER BY p.updated_at DESC`);
    res.set('Cache-Control', 'no-store').json({ ok: true, projects: r.rows });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
app.post('/api/supply/edi-projects', async (req, res) => {
  try { const name = String((req.body && req.body.name) || '').trim(); if (!name) return res.status(400).json({ error: 'name required' });
    const r = await pool.query(`INSERT INTO planner.edi_projects (name, created_by) VALUES ($1,$2) RETURNING id, name`, [name, authUser(req) || null]);
    res.json({ ok: true, id: r.rows[0].id, name: r.rows[0].name });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
app.get('/api/supply/edi-projects/:id', async (req, res) => {
  try {
    const p = (await pool.query(`SELECT id, name, created_by, to_char(created_at,'YYYY-MM-DD HH24:MI') created_at FROM planner.edi_projects WHERE id=$1`, [req.params.id])).rows[0];
    if (!p) return res.status(404).json({ error: 'not found' });
    const files = (await pool.query(`SELECT id, kind, filename, byte_size, uploaded_by, to_char(uploaded_at,'YYYY-MM-DD HH24:MI') uploaded_at
      FROM planner.edi_project_files WHERE project_id=$1 ORDER BY uploaded_at, id`, [req.params.id])).rows;
    res.set('Cache-Control', 'no-store').json({ ok: true, project: p, files });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
app.post('/api/supply/edi-projects/:id/files', async (req, res) => {
  try {
    const files = Array.isArray(req.body && req.body.files) ? req.body.files : [];
    if (!files.length) return res.status(400).json({ error: 'no files' });
    const ex = (await pool.query(`SELECT 1 FROM planner.edi_projects WHERE id=$1`, [req.params.id])).rowCount;
    if (!ex) return res.status(404).json({ error: 'project not found' });
    const by = authUser(req) || null; const out = [];
    for (const f of files) {
      // Each file arrives inline (f.b64) or already in Storage (f.storage_path + f.storage_sig). Skip empties.
      if (!f || (!f.b64 && !f.storage_path)) continue;
      let up; try { up = resolveUpload({ data_base64: f.b64, storage_path: f.storage_path, storage_sig: f.storage_sig, byte_size: f.byte_size }, { maxInline: 20 * 1024 * 1024 }); } catch (e) { return res.status(e.status || 400).json({ error: e.message }); }
      if (!up.storagePath && !up.buf.length) continue;
      const kind = (String(f.kind || '').toLowerCase() === 'csv') ? 'csv' : 'pdf';
      const r = await pool.query(`INSERT INTO planner.edi_project_files (project_id, kind, filename, mime, byte_size, data, storage_path, uploaded_by)
        VALUES ($1,$2,$3,$4,$5,$6,$7,$8) RETURNING id, kind, filename, byte_size, uploaded_by, to_char(uploaded_at,'YYYY-MM-DD HH24:MI') uploaded_at`,
        [req.params.id, kind, f.filename || (kind + '-file'), kind === 'csv' ? 'text/csv' : 'application/pdf', up.byteSize, up.buf, up.storagePath, by]);
      out.push(r.rows[0]);
    }
    await pool.query(`UPDATE planner.edi_projects SET updated_at=now() WHERE id=$1`, [req.params.id]);
    res.json({ ok: true, files: out });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
app.get('/api/supply/edi-projects/:id/files/:fid', async (req, res) => {
  try {
    const r = (await pool.query(`SELECT kind, filename, storage_path, CASE WHEN storage_path IS NULL THEN encode(data,'base64') END b64 FROM planner.edi_project_files WHERE id=$1 AND project_id=$2`, [req.params.fid, req.params.id])).rows[0];
    if (!r) return res.status(404).json({ error: 'not found' });
    const url = r.storage_path ? await storageSignDownload(r.storage_path, { filename: r.filename }) : null;   // large files: client follows the signed URL
    res.set('Cache-Control', 'no-store').json({ ok: true, kind: r.kind, filename: r.filename, b64: r.b64, url });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
app.delete('/api/supply/edi-projects/:id/files/:fid', async (req, res) => {
  try { const r = await pool.query(`DELETE FROM planner.edi_project_files WHERE id=$1 AND project_id=$2`, [req.params.fid, req.params.id]);
    await pool.query(`UPDATE planner.edi_projects SET updated_at=now() WHERE id=$1`, [req.params.id]);
    res.json({ ok: true, deleted: r.rowCount });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
app.delete('/api/supply/edi-projects/:id', async (req, res) => {
  try { const r = await pool.query(`DELETE FROM planner.edi_projects WHERE id=$1`, [req.params.id]); res.json({ ok: true, deleted: r.rowCount }); }
  catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// Admin upsert of a price entry + its tiers (id present = update, else insert). Always active/admin-sourced.
app.post('/api/supply/price-list', async (req, res) => {
  const b = req.body || {}, me = (await permsFor(req)).email || '';
  const scope = (b.scope === 'sku') ? 'sku' : 'type';
  const tiers = Array.isArray(b.tiers) ? b.tiers.map(t => ({ min_qty: Math.max(1, parseInt(t.min_qty, 10) || 1), unit_cost: Number(t.unit_cost) })).filter(t => isFinite(t.unit_cost)) : [];
  if (!b.supplier || (scope === 'type' && !b.price_type) || (scope === 'sku' && !b.sku)) return res.status(400).json({ error: 'supplier + price_type (type) or sku (sku) required' });
  if (!tiers.length) return res.status(400).json({ error: 'at least one tier (min_qty, unit_cost) required' });
  const efp = (b.effective_from_production === '' || b.effective_from_production == null) ? null : (parseInt(b.effective_from_production, 10) || null);
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    let id = b.id ? parseInt(b.id, 10) : null;
    if (id) {
      await client.query(`UPDATE planner.price_list_entries SET supplier=$2, scope=$3, price_type=$4, sku=$5, currency=$6,
        effective_from_production=$7, note=$8, status='active', source='admin', approved_by=$9, approved_at=now(), updated_at=now() WHERE id=$1`,
        [id, b.supplier, scope, scope === 'type' ? b.price_type : (b.price_type || null), scope === 'sku' ? b.sku : null, b.currency || 'USD', efp, b.note || null, me]);
    } else {
      id = (await client.query(`INSERT INTO planner.price_list_entries (supplier,scope,price_type,sku,currency,effective_from_production,note,status,source,approved_by,approved_at)
        VALUES ($1,$2,$3,$4,$5,$6,$7,'active','admin',$8,now()) RETURNING id`,
        [b.supplier, scope, scope === 'type' ? b.price_type : (b.price_type || null), scope === 'sku' ? b.sku : null, b.currency || 'USD', efp, b.note || null, me])).rows[0].id;
    }
    await client.query('DELETE FROM planner.price_list_tiers WHERE entry_id=$1', [id]);
    for (const t of tiers) await client.query('INSERT INTO planner.price_list_tiers (entry_id,min_qty,unit_cost) VALUES ($1,$2,$3) ON CONFLICT (entry_id,min_qty) DO UPDATE SET unit_cost=excluded.unit_cost', [id, t.min_qty, t.unit_cost]);
    await client.query('COMMIT');
    res.json({ ok: true, id });
  } catch (e) { await _rollback(client); log500(e); res.status(500).json({ error: e.message }); }
  finally { client.release(); }
});
app.post('/api/supply/price-list/:id/delete', async (req, res) => {
  try { await pool.query('DELETE FROM planner.price_list_entries WHERE id=$1', [parseInt(req.params.id, 10)]); res.json({ ok: true }); }
  catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// SEED FROM COST (Ben): create a REAL price-list entry for every (price_type × supplier) that planner.products says
// supplies the type but has no active type-scope price yet — seeded from the generic product cost (source='seed',
// one tier @ min_qty 1), editable like any other. Explicit + idempotent (only fills gaps). preview=1 → count only.
app.post('/api/supply/price-list/seed-missing', async (req, res) => {
  const preview = !!(req.body && req.body.preview);
  const me = (await permsFor(req)).email || '';
  const client = await pool.connect();
  try {
    const cand = (await client.query(`
      SELECT p.price_type, trim(s.supplier) supplier, mode() WITHIN GROUP (ORDER BY p.cost) seed_cost
      FROM planner.products p
      CROSS JOIN LATERAL unnest(string_to_array(coalesce(p.main_supplier_final,'')||','||coalesce(p.supplier_multiple_all,''), ',')) AS s(supplier)
      WHERE coalesce(p.variant_type,'')='MASTER' AND upper(coalesce(p.status,''))<>'NON STOCKED'
        AND coalesce(p.price_type,'')<>'' AND upper(coalesce(p.price_type,''))<>'NA'
        AND trim(s.supplier)<>'' AND p.cost IS NOT NULL AND p.cost>0
      GROUP BY 1,2`)).rows;
    const existing = new Set((await client.query(`SELECT supplier||'|'||price_type k FROM planner.price_list_entries WHERE status='active' AND scope='type'`)).rows.map(r => r.k));
    const supCcy = {}; (await client.query(`SELECT name, upper(coalesce(nullif(default_currency,''),'USD')) ccy FROM planner.suppliers WHERE coalesce(active,true)`)).rows.forEach(r => { supCcy[r.name] = r.ccy; });
    const todo = cand.filter(c => supCcy[c.supplier] && !existing.has(c.supplier + '|' + c.price_type) && Number(c.seed_cost) > 0);
    if (preview || !todo.length) return res.json({ ok: true, created: 0, pending: todo.length });
    await client.query('BEGIN');
    for (const c of todo) {
      const id = (await client.query(`INSERT INTO planner.price_list_entries (supplier,scope,price_type,sku,currency,effective_from_production,note,status,source,approved_by,approved_at)
        VALUES ($1,'type',$2,NULL,$3,NULL,'seeded from product cost','active','seed',$4,now()) RETURNING id`,
        [c.supplier, c.price_type, supCcy[c.supplier], me])).rows[0].id;
      await client.query(`INSERT INTO planner.price_list_tiers (entry_id,min_qty,unit_cost) VALUES ($1,1,$2)
        ON CONFLICT (entry_id,min_qty) DO UPDATE SET unit_cost=excluded.unit_cost`, [id, Number(c.seed_cost)]);
    }
    await client.query('COMMIT');
    res.json({ ok: true, created: todo.length });
  } catch (e) { try { await client.query('ROLLBACK'); } catch (_) {} log500(e); res.status(500).json({ error: e.message }); }
  finally { client.release(); }
});
