// Xero EXCEPTIONS (replaces the Xero Compare upload). An exception = a PO whose Xero bill amount-due / payments do NOT
// match HORIZON's, plus an insight into the likely cause. Also surfaces uncreated credit notes (a common cause) and
// shipped POs with no bill. Hits live Xero (bills fetched by id in bulk), so the result is cached ~3 min; ?refresh=1
// forces a recompute. The `count` feeds the action badge in the menu headers.
let _xeroExcCache = { at: 0, data: null };
const _usd = n => (Number(n) || 0).toLocaleString('en-US', { style: 'currency', currency: 'USD' });
const _xd = s => { const m = /\/Date\((\d+)/.exec(String(s || '')); return m ? new Date(Number(m[1])).toISOString().slice(0, 10) : (/^\d{4}-\d{2}-\d{2}/.test(String(s || '')) ? String(s).slice(0, 10) : null); };
const _daysDiff = (a, b) => { if (!a || !b) return null; const da = new Date(a + 'T00:00:00Z'), db = new Date(b + 'T00:00:00Z'); if (isNaN(da) || isNaN(db)) return null; return Math.round((da - db) / 86400000); };
async function _computeXeroExceptions() {
  const out = [];
  // v28.130 (Ben): only reconcile POs from production P55 onward; older productions are settled history (noise). POs with no
  // numeric PROD# are kept. One predicate, used by both the bill reconciliation and the uncreated-credit-note check.
  // CASE (not AND) so the ::int cast only ever runs on an all-digit string — Postgres doesn't guarantee AND short-circuits.
  const MIN_PROD = 55, PROD_OK = `coalesce(CASE WHEN regexp_replace(coalesce(p.prod_no,''),'[^0-9]','','g') ~ '^[0-9]{1,6}$' THEN regexp_replace(p.prod_no,'[^0-9]','','g')::int END, ${MIN_PROD}) >= ${MIN_PROD}`;
  // linked POs + HORIZON payment figures
  // v28.094: bill amounts/dates come from the LOCAL planner.xero_bills cache (kept fresh by syncXeroBills / the cron),
  // so this is a pure DB reconciliation — no live Xero call per bill (was ~22s of by-id fetches).
  const linked = (await pool.query(
    `SELECT p.po, coalesce(p.supplier_name,'') supplier, upper(coalesce(p.country_code,'')) cc, coalesce(p.branch,'') branch,
            coalesce(nullif(p.supplier_invoice_total,0), p.order_value_estimation, 0) total_h,
            (coalesce(p.pay_start_deposit_assigned,0)+coalesce(p.pay_completion_assigned,0)+coalesce(p.pay_balance_1_amount,0)+coalesce(p.pay_balance_2_amount,0)) paid_h,
            to_char(coalesce(p.balance_due_date_overide, p.pay_balance_1_date, p.pay_completion_date),'YYYY-MM-DD') due_h,
            l.external_id bill_id, l.external_ref bill_ref,
            b.total b_total, b.amount_paid b_paid, b.amount_due b_due, b.currency_code b_ccy, b.status b_status,
            b.invoice_number b_number, to_char(b.due_date,'YYYY-MM-DD') b_due_date, to_char(b.invoice_date,'YYYY-MM-DD') b_date
       FROM planner.purchase_orders p
       JOIN planner.po_links l ON l.po=p.po AND l.system='xero' AND l.status='linked' AND l.external_id IS NOT NULL
       LEFT JOIN planner.xero_bills b ON b.invoice_id=l.external_id
      WHERE coalesce(p.master_po,'')='' AND ${PROD_OK} LIMIT 800`)).rows;
  const TOL = 1.0;
  const DUE_TOL = 5;   // days
  linked.forEach(r => {
    r._reg = _poXeroRegion(r.cc, r.branch);
    if (r.b_status == null && r.b_total == null) return;   // bill not in the local cache yet (unsynced) → skip
    const x = { total: Number(r.b_total) || 0, paid: Number(r.b_paid) || 0, due: Number(r.b_due) || 0, ccy: r.b_ccy, status: r.b_status, number: r.b_number, dueDate: r.b_due_date, date: r.b_date };
    // Due-date check — independent of the amount reconciliation. Flag a bill whose due date is missing, before its
    // own date, or off Horizon's expected balance/completion due date by more than a few days.
    if (String(x.status || '') !== 'PAID' && String(x.status || '') !== 'VOIDED') {
      let ddMsg = null;
      if (x.date && x.dueDate && x.dueDate < x.date) ddMsg = 'Xero due date ' + x.dueDate + ' is before the bill date ' + x.date;
      else if (r.due_h && x.dueDate) { const dd = _daysDiff(x.dueDate, r.due_h); if (dd != null && Math.abs(dd) > DUE_TOL) ddMsg = 'Xero due ' + x.dueDate + ' vs Horizon ' + r.due_h + ' (' + (dd > 0 ? dd + 'd later' : (-dd) + 'd earlier') + ')'; }
      else if (r.due_h && !x.dueDate) ddMsg = 'Xero bill has no due date; Horizon expects ' + r.due_h;
      if (ddMsg) out.push({ type: 'due_date_mismatch', po: r.po, supplier: r.supplier, region: r._reg, bill_ref: x.number || r.bill_ref,
        bill_id: r.bill_id, bill_url: 'https://go.xero.com/AccountsPayable/View.aspx?InvoiceID=' + r.bill_id,
        message: r.po + ' — bill due date looks wrong', insight: ddMsg, action: 'review_po' });
    }
    // v28.094: HORIZON figures are USD. If the Xero bill is in another currency we can't compare raw amounts without an
    // FX rate, so skip the amount reconciliation (the due-date check above is currency-independent and still applies).
    // This removes the biggest class of false positives (GBP/AUD/CAD/EUR bills that always "mismatched").
    if (x.ccy && x.ccy !== 'USD') return;
    const dueH = (Number(r.total_h) || 0) - (Number(r.paid_h) || 0);
    const paidDiff = x.paid - (Number(r.paid_h) || 0);
    const dueDiff = x.due - dueH;
    const totalDiff = x.total - (Number(r.total_h) || 0);
    if (Math.abs(paidDiff) <= TOL && Math.abs(dueDiff) <= TOL && Math.abs(totalDiff) <= TOL) return;   // reconciled
    const bits = [];
    bits.push('Xero: due ' + _usd(x.due) + ', paid ' + _usd(x.paid) + ', total ' + _usd(x.total) + (x.ccy ? ' ' + x.ccy : '') + ' [' + (x.status || '') + ']');
    bits.push('Horizon: due ' + _usd(dueH) + ', paid ' + _usd(r.paid_h) + ', total ' + _usd(r.total_h));
    if (Math.abs(totalDiff) > TOL) bits.push('Bill total differs by ' + _usd(Math.abs(totalDiff)) + (totalDiff > 0 ? ' (Xero higher — invoice raised above Horizon’s value)' : ' (Horizon higher — final invoice may exceed the Xero bill)'));
    if (Math.abs(paidDiff) > TOL) bits.push(paidDiff > 0 ? 'Xero shows ' + _usd(paidDiff) + ' more paid — Horizon may be missing this payment' : 'Horizon shows ' + _usd(-paidDiff) + ' more paid — a payment / credit note is not in Xero yet');
    out.push({ type: 'amount_mismatch', po: r.po, supplier: r.supplier, region: r._reg, bill_ref: x.number || r.bill_ref,
      bill_id: r.bill_id, bill_url: 'https://go.xero.com/AccountsPayable/View.aspx?InvoiceID=' + r.bill_id,
      xero: { due: x.due, paid: x.paid, total: x.total }, horizon: { due: dueH, paid: Number(r.paid_h) || 0, total: Number(r.total_h) || 0 },
      diff: { due: dueDiff, paid: paidDiff, total: totalDiff },
      message: r.po + ' — amounts don’t reconcile with Xero', insight: bits.join('. '), action: 'review_po' });
  });
  // uncreated credit notes (a common cause of a paid mismatch): starting deposit + linked bill, none queued
  const cn = (await pool.query(
    `SELECT p.po, coalesce(p.supplier_name,'') supplier, coalesce(p.pay_start_deposit_assigned,0) amt,
            coalesce(p.prod_no,'') prod_no, coalesce(p.deposit_ref,'') deposit_ref, l.external_ref bill_ref, l.external_id bill_id
       FROM planner.purchase_orders p
       JOIN planner.po_links l ON l.po=p.po AND l.system='xero' AND l.status='linked'
      WHERE coalesce(p.pay_start_deposit_assigned,0) > 0.009
        AND ${PROD_OK}
        AND ( (upper(coalesce(p.country_code,''))='AU' OR (coalesce(p.country_code,'')='' AND p.branch ILIKE '%coghlan%'))
              OR (regexp_replace(coalesce(p.prod_no,''),'[^0-9]','','g') ~ '^[0-9]+$' AND regexp_replace(p.prod_no,'[^0-9]','','g')::int >= 58) )
        AND NOT EXISTS (SELECT 1 FROM planner.po_links c WHERE c.po=p.po AND c.system='xero_credit_note' AND c.status='linked')
        AND NOT EXISTS (SELECT 1 FROM planner.xero_push_queue q WHERE q.po=p.po AND q.kind='credit_note' AND q.status <> 'cancelled')
      ORDER BY p.po LIMIT 300`)).rows;
  cn.forEach(r => out.push({ type: 'uncreated_credit_note', po: r.po, supplier: r.supplier, amount: Number(r.amt) || 0,
    prod_no: r.prod_no, deposit_ref: r.deposit_ref, bill_ref: r.bill_ref,
    bill_id: r.bill_id, bill_url: r.bill_id ? ('https://go.xero.com/AccountsPayable/View.aspx?InvoiceID=' + r.bill_id) : null,
    message: r.po + ' — ' + _usd(r.amt) + ' starting deposit not yet drawn down',
    insight: 'Create a credit note coded to Stock Deposits (602)' + (r.prod_no ? ', tagged P' + String(r.prod_no).replace(/^P/i, '') : '') + ', allocated to bill ' + (r.bill_ref || 'the PO bill') + ' — until then Xero shows more owed than Horizon.', action: 'create_credit_note' }));
  const byType = {}; out.forEach(e => { byType[e.type] = (byType[e.type] || 0) + 1; });
  return { count: out.length, by_type: byType, exceptions: out, computed_at: new Date().toISOString() };
}
app.get('/api/supply/xero/exceptions', async (req, res) => {
  try {
    const fresh = String(req.query.refresh || '') === '1';
    // v28.081: was a 3-min cache that BLOCKED on expiry. Now SWR: within 15 min serve cached; past that serve the last
    // result at once and recompute behind. The reconciliation itself is now a fast local-DB read (v28.094 — bill amounts
    // come from planner.xero_bills), so ?refresh=1 first runs an incremental bill sync, then recomputes and waits.
    if (fresh) { try { await syncXeroBills({}); } catch (e) { /* keep last synced bills */ } const data = await _computeXeroExceptions(); _xeroExcCache = { at: Date.now(), data }; swrDrop('xero:exc'); return res.set('Cache-Control', 'no-store').json(Object.assign({ cached: false }, data)); }
    const _seed = _xeroExcCache.data ? _xeroExcCache : null; _xeroExcCache = { at: 0, data: null };   // migrate the old cache slot into swr once
    if (_seed) { const e = { v: _seed.data, at: _seed.at, inflight: null }; if (!_swr.has('xero:exc')) _swr.set('xero:exc', e); }
    const data = await swrGet('xero:exc', 15 * 60 * 1000, _computeXeroExceptions);
    res.set('Cache-Control', 'no-store').json(Object.assign({ cached: true }, data));
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// ── v28.094 (Ben): local Xero-bills cache + incremental sync ────────────────────────────────────────────────────────
// Store ACCPAY bills in planner.xero_bills and pull only bills MODIFIED since the last watermark (Xero If-Modified-Since),
// so the link resolver and the Exceptions reconciliation read amounts/refs from Postgres instead of hitting Xero live
// every run (was a ~3-min full sweep + a ~22s by-id refetch). First run per region (no watermark) is a full pull.
const _xBillDate = s => { const m = /\/Date\((\d+)/.exec(String(s || '')); if (m) return new Date(Number(m[1])); const t = String(s || ''); return /^\d{4}-\d{2}-\d{2}/.test(t) ? new Date(t.length > 10 ? (t.slice(0, 19) + 'Z') : (t + 'T00:00:00Z')) : null; };
// v28.183 (Ben): every bill list call names ALL statuses (Xero's default list does include VOIDED/DELETED today, verified
// 06-Oct-26, but the explicit Statuses param keeps a void from ever being filtered out) and reads 1000 bills per page
// (pageSize; was the 100 default, so a full UK pull is 9 calls instead of 88).
const XB_STATUSES = 'DRAFT,SUBMITTED,AUTHORISED,PAID,VOIDED,DELETED';
const XB_PAGE = 1000;
const xbDead = s => /^(VOIDED|DELETED)$/i.test(String(s || ''));
const xbUrl = id => 'https://go.xero.com/AccountsPayable/View.aspx?InvoiceID=' + id;
// Upsert Xero ACCPAY invoices (API shape) into planner.xero_bills in ONE multi-row statement. Returns how many rows are new
