// ── Supplier portal admin (CONFIG ▸ Portal Users). The approved email↔supplier list + magic-link issue.
app.post('/api/supply/portal-user-create', async (req, res) => {
  const b = req.body || {}; const email = String(b.email || '').trim().toLowerCase();
  if (!email || !/.+@.+\..+/.test(email)) return res.status(400).json({ error: 'valid email required' });
  try {
    // resolve supplier_id from the supplier name when given (mirrors the rest of the app: map by name)
    let sid = b.supplier_id || null, sname = b.supplier_name || null;
    if (!sid && sname) { const r = await pool.query(`SELECT id FROM planner.suppliers WHERE name=$1`, [sname]); sid = r.rows[0] ? r.rows[0].id : null; }
    const r = await pool.query(`INSERT INTO planner.supplier_portal_users (email, supplier_id, supplier_name, contact_name)
      VALUES ($1,$2,$3,$4) RETURNING id`, [email, sid, sname, b.contact_name || null]);
    res.json({ id: r.rows[0].id });
  } catch (e) { log500(e); res.status(500).json({ error: /unique/i.test(e.message) ? 'that email is already on the list' : e.message }); }
});
app.post('/api/supply/portal-user/:id', async (req, res) => {
  const b = req.body || {};
  if (b._delete) { try { await pool.query(`DELETE FROM planner.supplier_portal_users WHERE id=$1`, [req.params.id]); return res.json({ deleted: true }); } catch (e) { log500(e); return res.status(500).json({ error: e.message }); } }
  // if supplier_name changes, re-resolve supplier_id
  if (b.supplier_name !== undefined && b.supplier_id === undefined) {
    const r = await pool.query(`SELECT id FROM planner.suppliers WHERE name=$1`, [b.supplier_name]);
    b.supplier_id = r.rows[0] ? String(r.rows[0].id) : '';
  }
  if (b.email) b.email = String(b.email).trim().toLowerCase();
  return patch(res, 'planner.supplier_portal_users', 'id', req.params.id,
    { email: 'text', supplier_id: 'bigint', supplier_name: 'text', contact_name: 'text', active: 'boolean', receive_payment_notification: 'boolean' }, b, 'bigint');
});
// Issue a magic link (dev stub: returns the URL instead of emailing it — Diviyaj wires real email for prod).
app.post('/api/supply/portal-magic/:id', async (req, res) => {
  try {
    const u = (await pool.query(`SELECT email, active FROM planner.supplier_portal_users WHERE id=$1`, [req.params.id])).rows[0];
    if (!u) return res.status(404).json({ error: 'no such portal user' });
    if (!u.active) return res.status(400).json({ error: 'user is inactive — activate before issuing a link' });
    const token = crypto.randomBytes(24).toString('hex');
    await pool.query(`INSERT INTO planner.portal_magic_tokens (token, email, expires_at) VALUES ($1,$2, now() + make_interval(hours => $3))`, [tokHash(token), u.email, PORTAL_LINK_HOURS]);   // v28.186 (Ben): 24 h link life (was 7 days). v28.210 (Ben, H2): stored hashed
    const base = portalLinkBase(req);   // v28.151 (review B5)
    res.json({ email: u.email, url: base + '/portal?token=' + token, expires_hours: PORTAL_LINK_HOURS, expires_days: Math.round(PORTAL_LINK_HOURS / 24 * 10) / 10 });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});

// Bulk signals for the CONFIG ▸ Portal Users open-action counts: unread internal (D&B) notes per PO +
// all supplier submissions. Combined client-side with /api/supply/purchase-orders + samples to compute
// each supplier's open actions (same conditions the portal shows the supplier).
// Send an open-actions reminder email to a supplier's registered portal address(es) — LIVE via Resend.
// Recipients are derived server-side from ACTIVE portal users for the supplier_id (the client cannot email
// an arbitrary address). Sandbox has no RESEND_API_KEY → nothing is sent (safe to test).
app.post('/api/supply/portal-remind', async (req, res) => {
  const b = req.body || {}, sid = b.supplier_id;
  if (!sid) return res.status(400).json({ error: 'supplier_id required' });
  try {
    const emails = (await pool.query(`SELECT DISTINCT lower(email) email FROM planner.supplier_portal_users WHERE supplier_id=$1 AND active=true AND coalesce(email,'')<>''`, [sid])).rows.map(r => r.email);
    if (!emails.length) return res.status(400).json({ error: 'no active portal email for this supplier' });
    const subject = String(b.subject || 'Dock & Bay — open items on your supplier portal').slice(0, 200);
    const html = b.html || '<p>Please log in to the supplier portal and action your open items.</p>';
    if (!process.env.RESEND_API_KEY) { console.log('[portal remind] no RESEND_API_KEY — would email ' + emails.join(', ')); return res.json({ ok: true, sent: 0, emails, sandbox: true }); }
    const r = await _fetchT('https://api.resend.com/emails', { method: 'POST',
      headers: { Authorization: 'Bearer ' + process.env.RESEND_API_KEY, 'Content-Type': 'application/json' },
      body: JSON.stringify({ from: process.env.PORTAL_FROM || 'Dock & Bay <portal@dockandbay.com>', reply_to: EMAIL_REPLY_TO, to: emails, subject, html }) });
    if (!r.ok) { const t = await r.text().catch(() => ''); logEmail({ recipients: emails.join(', '), subject, kind: 'portal-remind', by: authUser(req), status: 'error', error: 'resend ' + r.status }); return res.status(502).json({ error: 'email send failed: ' + t.slice(0, 200) }); }
    const _rid = await r.json().then(j => j && j.id).catch(() => null);
    logEmail({ recipients: emails.join(', '), subject, kind: 'portal-remind', ref: b.supplier_name || null, by: authUser(req), status: 'sent', resend_id: _rid });
    res.json({ ok: true, sent: emails.length, emails });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});

