// Product SIZES master (phase 2): claim / release a Workshop-pool barcode (mig 293) for a size. Transactional so the
// pool's status stays in sync — one barcode ↔ one size. Body {barcode:'<ean>'} to claim (frees the size's old code first),
// or {barcode:null|''} to release. A code already assigned to ANOTHER size is rejected.
app.post('/api/product/size/:id/barcode', async (req, res) => {
  const sizeId = req.params.id; const bc = (req.body && req.body.barcode != null) ? String(req.body.barcode).trim() : '';
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const sz = (await client.query(`SELECT s.id, coalesce(s.barcode,'') cur, coalesce(s.mapped_sku,'') mapped_sku, coalesce(s.working_sku,'') working_sku, i.ref
      FROM planner.product_dev_sizes s JOIN planner.product_dev_items i ON i.id=s.item_id WHERE s.id=$1::bigint`, [sizeId])).rows[0];
    if (!sz) { await _rollback(client); return res.status(404).json({ error: 'size not found' }); }
    if (bc) {
      const pool0 = (await client.query(`SELECT status, assigned_size_id FROM planner.product_workshop_barcodes WHERE barcode=$1`, [bc])).rows[0];
      if (!pool0) { await _rollback(client); return res.status(400).json({ error: 'barcode ' + bc + ' is not in the workshop pool' }); }
      if (pool0.status === 'assigned' && String(pool0.assigned_size_id) !== String(sizeId)) { await _rollback(client); return res.status(409).json({ error: 'barcode ' + bc + ' is already assigned to another size' }); }
    }
    // free the size's current barcode (if changing/clearing)
    if (sz.cur && sz.cur !== bc) await client.query(`UPDATE planner.product_workshop_barcodes SET status='free', assigned_size_id=NULL, assigned_ref=NULL, assigned_sku=NULL, assigned_by=NULL, assigned_at=NULL WHERE barcode=$1`, [sz.cur]);
    if (bc) {
      const sku = sz.mapped_sku || sz.working_sku || null;
      await client.query(`UPDATE planner.product_workshop_barcodes SET status='assigned', assigned_size_id=$2::bigint, assigned_ref=$3, assigned_sku=$4, assigned_by=$5, assigned_at=now() WHERE barcode=$1`,
        [bc, sizeId, sz.ref, sku, authUser(req)]);
    }
    await client.query(`UPDATE planner.product_dev_sizes SET barcode=$2 WHERE id=$1::bigint`, [sizeId, bc || null]);
    await client.query('COMMIT');
    res.json({ ok: true, barcode: bc || null });
  } catch (e) { try { await client.query('ROLLBACK'); } catch (_) {} log500(e); res.status(500).json({ error: e.message }); }
  finally { client.release(); }
});
// Approved products waiting room (mig 295, phase 3): push a SIZE with a working SKU into the Horizon PIM waiting room —
// a staging list of new-product requests (SKU + barcode + colourway). NO Airtable write; this is an in-Horizon report.
// Upserts one row per source size (re-pushing refreshes it). Requires the size to have a working_sku.
app.post('/api/product/size/:id/push-pim', async (req, res) => {
  try {
    const s = (await pool.query(`SELECT s.id, coalesce(s.size_label,'') size_label, coalesce(s.working_sku,'') working_sku, coalesce(s.barcode,'') barcode,
        i.ref, coalesce(i.description,'') product_name, coalesce(i.category,'') category,
        coalesce(nullif(i.bulk_colour_name,''), i.colour_name, '') colourway
      FROM planner.product_dev_sizes s JOIN planner.product_dev_items i ON i.id=s.item_id WHERE s.id=$1::bigint`, [req.params.id])).rows[0];
    if (!s) return res.status(404).json({ error: 'size not found' });
    // v27.811 (Ben): a size can be pushed WITHOUT a working SKU or barcode — it goes in under the product development ref
    // (the dev "SKU") so the PIM request still carries an identity. Barcode is optional.
    const sku = s.working_sku || s.ref;
    await pool.query(`INSERT INTO planner.product_pim_waiting_room (size_id,item_ref,working_sku,barcode,colourway,size_label,product_name,category,status,pushed_by,pushed_at)
      VALUES ($1,$2,$3,$4,$5,$6,$7,$8,'waiting',$9,now())
      ON CONFLICT (size_id) DO UPDATE SET item_ref=excluded.item_ref, working_sku=excluded.working_sku, barcode=excluded.barcode, colourway=excluded.colourway,
        size_label=excluded.size_label, product_name=excluded.product_name, category=excluded.category, status='waiting', pushed_by=excluded.pushed_by, pushed_at=now()`,
      [s.id, s.ref, sku, s.barcode || null, s.colourway || null, s.size_label || null, s.product_name || null, s.category || null, authUser(req)]);
    res.json({ ok: true });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
