app.get('/api/product/notes/:ref', async (req, res) => {
  try {
    // v27.857 (Ben): timeline is per-SUPPLIER (a development request belongs to one supplier; the product item does not).
    // When ?supplier=<name> is given, return that supplier's notes PLUS product-wide notes (supplier_id IS NULL); no
    // filter = the full merged product view. supplier_id -1 = an unknown supplier → only the product-wide notes.
    let supId = null; const supName = String(req.query.supplier || '').trim();
    if (supName) { const s = (await pool.query(`SELECT id FROM planner.suppliers WHERE lower(name)=lower($1) LIMIT 1`, [supName])).rows[0]; supId = s ? s.id : -1; }
    const r = await pool.query(`SELECT n.id, n.author_kind, coalesce(n.author_email,'') author_email, n.body,
    to_char(n.created_at,'DD-Mon-YY HH24:MI') created_at, n.read_at IS NOT NULL read,
    n.attachment_id, coalesce(a.filename,'') attachment_name, coalesce(a.mime,'') attachment_mime, coalesce(n.tags,'[]'::jsonb) tags, coalesce(n.pantone,'[]'::jsonb) pantone,
    n.sample_id, (SELECT ps.version FROM planner.product_dev_samples ps WHERE ps.id=n.sample_id) sample_version
    FROM planner.supplier_notes n LEFT JOIN planner.portal_attachments a ON a.id=n.attachment_id
    WHERE n.po=$1 AND ($2::bigint IS NULL OR n.supplier_id=$2 OR n.supplier_id IS NULL) ORDER BY n.created_at`, [req.params.ref, supName ? supId : null]);
    res.json(r.rows); } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// Sanitise Pantone reference cards attached to a message → array of {code,name,hex,book}
function cleanPantone(arr) {
  return Array.isArray(arr) ? arr.filter(p => p && p.code).slice(0, 12).map(p => ({
    code: String(p.code).slice(0, 40), name: String(p.name || '').slice(0, 80),
    hex: (/^#?[0-9a-fA-F]{3,8}$/.test(String(p.hex || '')) ? (String(p.hex)[0] === '#' ? String(p.hex) : '#' + p.hex) : ''),
    book: String(p.book || '').slice(0, 20)
  })) : [];
}
app.post('/api/product/note', async (req, res) => {
  const b = req.body || {}, ref = (b.ref || '').trim();
  if (!ref || !String(b.body || '').trim()) return res.status(400).json({ error: 'ref and body required' });
  // tags = array of product_timeline_tags ids; pantone = array of Pantone reference cards (optional)
  const tags = Array.isArray(b.tags) ? b.tags.map(x => Number(x)).filter(x => Number.isFinite(x)) : [];
  const pantone = cleanPantone(b.pantone);
  const att = (b.attachment_id != null && String(b.attachment_id).trim() !== '') ? Number(b.attachment_id) : null;   // v27.558: optional file on the message (portal_attachments id, uploaded via /api/product/doc)
  const sampleId = (b.sample_id != null && String(b.sample_id).trim() !== '' && Number.isFinite(Number(b.sample_id))) ? Number(b.sample_id) : null;   // v27.750 (P6): /s chip → link this note to a specific development sample
  try { const r = await pool.query(`INSERT INTO planner.supplier_notes (po, author_email, author_kind, body, tags, pantone, attachment_id, sample_id) VALUES ($1,$2,'internal',$3,$4::jsonb,$5::jsonb,$6,$7) RETURNING id`,
    [ref, internalAuthor(req, b.author_email), String(b.body).trim(), JSON.stringify(tags), JSON.stringify(pantone), att, sampleId]);
    res.json({ ok: true, id: r.rows[0].id }); } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// v27.550: sample FEEDBACK notes are one-per-(sample × component) on the timeline. Re-saving feedback rewrites that note
// (text, tags, Pantone) instead of adding another. Matched by the stable prefix "Feedback on REF_vN · Component:" on the
// latest internal note for the product; falls back to a normal insert when none exists yet.
app.post('/api/product/note/upsert-feedback', async (req, res) => {
  const b = req.body || {}, ref = (b.ref || '').trim(), prefix = String(b.prefix || '').trim();
  if (!ref || !prefix || !String(b.body || '').trim()) return res.status(400).json({ error: 'ref, prefix and body required' });
  const tags = Array.isArray(b.tags) ? b.tags.map(x => Number(x)).filter(x => Number.isFinite(x)) : [];
  const pantone = cleanPantone(b.pantone);
  const att = (b.attachment_id != null && String(b.attachment_id).trim() !== '') ? Number(b.attachment_id) : null;   // v27.556: optional file on the note (portal_attachments id)
  // v27.863 (Ben): feedback is always about ONE sample version — stamp sample_id so the timeline auto-tags the "v2 sample" chip (no manual tag).
  const smpId = (b.sample_id != null && String(b.sample_id).trim() !== '') ? Number(b.sample_id) : null;
  // v27.857 (Ben): scope this feedback to the supplier whose sample it is — the caller (MANAGE / scan review) knows it.
  let supId = null; const fbSup = String(b.supplier || '').trim();
  if (fbSup) { const s = (await pool.query(`SELECT id FROM planner.suppliers WHERE lower(name)=lower($1) LIMIT 1`, [fbSup])).rows[0]; supId = s ? s.id : null; }
  try {
    const like = prefix.replace(/[\\%_]/g, m => '\\' + m) + '%';
    const up = await pool.query(`UPDATE planner.supplier_notes SET body=$3, tags=$4::jsonb, pantone=$5::jsonb, author_email=$6, attachment_id=coalesce($7::bigint, attachment_id), supplier_id=coalesce($8::bigint, supplier_id), sample_id=coalesce($9::bigint, sample_id)
      WHERE id=(SELECT id FROM planner.supplier_notes WHERE po=$1 AND author_kind='internal' AND body LIKE $2 ORDER BY created_at DESC LIMIT 1) RETURNING id, to_char(now(),'DD-Mon-YY HH24:MI') at`,
      [ref, like, String(b.body).trim(), JSON.stringify(tags), JSON.stringify(pantone), internalAuthor(req, b.author_email), att, supId, smpId]);
    if (up.rows.length) return res.json({ ok: true, id: up.rows[0].id, updated: true, at: up.rows[0].at });
    const r = await pool.query(`INSERT INTO planner.supplier_notes (po, supplier_id, author_email, author_kind, body, tags, pantone, attachment_id, sample_id) VALUES ($1,$7,$2,'internal',$3,$4::jsonb,$5::jsonb,$6,$8) RETURNING id, to_char(created_at,'DD-Mon-YY HH24:MI') at`,
      [ref, internalAuthor(req, b.author_email), String(b.body).trim(), JSON.stringify(tags), JSON.stringify(pantone), att, supId, smpId]);
    res.json({ ok: true, id: r.rows[0].id, updated: false, at: r.rows[0].at });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// In-app Pantone search (seeded from Dock & Bay's Connect export; approximate on-screen swatch). Powers the
// "/p" picker in the product-timeline compose box. Filter by book (TCX / Coated / Uncoated) optional.
app.get('/api/product/pantone/search', async (req, res) => {
  const q = String(req.query.q || '').trim(), book = String(req.query.book || '').trim();
  try {
    const params = []; let where = 'active';
    if (q) { params.push('%' + q + '%'); where += ` AND (code ILIKE $${params.length} OR name ILIKE $${params.length})`; }
    if (book) { params.push(book); where += ` AND book=$${params.length}`; }
    const rows = (await pool.query(`SELECT code, name, hex, book FROM planner.pantone_colors WHERE ${where} ORDER BY sort, code LIMIT 24`, params)).rows;
    res.json(rows);
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// Re-tag an existing product timeline message (D&B side). tags = full replacement array of tag ids.
