// ── SAMPLE SHIPMENT CONTENTS — candidate lists for the "Add contents" picker ──
// A sample shipment IS a sample_request; its contents are bulk-SKU lines (sample_request_lines)
// + product-development sample versions (sample_request_dev_samples, mig 133).
async function openSampleCandidates(suppliers) {   // dev-sample versions whose parent product is still in development ("open")
  const scoped = Array.isArray(suppliers);
  return (await pool.query(`SELECT ps.id, ps.item_ref, (ps.item_ref||'_v'||ps.version) ref, ps.version,
      coalesce(i.colour_name,'') colour_name, coalesce((SELECT string_agg(DISTINCT r.supplier_name, ', ' ORDER BY r.supplier_name) FROM planner.product_dev_requests r WHERE r.item_id=i.id),'') supplier
    FROM planner.product_dev_samples ps JOIN planner.product_dev_items i ON i.ref=ps.item_ref
    WHERE i.status='in_development' ${scoped ? 'AND EXISTS (SELECT 1 FROM planner.product_dev_requests r WHERE r.item_id=i.id AND r.supplier_name = ANY($1))' : ''}
    ORDER BY i.updated_at DESC, ps.version DESC`, scoped ? [suppliers] : [])).rows;
}
async function supplierSkuCandidates(suppliers, q, includeDev) {   // bulk SKUs, scoped to a supplier via products.supplier_multiple_all; optionally also product-development items
  const scoped = Array.isArray(suppliers); const params = []; const where = [];
  if (scoped) { params.push(suppliers); where.push(`EXISTS (SELECT 1 FROM unnest(string_to_array(coalesce(p.supplier_multiple_all,''),',')) sm WHERE btrim(sm) = ANY($${params.length}))`); }
  if (q) { params.push('%' + q + '%'); const p = '$' + params.length;
    where.push(`(p.sku ILIKE ${p} OR coalesce(p.product_name_final,p.product_name,'') ILIKE ${p} OR coalesce(p.colour_long,'') ILIKE ${p} OR coalesce(p.release_window,'') ILIKE ${p})`); }
  const skuRows = (await pool.query(`SELECT p.sku, coalesce(p.product_name_final,p.product_name,'') description, coalesce(p.size_short,'') size, coalesce(p.colour_long,'') colour, coalesce(p.release_window,'') release_window, false dev
    FROM planner.products p ${where.length ? 'WHERE ' + where.join(' AND ') : ''} ORDER BY p.sku LIMIT 300`, params)).rows;
  if (!includeDev) return skuRows;
  // also search the PRODUCT development grid (planner.product_dev_items) — its ref acts as the "sku"
  const dp = []; const dw = [`coalesce(i.status,'') <> 'dropped'`];
  if (scoped) { dp.push(suppliers); dw.push(`EXISTS (SELECT 1 FROM planner.product_dev_requests r WHERE r.item_id=i.id AND r.supplier_name = ANY($${dp.length}))`); }
  if (q) { dp.push('%' + q + '%'); const p = '$' + dp.length;
    dw.push(`(i.ref ILIKE ${p} OR coalesce(i.colour_name,'') ILIKE ${p} OR coalesce(i.description,'') ILIKE ${p} OR coalesce(i.season,'') ILIKE ${p} OR coalesce(i.category,'') ILIKE ${p})`); }
  const devRows = (await pool.query(`SELECT i.ref sku,
      (coalesce(i.colour_name,'') || CASE WHEN coalesce(i.season,'')<>'' THEN ' · '||i.season ELSE '' END || CASE WHEN coalesce(i.category,'')<>'' THEN ' · '||i.category ELSE '' END) description,
      '' size, coalesce(i.colour_name,'') colour, coalesce(i.season,'') release_window, true dev
    FROM planner.product_dev_items i WHERE ${dw.join(' AND ')} ORDER BY i.updated_at DESC LIMIT 50`, dp)).rows;
  return devRows.concat(skuRows);   // dev items first
}
function qtyOrOne(v) { var q = Math.round(Number(v) || 0); return q < 1 ? 1 : q; }   // blank/0/NaN → 1
// Assign a product sample version (dev sample) to a single sample shipment (SR), or clear it. srId=null clears all
// links; notShipped sets the "will not be shipped" flag (used to suppress the completed-but-unassigned exception).
async function assignSampleToShipment(devSampleId, srId, notShipped, by) {
  await pool.query(`DELETE FROM planner.sample_request_dev_samples WHERE dev_sample_id=$1`, [devSampleId]);
  if (srId) await pool.query(`INSERT INTO planner.sample_request_dev_samples (sample_request_id, dev_sample_id, qty, created_by)
    VALUES ($1::bigint,$2,1,$3) ON CONFLICT (sample_request_id, dev_sample_id) DO NOTHING`, [srId, devSampleId, by || null]);
  await pool.query(`UPDATE planner.product_dev_samples SET not_shipped=$2 WHERE id=$1`, [devSampleId, srId ? false : !!notShipped]);
}
// ADD a link (a dev sample can be on MANY shipments) without disturbing existing links; UNLINK removes just one.
async function linkSampleToShipment(devSampleId, srId, by) {
  if (!srId) return;
  await pool.query(`INSERT INTO planner.sample_request_dev_samples (sample_request_id, dev_sample_id, qty, created_by)
    VALUES ($1::bigint,$2,1,$3) ON CONFLICT (sample_request_id, dev_sample_id) DO NOTHING`, [srId, devSampleId, by || null]);
  await pool.query(`UPDATE planner.product_dev_samples SET not_shipped=false WHERE id=$1`, [devSampleId]);
  // sample attached to a shipment → the product's stage advances to "sample shipped" (forward-only)
  try { const it = (await pool.query(`SELECT item_ref FROM planner.product_dev_samples WHERE id=$1`, [devSampleId])).rows[0]; if (it) await prodStageAdvance(it.item_ref, 'sample_shipped', { sampleId: devSampleId }); } catch (e) { /* best-effort */ }
}
async function unlinkSampleFromShipment(devSampleId, srId) {
  if (!srId) return;
  await pool.query(`DELETE FROM planner.sample_request_dev_samples WHERE dev_sample_id=$1 AND sample_request_id=$2::bigint`, [devSampleId, srId]);
}
// v28.191 (Ben, deep dive H6): ownership of a product SAMPLE VERSION is by its development REQUEST (the supplier that submitted it), not
// the item: suppliers competing on one item must never change each other's versions (status, sizes, shipment, files). A version with no
// request (older rows) is the caller's only when the item has no other supplier's request.
async function portalOwnsProductSample(req, sampleId) {
  const n = Number(sampleId); if (!Number.isSafeInteger(n) || n <= 0) return false;
  const r = (await pool.query(`SELECT ps.item_ref, (SELECT rq.supplier_name FROM planner.product_dev_requests rq WHERE rq.id=ps.request_id) req_sup,
      (SELECT count(*) FROM planner.product_dev_requests r2 JOIN planner.product_dev_items i ON i.id=r2.item_id WHERE i.ref=ps.item_ref AND NOT (r2.supplier_name = ANY($2)))::int others
    FROM planner.product_dev_samples ps WHERE ps.id=$1`, [n, req.portal.suppliers || []])).rows[0];
  if (!r) return false;
  if (r.req_sup) return (req.portal.suppliers || []).includes(r.req_sup);
  return r.others === 0 && portalOwnsProduct(req, r.item_ref);
}
// v28.191 (Ben, H6): the caller's development request(s) on an item (id + supplier id), and the emails of the caller's people.
async function portalMyRequests(req, ref) { return (await pool.query(`SELECT r.id, r.supplier_id, r.supplier_name FROM planner.product_dev_requests r JOIN planner.product_dev_items i ON i.id=r.item_id WHERE i.ref=$1 AND r.supplier_name = ANY($2) ORDER BY r.id`, [ref, req.portal.suppliers || []])).rows; }
async function portalMyNoteSupplierId(req, ref) { const m = await portalMyRequests(req, ref); const sid = m.find(x => x.supplier_id != null); return sid ? sid.supplier_id : ((req.portal.supplierIds || [])[0] || null); }
async function portalPeopleEmails(req) { if (req._ppEmails) return req._ppEmails;
  const rows = (await pool.query(`SELECT lower(email) e FROM planner.supplier_portal_users WHERE supplier_name = ANY($1) OR supplier_id = ANY($2::bigint[])`, [req.portal.suppliers || [], (req.portal.supplierIds || []).map(Number)])).rows;
  req._ppEmails = new Set(rows.map(x => x.e).concat([String(req.portal.email || '').toLowerCase()])); return req._ppEmails; }
async function setSampleDevSamples(sampleId, devs, by) {   // replace-all the dev-sample links on a sample shipment; devs = [{id,qty}] or [id]
  await pool.query(`DELETE FROM planner.sample_request_dev_samples WHERE sample_request_id=$1::bigint`, [sampleId]);
  for (const d of (Array.isArray(devs) ? devs : [])) { const id = (d && typeof d === 'object') ? d.id : d; if (!id) continue;
    await pool.query(`INSERT INTO planner.sample_request_dev_samples (sample_request_id, dev_sample_id, qty, created_by) VALUES ($1::bigint,$2,$3,$4)
      ON CONFLICT (sample_request_id, dev_sample_id) DO UPDATE SET qty=excluded.qty`, [sampleId, id, qtyOrOne(d && typeof d === 'object' ? d.qty : 1), by || null]); }
}
async function setSampleLines(sampleId, lines) {   // replace-all the bulk-SKU lines on a sample shipment
  await pool.query(`DELETE FROM planner.sample_request_lines WHERE sample_id=$1::bigint`, [sampleId]);
  for (const l of (Array.isArray(lines) ? lines : [])) { if (!l || !l.sku) continue;
    await pool.query(`INSERT INTO planner.sample_request_lines (sample_id, sku, qty) VALUES ($1::bigint,$2,$3)`, [sampleId, String(l.sku).trim(), qtyOrOne(l.qty)]); }
}
