// Resolve a supplier name → its active portal-user emails.
async function supplierPortalEmails(name) {
  if (!name) return [];
  return (await pool.query(`SELECT DISTINCT lower(u.email) e FROM planner.supplier_portal_users u
    LEFT JOIN planner.suppliers s ON s.id=u.supplier_id
    WHERE u.active=true AND coalesce(u.email,'')<>'' AND (lower(trim(u.supplier_name))=lower(trim($1)) OR lower(trim(s.name))=lower(trim($1)))`, [name])).rows.map(x => x.e);
}
// Queue the paid-notification email (5-min delay). Body: run_key, supplier_name, amount, currency, pay_date.
app.post('/api/supply/payment-notify', async (req, res) => {
  const b = req.body || {};
  if (!b.run_key || !b.supplier_name) return res.status(400).json({ error: 'run_key and supplier_name required' });
  try {
    const emails = await supplierPortalEmails(b.supplier_name);
    if (!emails.length) return res.status(400).json({ error: 'No active portal users for "' + b.supplier_name + '" — add one in CONFIG ▸ Suppliers to send a remittance email.' });
    // one live queued email per run — replace any existing queued one
    await pool.query(`UPDATE planner.payment_emails SET status='cancelled' WHERE run_key=$1 AND status='queued'`, [b.run_key]);
    const sendAfter = new Date(Date.now() + REMIT_DELAY_MS).toISOString();
    const r = await pool.query(`INSERT INTO planner.payment_emails (run_key, supplier_name, to_emails, amount, currency, pay_date, send_after, created_by)
      VALUES ($1,$2,$3,$4,$5,$6,$7,$8) RETURNING id`,
      [b.run_key, b.supplier_name, emails.join(', '), (b.amount == null || b.amount === '') ? null : Number(b.amount), (b.currency || '').toUpperCase() || null, b.pay_date || null, sendAfter, authUser(req) || 'admin']);
    res.json({ id: r.rows[0].id, to_emails: emails, send_after: sendAfter });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
app.post('/api/supply/payment-notify/:id/cancel', async (req, res) => {
  try { const r = await pool.query(`UPDATE planner.payment_emails SET status='cancelled' WHERE id=$1 AND status='queued'`, [req.params.id]);
    res.json({ ok: true, cancelled: r.rowCount }); }
  catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// (Status list /api/supply/payment-emails is served by the /api/supply/:section switch above.)
// Build + send one queued paid-notification. Attaches the remittance(s) for the run if any exist.
async function sendPaymentNotify(row) {
  const rem = (await pool.query(`SELECT filename, mime, data, storage_path FROM planner.payment_remittances WHERE run_key=$1 ORDER BY uploaded_at`, [row.run_key])).rows;
  const money = (row.amount != null) ? (Number(row.amount).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 })) : '';
  const amtLine = money ? ('<b>' + escHtml(money) + ' ' + escHtml(row.currency || '') + '</b>') : 'your payment';
  const dateLine = row.pay_date ? (' on <b>' + escHtml(row.pay_date) + '</b>') : '';
  const hasRem = rem.length > 0;
  const html = '<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;color:#111;line-height:1.5">'
    + '<p>Hello,</p>'
    + '<p>This is to confirm that Dock &amp; Bay has made a payment of ' + amtLine + dateLine + '.</p>'
    + (hasRem ? '<p><b>Remittance attached.</b></p>' : '')
    + '<p>Thank you,<br>Dock &amp; Bay Accounts</p></div>';
  const attachments = await Promise.all(rem.map(async a => ({ filename: a.filename || 'remittance', content: (a.storage_path ? await storageFetch(a.storage_path) : Buffer.from(a.data)).toString('base64') })));
  const subj = 'Payment made — Dock & Bay' + (money ? (' (' + money + ' ' + (row.currency || '') + ')') : '');
  return sendResendEmail({ to: row.to_emails.split(',').map(s => s.trim()).filter(Boolean), subject: subj, html,
    kind: 'payment-remittance', ref: row.run_key, by: row.created_by, attachments });
}
// Worker: every 30s, claim + send any queued email whose 5-min window has elapsed.
let _remitTick = false;
async function processPaymentEmails() {
  if (_remitTick) return { busy: true }; _remitTick = true; let sent = 0, failed = 0, reclaimed = 0;
  try {
    // v28.151 (review E5): reclaim rows stuck in 'sending' > 10 min (the instance died or froze between claim and the
    // sent/failed update; they were never retried). The claim stamps send_after = claim time (no schema change), so the
    // age test is on that. Edge: a send that DID reach Resend before the crash is sent again (preferred over never).
    reclaimed = (await pool.query(`UPDATE planner.payment_emails SET status='queued', error='reclaimed after a stalled send' WHERE status='sending' AND send_after < now() - interval '10 minutes'`)).rowCount;
    if (reclaimed) console.warn('[payment-emails] reclaimed ' + reclaimed + ' stalled sending row(s)');
    const due = (await pool.query(`SELECT id FROM planner.payment_emails WHERE status='queued' AND send_after<=now() ORDER BY id LIMIT 20`)).rows;
    for (const d of due) {
      // claim (skip if someone else took it)
      const claim = await pool.query(`UPDATE planner.payment_emails SET status='sending', send_after=now() WHERE id=$1 AND status='queued' RETURNING *`, [d.id]);
      const row = claim.rows[0]; if (!row) continue;
      try { const r = await sendPaymentNotify(row);
        if (r && r.error) { failed++; await pool.query(`UPDATE planner.payment_emails SET status='failed', error=$2 WHERE id=$1`, [row.id, String(r.error).slice(0, 300)]); }
        else { sent++; await pool.query(`UPDATE planner.payment_emails SET status='sent', sent_at=now(), error=null WHERE id=$1`, [row.id]); }
      } catch (e) { failed++; await pool.query(`UPDATE planner.payment_emails SET status='failed', error=$2 WHERE id=$1`, [row.id, String(e.message || e).slice(0, 300)]); }
    }
  } catch (e) { console.error('[payment-emails] worker error:', e && e.message); }
  finally { _remitTick = false; }
  return { sent, failed, reclaimed };
}
// v28.151 (review E5): the 30s timer runs on the long-lived server only. On Vercel a timer fires on frozen/idle containers
// (pooled connection opened with no request = the stranded-connection pattern) and simply never runs when no instance
// is warm, so prod needs a scheduler hitting the cron route below (n8n every 1-2 min, webhook-secret gated like the others).
// Coordinator safety: prod keeps the in-process timer (today's behaviour) until the scheduler exists; Diviyaj sets
// PAYMENT_EMAIL_CRON=1 once n8n hits /api/cron/payment-emails, which turns the Vercel timer off.
if (!process.env.VERCEL || process.env.PAYMENT_EMAIL_CRON !== '1') setInterval(processPaymentEmails, 30000).unref?.();
app.post('/api/cron/payment-emails', async (req, res) => {
  const secret = process.env.N8N_WEBHOOK_SECRET; if (!secret || req.get('x-webhook-secret') !== secret) return res.status(401).json({ error: 'unauthorized' });
  try { res.json(Object.assign({ ok: true }, await processPaymentEmails())); } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});

// Admin PO ▸ DOCUMENTS tab: approve / reject a supplier-submitted document (with notes). Rejection returns the
// doc to a re-submittable state; the notes are kept so the portal shows why. Posts an INTERNAL timeline note
// (shows as an unread action for the supplier in the portal) so the decision flows both ways.
app.post('/api/supply/po-doc-review', async (req, res) => {
  const b = req.body || {}; const id = b.id, decision = (b.decision === 'rejected') ? 'rejected' : 'approved';
  const notes = String(b.notes || '').trim();
  if (!id) return res.status(400).json({ error: 'id required' });
  try {
    const doc = (await pool.query(`UPDATE planner.portal_attachments
        SET approval_status=$2, review_notes=$3, reviewed_by=$4, reviewed_at=now()
        WHERE id=$1 RETURNING po, coalesce(filename,'document') filename`, [id, decision, notes || null, internalAuthor(req, b.reviewed_by)])).rows[0];
    if (doc && doc.po) {
      const verb = decision === 'approved' ? 'Approved' : 'Rejected';
      const tail = decision === 'rejected' ? ' — please revise & re-submit' : '';
      const body = verb + ' document “' + doc.filename + '”' + tail + (notes ? (' — ' + notes) : '');
      try { await pool.query(`INSERT INTO planner.supplier_notes (po, author_email, author_kind, body) VALUES ($1,$2,'internal',$3)`,
        [doc.po, internalAuthor(req, b.reviewed_by), body]); } catch (e) { /* timeline best-effort */ }
    }
    res.json({ ok: true });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
app.post('/api/supply/portal-submit', async (req, res) => {
  const b = req.body || {}; const sid = b.supplier_id || null, by = b.submitted_by || 'portal';
  if (!b.po) return res.status(400).json({ error: 'po required' });
  // validate up front (before opening a transaction) — a bad status must fail loudly, not be silently dropped
  if (b.production_status != null) {
    const st = String(b.production_status).trim();
    if (st !== '' && !PROD_STATUSES.includes(st)) return res.status(400).json({ error: 'bad production_status' });
  }
  // reject a non-numeric invoice value up front (commas/currency are stripped; letters/garbage are refused)
  if (b.invoice_value != null && String(b.invoice_value).trim() !== '' && sanitiseMoney(b.invoice_value) == null) return res.status(400).json({ error: 'Invoice value must be a number (no currency symbols or letters).' });
  const out = { staged: [], applied: [] }; let _invoiceSubmit = null;
  // one transaction for the whole submit so a mid-way failure can't leave a half-created shipment / orphan PO
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const stage = async (kind, value, attId) => {
      if (value == null || value === '') return;
      // supersede any earlier still-pending submission of the same kind for this PO so only the latest is actionable
      await client.query(`UPDATE planner.supplier_submissions SET status='superseded'
        WHERE po=$1 AND kind=$2 AND status='pending'`, [b.po, kind]);
      await client.query(`INSERT INTO planner.supplier_submissions (supplier_id, po, kind, value, attachment_id, status, submitted_by)
        VALUES ($1,$2,$3,$4,$5,'pending',$6)`, [sid, b.po, kind, String(value), attId || null, by]);
      out.staged.push(kind);
      // invoice / completion info → visible unread timeline note (+ email for invoices)
      if (kind === 'invoice_value' || kind === 'completion_date') await postSupplierSubmitNote(client, b.po, kind, value, by);
      if (kind === 'invoice_value') _invoiceSubmit = String(value);
    };
    await stage('completion_date', b.completion_date);
    await stage('invoice_value', b.invoice_value == null ? null : sanitiseMoney(b.invoice_value), b.invoice_attachment_id);
    // tracking / carrier → applies to the PO's SHIPMENT (not the PO). If the PO has no shipment yet, the
    // supplier's submission CREATES a master shipment named after the PO and assigns this PO to it, so the
    // carrier/tracking flows straight onto that new shipment (and it shows up in the portal Shipment Plan).
    if (b.tracking != null && b.tracking !== '' || b.carrier != null && b.carrier !== '') {
      const sh = (await client.query(`SELECT shipment_ref FROM planner.purchase_orders WHERE po=$1`, [b.po])).rows[0];
      let ref = b.shipment_ref || (sh && sh.shipment_ref);
      if (!ref) {
        ref = b.po;   // master shipment ref = the PO number
        await client.query(`INSERT INTO planner.shipments (shipment_ref, master_po, supplier_created_at, supplier_created_by)
          VALUES ($1,$1,now(),$2) ON CONFLICT (shipment_ref) DO UPDATE SET supplier_created_at=now(), supplier_created_by=$2`, [ref, by]);
        await client.query(`UPDATE planner.purchase_orders SET shipment_ref=$1 WHERE po=$1`, [b.po]);
        out.applied.push('shipment created + assigned → ' + ref);
      }
      const sets = [], vals = []; let i = 1;
      if (b.tracking != null && b.tracking !== '') { sets.push(`carrier_ref=$${i++}`); vals.push(b.tracking); }
      if (b.carrier != null && b.carrier !== '') { sets.push(`carrier=$${i++}`); vals.push(b.carrier); }
      if (sets.length) { vals.push(ref);
        await client.query(`UPDATE planner.shipments SET ${sets.join(',')}, updated_at=now() WHERE shipment_ref=$${i}`, vals); }
      await client.query(`INSERT INTO planner.supplier_submissions (supplier_id, po, shipment_ref, kind, value, status, submitted_by, applied_by, applied_at)
        VALUES ($1,$2,$3,'tracking',$4,'applied',$5,$5,now())`, [sid, b.po, ref, JSON.stringify({ tracking: b.tracking || null, carrier: b.carrier || null }), by]);
      out.applied.push('tracking/carrier → ' + ref);
      // shipment details also land on the PO timeline as a readable supplier message (author = the exact portal user)
      const _shipParts = []; if (b.carrier) _shipParts.push('carrier ' + b.carrier); if (b.tracking) _shipParts.push('tracking ' + b.tracking);
      if (_shipParts.length) try { await client.query(`INSERT INTO planner.supplier_notes (po, supplier_id, author_email, author_kind, body) VALUES ($1,$2,$3,'supplier',$4)`,
        [b.po, sid, by || null, 'Supplier submitted shipment details — ' + _shipParts.join(', ')]); } catch (e) { /* timeline note best-effort */ }
    }
    // supplier production status (validated above) — '' clears it
    if (b.production_status != null) {
      const st = String(b.production_status).trim();
      await client.query(`UPDATE planner.purchase_orders SET production_status=$2,
        production_confirmed_at=CASE WHEN $2='' THEN NULL ELSE now() END WHERE po=$1`, [b.po, st]);
      out.applied.push('production status → ' + (st || 'cleared'));
      // master PO marked shipped → its shipment advances to Shipping (master POs only)
      if (st === 'shipped') { const shref = await shipmentShippingFromMasterPO(client, b.po); if (shref) out.applied.push('shipment ' + shref + ' → Shipping'); }
    }
    // PO confirmation (#supplier confirms SKUs / qty / dates). po_confirmed:true → confirm; false → clear (re-request).
    if (b.po_confirmed != null) {
      if (b.po_confirmed) { await client.query(`UPDATE planner.purchase_orders
          SET supplier_confirmed_at=now(), supplier_confirmed_by=$2,
              approved_lines=(SELECT jsonb_object_agg(sku, qty) FROM planner.purchase_order_lines WHERE po=$1 AND coalesce(qty,0)>0)
          WHERE po=$1`, [b.po, by]); out.applied.push('PO confirmed'); }   // snapshot the SKUs/qtys the supplier approved → diff against on re-approval
      else { await client.query(`UPDATE planner.purchase_orders SET supplier_confirmed_at=NULL, supplier_confirmed_by=NULL WHERE po=$1`, [b.po]); out.applied.push('PO confirmation cleared'); }
    }
    await client.query('COMMIT');
    if (_invoiceSubmit != null && !(await invoiceSubmitIsRepeat(b.po, _invoiceSubmit))) await emailInvoiceSubmit(b.po, _invoiceSubmit, by).catch(() => {});   // skip duplicate emails from repeated Submit clicks with the same amount
    res.json(out);
  } catch (e) { await client.query('ROLLBACK').catch(()=>{}); res.status(500).json({ error: e.message }); }
  finally { client.release(); }
});
// ── Supplier invoice/packing .xlsx parsing (pure Node — no external dependency) ──────────────────────────
// Unzip an .xlsx via the ZIP central directory (handles stored + deflate; robust to data descriptors).
function unzipXlsx(buf) {
  const files = {};
  let eocd = -1;
  for (let i = buf.length - 22; i >= 0; i--) { if (buf.readUInt32LE(i) === 0x06054b50) { eocd = i; break; } }
  if (eocd < 0) throw new Error('not a valid .xlsx (no zip directory)');
  const cdOff = buf.readUInt32LE(eocd + 16), cdCount = buf.readUInt16LE(eocd + 10);
  let p = cdOff;
  for (let n = 0; n < cdCount && p + 46 <= buf.length; n++) {
    if (buf.readUInt32LE(p) !== 0x02014b50) break;
    const method = buf.readUInt16LE(p + 10), compSize = buf.readUInt32LE(p + 20);
    const nameLen = buf.readUInt16LE(p + 28), extraLen = buf.readUInt16LE(p + 30), commentLen = buf.readUInt16LE(p + 32);
    const lho = buf.readUInt32LE(p + 42), name = buf.toString('utf8', p + 46, p + 46 + nameLen);
    const lNameLen = buf.readUInt16LE(lho + 26), lExtraLen = buf.readUInt16LE(lho + 28);
    const dataStart = lho + 30 + lNameLen + lExtraLen, raw = buf.subarray(dataStart, dataStart + compSize);
    try { files[name] = method === 0 ? raw : zlib.inflateRawSync(raw); } catch (e) { /* skip unreadable entry */ }
    p += 46 + nameLen + extraLen + commentLen;
  }
  return files;
}
// Parse a supplier invoice workbook → { po, lines:[{sku, qty, price}] }. Scans every worksheet for a header row
// with SKU + a Q'TY (PCS) column + a Unit Price column, then reads the line items below it.
function parseInvoiceXlsx(buf) {
  const f = unzipXlsx(buf);
  const dec = s => String(s).replace(/&amp;/g, '&').replace(/&#10;/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&apos;|&#39;/g, "'");   // v27.707: &apos; (Excel writes "Q'TY" this way) was left encoded → header never matched
  const ss = [];
  const ssXml = f['xl/sharedStrings.xml'] ? f['xl/sharedStrings.xml'].toString('utf8') : '';
  for (const m of ssXml.matchAll(/<si>([\s\S]*?)<\/si>/g)) { ss.push(dec([...m[1].matchAll(/<t[^>]*>([\s\S]*?)<\/t>/g)].map(x => x[1]).join('')).trim()); }
  const colNum = ref => { const c = ref.match(/^[A-Z]+/)[0]; let n = 0; for (const ch of c) n = n * 26 + (ch.charCodeAt(0) - 64); return n; };
  const sheetRows = xml => { const rows = {};
    for (const rm of xml.matchAll(/<row[^>]*r="(\d+)"[^>]*>([\s\S]*?)<\/row>/g)) { const rn = +rm[1], cells = {};
      for (const cm of rm[2].matchAll(/<c r="([A-Z]+\d+)"(?:[^>]*t="([^"]*)")?[^>]*>(?:<v>([\s\S]*?)<\/v>|<is><t[^>]*>([\s\S]*?)<\/t><\/is>)?<\/c>/g)) {
        const t = cm[2], v = cm[3], inl = cm[4]; let val = ''; if (inl != null) val = dec(inl); else if (v != null) val = t === 's' ? (ss[+v] || '') : v;
        cells[colNum(cm[1])] = String(val).trim(); }
      rows[rn] = cells; }
    return rows; };
  const sheetNames = Object.keys(f).filter(k => /^xl\/worksheets\/sheet\d+\.xml$/.test(k)).sort();
  for (const sn of sheetNames) {
    const rows = sheetRows(f[sn].toString('utf8'));
    const rns = Object.keys(rows).map(Number).sort((a, b) => a - b);
    let hr, sc, qc, pc;
    for (const rn of rns) { const e = Object.entries(rows[rn]);
      const sk = e.find(([k, v]) => /^sku$/i.test(v)); if (!sk) continue;
      const qt = e.find(([k, v]) => /q['’‘]?ty/i.test(v) && /pcs/i.test(v));   // v27.707: straight, curly or no apostrophe
      const pr = e.find(([k, v]) => /unit\s*price/i.test(v));
      if (sk && qt && pr) { hr = rn; sc = +sk[0]; qc = +qt[0]; pc = +pr[0]; break; } }
    if (!hr) continue;   // not the invoice sheet
    let po = ''; for (const rn of rns) { const c = rows[rn]; for (const k in c) { if (/invoice\s*no/i.test(c[k])) po = (c[+k + 1] || '').trim(); } if (po) break; }
    const raw = [];
    for (const rn of rns) { if (rn <= hr) continue; const c = rows[rn];
      const sku = (c[sc] || '').trim(), qty = Number(c[qc]), price = Number(c[pc]);
      if (sku && /^[A-Za-z0-9][\w\-\.]*$/.test(sku) && qty > 0) raw.push({ sku, qty, price: isFinite(price) && price > 0 ? price : null, row: rn }); }
    // v27.707 (Ben, PO-57USLX4): a SKU can appear on SEVERAL invoice lines (e.g. 40 + 70 + 100). Previously the last line
    // silently won on apply. Now duplicate SKUs are SUMMED into one line (unit price kept when identical, else the
    // qty-weighted average, flagged price_mixed) and reported in `duplicates` so every surface can warn loudly.
    const bySku = {}, order = [];
    raw.forEach(l => { const k = l.sku.toUpperCase(); if (!bySku[k]) { bySku[k] = { sku: l.sku, qty: 0, val: 0, priced: 0, parts: [] }; order.push(k); }
      const g = bySku[k]; g.qty += l.qty; g.parts.push({ qty: l.qty, price: l.price, row: l.row }); if (l.price != null) { g.val += l.qty * l.price; g.priced += l.qty; } });
    const duplicates = [];
    const lines = order.map(k => { const g = bySku[k];
      let price = null, mixed = false;
      if (g.priced > 0) { const ps = g.parts.filter(p => p.price != null).map(p => p.price); mixed = ps.some(p => Math.abs(p - ps[0]) > 0.00001); price = mixed ? Math.round(g.val / g.priced * 10000) / 10000 : ps[0]; }
      if (g.parts.length > 1) duplicates.push({ sku: g.sku, lines: g.parts.map(p => p.qty), prices: g.parts.map(p => p.price), qty: g.qty, price, price_mixed: mixed, rows: g.parts.map(p => p.row) });
      return { sku: g.sku, qty: g.qty, price, dup: g.parts.length > 1, dup_lines: g.parts.length > 1 ? g.parts.map(p => p.qty) : null, price_mixed: mixed }; });
    return { po, lines, duplicates };
  }
  return { po: '', lines: [], duplicates: [] };
}
// One-line human summary of duplicate invoice SKUs — shared by the preview, the apply note, the record of change and the email.
function invoiceDupSummary(dups) { return (dups || []).map(d => d.sku + ': ' + d.lines.join(' + ') + ' = ' + d.qty + (d.price_mixed ? ' (mixed unit prices → weighted avg ' + d.price + ')' : '')).join('; '); }
// Parse an uploaded supplier invoice and PREVIEW it against the PO's current order plan (no DB write).
const _invoiceParseHandler = async (req, res) => {   // v27.707: shared by the admin route and the supplier-portal route below
  const b = req.body || {};
  if (!b.data_base64 && !b.storage_path) return res.status(400).json({ error: 'data_base64 required' });
  try {
    const buf = await resolveUploadBytes(b, { maxInline: 20 * 1024 * 1024 });
    const parsed = parseInvoiceXlsx(buf);
    if (!parsed.lines.length) return res.json({ ok: false, error: 'No invoice line items found — need a sheet with SKU / Q’TY (PCS) / Unit Price columns.' });
    const po = b.po || parsed.po;
    const plan = po ? (await pool.query(`SELECT sku, qty, cost_price FROM planner.purchase_order_lines WHERE po=$1`, [po])).rows : [];
    const planBy = {}; plan.forEach(l => { planBy[String(l.sku).toUpperCase()] = l; });
    const lines = parsed.lines.map(l => { const cur = planBy[l.sku.toUpperCase()];
      const cq = cur ? Number(cur.qty) : null, cc = cur ? Number(cur.cost_price) : null;
      const status = !cur ? 'new' : ((cq !== l.qty || (l.price != null && cc !== l.price)) ? 'changed' : 'match');
      return { sku: l.sku, inv_qty: l.qty, inv_price: l.price, cur_qty: cq, cur_cost: cc, status, dup: !!l.dup, dup_lines: l.dup_lines || null, price_mixed: !!l.price_mixed }; });
    // plan SKUs NOT on the invoice → propose qty 0 (they weren't shipped/invoiced)
    const invSkus = new Set(parsed.lines.map(l => l.sku.toUpperCase()));
    const removed = plan.filter(l => !invSkus.has(String(l.sku).toUpperCase()) && Number(l.qty) > 0)
      .map(l => ({ sku: l.sku, inv_qty: 0, inv_price: null, cur_qty: Number(l.qty), cur_cost: (l.cost_price != null ? Number(l.cost_price) : null), status: 'removed' }));
    const allLines = lines.concat(removed);
    res.json({ ok: true, po_detected: parsed.po,
      totals: { count: lines.length, qty: lines.reduce((s, r) => s + r.inv_qty, 0), value: Math.round(lines.reduce((s, r) => s + r.inv_qty * (r.inv_price || 0), 0) * 100) / 100,
        matched: lines.filter(r => r.status !== 'new').length, changed: lines.filter(r => r.status === 'changed').length, neu: lines.filter(r => r.status === 'new').length, removed: removed.length },
      lines: allLines,
      duplicates: parsed.duplicates || [], duplicate_summary: invoiceDupSummary(parsed.duplicates) });   // v27.707 duplicate SKU lines (summed) → warn on every surface
  } catch (e) { res.status(400).json({ error: 'Could not parse the file: ' + e.message }); }
};
app.post('/api/supply/portal-parse-invoice', _invoiceParseHandler);
// Apply a parsed supplier invoice to the PO's order plan as portal overrides (amended_qty / actual_cost). Re-parses
// the file server-side (single source of truth), writes only CHANGED + NEW lines (new SKUs flagged is_added), in a
// transaction. The supplier then reviews/confirms in the portal; the planner approves the order-plan change (existing flow).
const _invoiceApplyHandler = async (req, res) => {   // v27.707: shared by the admin route and the supplier-portal route below
  const b = req.body || {}; const by = b.submitted_by || 'portal';
  if (!b.data_base64 && !b.storage_path) return res.status(400).json({ error: 'data_base64 required' });
  let parsed;
  try { parsed = parseInvoiceXlsx(await resolveUploadBytes(b, { maxInline: 20 * 1024 * 1024 })); }
  catch (e) { return res.status(e.status || 400).json({ error: 'Could not parse the file: ' + e.message }); }
  const po = b.po || parsed.po;
  if (!po) return res.status(400).json({ error: 'no PO (none supplied and none detected in the file)' });
  if (!parsed.lines.length) return res.status(400).json({ error: 'No invoice line items found in the file.' });
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const plan = (await client.query(`SELECT sku, qty, cost_price FROM planner.purchase_order_lines WHERE po=$1`, [po])).rows;
    const planBy = {}; plan.forEach(l => { planBy[String(l.sku).toUpperCase()] = l; });
    let applied = 0, added = 0, unchanged = 0;
    for (const l of parsed.lines) {
      const cur = planBy[l.sku.toUpperCase()];
      const cq = cur ? Number(cur.qty) : null, cc = cur ? Number(cur.cost_price) : null;
      const isNew = !cur, changed = isNew || cq !== l.qty || (l.price != null && cc !== l.price);
      if (!changed) { unchanged++; continue; }
      await client.query(`INSERT INTO planner.portal_line_costs (po, sku, actual_cost, amended_qty, is_added, submitted_by, submitted_at)
        VALUES ($1,$2,$3,$4,$5,$6, now())
        ON CONFLICT (po, sku) DO UPDATE SET actual_cost=excluded.actual_cost, amended_qty=excluded.amended_qty,
          is_added=planner.portal_line_costs.is_added OR excluded.is_added, submitted_by=excluded.submitted_by, submitted_at=now()`,
        [po, l.sku, l.price, l.qty, isNew, by]);
      applied++; if (isNew) added++;
    }
    // plan SKUs NOT on the invoice → propose amended_qty 0 (weren't shipped/invoiced). Cost left untouched on conflict.
    const invSkus = new Set(parsed.lines.map(l => l.sku.toUpperCase()));
    let zeroed = 0;
    for (const l of plan) {
      if (invSkus.has(String(l.sku).toUpperCase()) || Number(l.qty) <= 0) continue;
      await client.query(`INSERT INTO planner.portal_line_costs (po, sku, actual_cost, amended_qty, is_added, submitted_by, submitted_at)
        VALUES ($1,$2,$3,0,false,$4, now())
        ON CONFLICT (po, sku) DO UPDATE SET amended_qty=0, submitted_by=excluded.submitted_by, submitted_at=now()`,
        [po, l.sku, (l.cost_price != null ? Number(l.cost_price) : null), by]);
      applied++; zeroed++;
    }
    await client.query('COMMIT');
    // v27.707: duplicate SKU lines were SUMMED — warn loudly everywhere (timeline note both sides, record of change, pending
    // admin banner, email to D&B). Best-effort; never fails the apply.
    const dups = parsed.duplicates || [];
    if (dups.length) { const summary = invoiceDupSummary(dups);
      try { await pool.query(`INSERT INTO planner.supplier_notes (po, author_email, author_kind, body) VALUES ($1,$2,'internal',$3)`, [po, by, '⚠ Invoice had duplicate SKU lines — ' + summary + '. The quantities were SUMMED into the order plan — please check the totals against the invoice.']); } catch (e) {}
      try { await pool.query(`INSERT INTO planner.po_change_log (po,event,detail,changed_by) VALUES ($1,'Invoice duplicates',$2,$3)`, [po, summary, by]); } catch (e) {}
      try { const sid = (await pool.query(`SELECT supplier_id FROM planner.purchase_orders WHERE po=$1`, [po])).rows[0]?.supplier_id || null;
        await pool.query(`UPDATE planner.supplier_submissions SET status='superseded' WHERE po=$1 AND kind='invoice_duplicates' AND status='pending'`, [po]);
        await pool.query(`INSERT INTO planner.supplier_submissions (supplier_id, po, kind, value, status, submitted_by) VALUES ($1,$2,'invoice_duplicates',$3,'pending',$4)`, [sid, po, JSON.stringify({ summary, duplicates: dups, by, at: new Date().toISOString() }), by]); } catch (e) {}
      try { let emails = []; try { const s = (await pool.query(`SELECT value FROM planner.app_settings WHERE key='invoice_submit_notify'`)).rows[0]; emails = _emails(s ? s.value : ''); } catch (e) {} if (!emails.length) emails = ['zera@dockandbay.com', 'ben@dockandbay.com'];
        const supName = await poSupplierName(po); const link = PLANNER_URL + '/#/supply/purchase-orders/' + encodeURIComponent(po) + '/order-plan';
        const html = '<p style="color:#b45309"><b>⚠ Duplicate SKU lines on the invoice for ' + po + '</b> (' + escHtml(supName) + ').</p><p>The same SKU appeared on more than one invoice line. HORIZON <b>summed</b> them into the order plan — please check:</p><ul>' + dups.map(d => '<li><b>' + escHtml(d.sku) + '</b>: ' + d.lines.join(' + ') + ' = <b>' + d.qty + '</b>' + (d.price_mixed ? ' <i>(mixed unit prices → weighted average ' + d.price + ')</i>' : '') + '</li>').join('') + '</ul><p>Applied by: ' + escHtml(by || 'portal') + '</p><p><a href="' + link + '">Open the Order plan for ' + po + '</a></p>';
        await sendResendEmail({ to: emails, subject: '⚠ Duplicate SKU lines on invoice — ' + po + ' (' + supName + ')', html, kind: 'invoice-notify', ref: po, replyTo: by }); } catch (e) {} }
    res.json({ ok: true, po, applied, added, unchanged, zeroed, total: parsed.lines.length, duplicates: dups, duplicate_summary: invoiceDupSummary(dups) });
  } catch (e) { await client.query('ROLLBACK').catch(() => {}); res.status(500).json({ error: e.message }); }
  finally { client.release(); }
};
app.post('/api/supply/portal-invoice-apply', _invoiceApplyHandler);
// v27.707: the REAL supplier portal had no route for these (only the admin "view as supplier" preview did) — portal-scoped
