// Payments made to a supplier (payment ledger) — feeds the CONFIG ▸ Portal preview's master PAYMENTS tab (the
// real portal gets the same data via /api/portal/bootstrap).
app.get('/api/supply/supplier-payments/:name', async (req, res) => {
  // DERIVED from the same source-of-truth as the admin Payments Report + the real portal bootstrap: PO
  // completion + balance milestones, the deposit register, and Other payments (NOT the import-only
  // payment_transactions ledger, which misses plan-entered dates/amounts). Starting deposits excluded.
  const nm = [String(req.params.name || '').toLowerCase().trim()];
  try { res.json(await pool.query(`SELECT dt payment_date, dt payment_run_ref, reference, type, amount, deposit_ref FROM (
      SELECT to_char(o.pay_completion_date,'YYYY-MM-DD') dt, o.po reference, round(o.pay_completion_assigned,2) amount, 'Completion' type, coalesce(o.deposit_ref,'') deposit_ref
        FROM planner.purchase_orders o WHERE o.pay_completion_date IS NOT NULL AND coalesce(o.pay_completion_assigned,0)>0 AND lower(trim(o.supplier_name))=ANY($1)
      UNION ALL
      SELECT to_char(o.pay_balance_1_date,'YYYY-MM-DD'), o.po, round(o.pay_balance_1_amount,2), 'Balance', coalesce(o.deposit_ref,'')
        FROM planner.purchase_orders o WHERE o.pay_balance_1_date IS NOT NULL AND coalesce(o.pay_balance_1_amount,0)>0 AND lower(trim(o.supplier_name))=ANY($1)
      UNION ALL
      SELECT to_char(o.pay_balance_2_date,'YYYY-MM-DD'), o.po, round(o.pay_balance_2_amount,2), 'Balance', coalesce(o.deposit_ref,'')
        FROM planner.purchase_orders o WHERE o.pay_balance_2_date IS NOT NULL AND coalesce(o.pay_balance_2_amount,0)>0 AND lower(trim(o.supplier_name))=ANY($1)
      UNION ALL
      SELECT to_char(date_paid,'YYYY-MM-DD'), coalesce(nullif(reference,''), description, ''), round(amount,2), 'Deposit', ''
        FROM planner.deposits WHERE is_deposit=true AND date_paid IS NOT NULL AND round(coalesce(amount,0))<>0 AND lower(trim(supplier_name))=ANY($1)
      UNION ALL
      SELECT to_char(date_paid,'YYYY-MM-DD'), coalesce(nullif(reference,''), description, ''), round(amount,2), 'Other', ''
        FROM planner.deposits WHERE is_deposit=false AND date_paid IS NOT NULL AND round(coalesce(amount,0))<>0 AND lower(trim(supplier_name))=ANY($1)
    ) t ORDER BY payment_date DESC NULLS LAST`, [nm]).then(r => r.rows)); }
  catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// Internal one-click apply / dismiss of a staged supplier submission (Phase 4). Apply writes to the live PO
// (the internal click is the confirmation); completion_date → end_production_overide, invoice_value → supplier_invoice_total.
app.post('/api/supply/submission/:id/apply', async (req, res) => {
  try {
    const s = (await pool.query(`SELECT * FROM planner.supplier_submissions WHERE id=$1`, [req.params.id])).rows[0];
    if (!s) return res.status(404).json({ error: 'no such submission' });
    // allow (re)apply on pending OR already-applied (e.g. the final was later edited and needs re-syncing);
    // only a rejected/dismissed submission can't be applied.
    if (s.status === 'dismissed') return res.status(400).json({ error: 'this submission was rejected' });
    // Attribute the real approver (the logged-in D&B user) — was recorded as a generic 'PO PLAN' from the client.
    const by = authUser(req) || (req.body && req.body.by) || 'internal';
    const _origin = ' (supplier submission' + (s.submitted_by ? ' by ' + s.submitted_by : '') + ')';
    let applied, logEvent, logDetail;
    if (s.kind === 'completion_date') {
      const _o = (await pool.query(`SELECT to_char(end_production_overide,'YYYY-MM-DD') v FROM planner.purchase_orders WHERE po=$1`, [s.po])).rows[0];
      await pool.query(`UPDATE planner.purchase_orders SET end_production_overide=$1::date, updated_at=now() WHERE po=$2`, [s.value, s.po]);
      applied = 'production-end → ' + s.value;
      logEvent = 'Production end date'; logDetail = ((_o && _o.v) ? ddMonYy(_o.v) : '(none)') + ' → ' + ddMonYy(s.value) + _origin;
    }
    else if (s.kind === 'invoice_value') { const clean = sanitiseMoney(s.value); if (clean == null) return res.status(400).json({ error: 'Stored invoice value "' + s.value + '" is not a number — fix it on the PO before approving.' });
      const _o = (await pool.query(`SELECT round(supplier_invoice_total,2)::text v FROM planner.purchase_orders WHERE po=$1`, [s.po])).rows[0];
      await pool.query(`UPDATE planner.purchase_orders SET supplier_invoice_total=$1::numeric, updated_at=now() WHERE po=$2`, [clean, s.po]);
      applied = 'invoice total → $' + clean;
      logEvent = 'Final invoice amount'; logDetail = ((_o && _o.v != null) ? '$' + _o.v : '(none)') + ' → $' + clean + _origin;
    }
    else return res.status(400).json({ error: 'kind ' + s.kind + ' is not applyable here' });
    await pool.query(`UPDATE planner.supplier_submissions SET status='applied', applied_at=now(), applied_by=$1 WHERE id=$2`, [by, req.params.id]);
    // Record-of-change: applying a staged supplier submission was previously silent (no po_change_log row) —
    // so the final-invoice / production-end update never showed on the PO timeline. Now it's audited. (v27.325)
    logPoChange(s.po, logEvent, logDetail, by);
    res.json({ applied });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
