// ── 3PL Invoice (REPORTS ▸ 3PL Invoice) ─────────────────────────────────────
// 3PLs: uk_ilg | us_geneva | eu_ifulfilment (=Blade) | au_coghlans. Phase 1: uploaded invoice files per
// 3PL+month, per-3PL storage/other cost-account config, and the region×channel account map (read-only).
const TPL_KEYS = ['uk_ilg', 'us_geneva', 'eu_ifulfilment', 'au_coghlans'];
app.get('/api/supply/tpl/data', async (req, res) => {
  const tpl = String(req.query.tpl || ''), period = String(req.query.period || '');
  if (!TPL_KEYS.includes(tpl)) return res.status(400).json({ error: 'bad tpl' });
  try {
    const files = (await pool.query(`SELECT id, filename, content_type, byte_size, uploaded_by,
      to_char(uploaded_at,'YYYY-MM-DD HH24:MI') uploaded_at, parse_status
      FROM planner.tpl_invoice_files WHERE tpl=$1 AND ($2='' OR period=$2) ORDER BY uploaded_at DESC`, [tpl, period])).rows;
    const cost = (await pool.query(`SELECT cost_type, coalesce(account_code,'') account_code, coalesce(account_name,'') account_name
      FROM planner.tpl_cost_accounts WHERE tpl=$1 ORDER BY cost_type`, [tpl])).rows;
    const map = (await pool.query(`SELECT id, label, coalesce(region,'') region, coalesce(channel,'') channel,
      coalesce(cogs_account,'') cogs_account, coalesce(sales_account,'') sales_account,
      coalesce(fulfilment_account,'') fulfilment_account, coalesce(cost_of_sales_account,'') cost_of_sales_account,
      coalesce(fulfil_channel,'') fulfil_channel
      FROM planner.tpl_account_map ORDER BY region NULLS LAST, channel NULLS LAST, label`)).rows;
    const cin7_summary = /^\d{4}-\d{2}$/.test(period) ? await tplCin7Summary(period, tpl) : null;
    res.json({ ok: true, files, cost_accounts: cost, account_map: map, cin7_summary });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// 3PL Forecast tab — known inbound to this 3PL, grouped under the master SHIPMENT: shipment id, effective delivery
// date, units (Σ line qty), and a container COUNT (pallets ÷ 20 → 40ft-equivalent, rounded up). Open POs only. The
// client buckets these by delivery month for the "Goods in" column (expandable to the shipment list). Read-only.
const TPL3_BRANCH = { uk_ilg: 'UK ILG', us_geneva: 'US Geneva', eu_ifulfilment: 'EU iFulfillment', au_coghlans: 'AU Coghlans' };
app.get('/api/supply/tpl/goods-in', async (req, res) => {
  const branch = TPL3_BRANCH[String(req.query.tpl || '')] || null;
  if (!branch) return res.json({ ok: true, shipments: [] });
  try {
    const rows = (await pool.query(`
      WITH poa AS (
        SELECT p.po,
               coalesce(nullif(p.shipment_ref,''), p.po) ship_id,
               coalesce((SELECT sum(l.qty)::int FROM planner.purchase_order_lines l WHERE l.po=p.po),0) units,
               ${PO_PALLETS_EFF_SQL} pallets,
               coalesce(sh.delivery_date, sh.arrival_date, sh.landing_date, p.delivery_date_overide,
                        (SELECT min(i.estimated_delivery_date) FROM planner.inbound_shipments i WHERE i.reference=p.po)) deliv
        FROM planner.purchase_orders p
        LEFT JOIN planner.shipments sh ON sh.shipment_ref = nullif(p.shipment_ref,'')
        WHERE p.branch = $1 AND coalesce(p.status,'') NOT ILIKE '%complete%'
      )
      SELECT ship_id,
             -- overdue inbound (past date) lands NOW → clamp to the current month for bucketing. to_char so the
             -- client gets a clean 'YYYY-MM-DD' (a raw pg Date stringifies to "Tue Sep 01" and breaks month bucketing).
             to_char(greatest(min(deliv), date_trunc('month', current_date)::date), 'YYYY-MM-DD') deliv,
             sum(units)::int units, round(sum(pallets)::numeric,1) pallets,
             string_agg(distinct po, ', ' ORDER BY po) pos, count(distinct po)::int po_count
      FROM poa
      WHERE deliv IS NOT NULL
      GROUP BY ship_id
      HAVING greatest(min(deliv), date_trunc('month', current_date)::date) < (date_trunc('month', current_date) + interval '6 months')
         AND sum(units) > 0
      ORDER BY deliv`, [branch])).rows;
    const out = rows.map(r => { const pal = Number(r.pallets) || 0;
      // Not a sea container: a real AIR reference (-AIR in the ship id / PO), or a sub-pallet consignment that goes as
      // LCL (0<pallets<1, e.g. a 170-unit top-up) — show 0 containers rather than rounding a fraction up to a full one.
      const realAir = /air/i.test(r.ship_id || '') || /air/i.test(r.pos || '');
      const subPallet = !realAir && (pal > 0 && pal < 1);
      const air = realAir || subPallet;   // "not a full sea container" — drives containers:0
      return {
      ship_id: r.ship_id, deliv: r.deliv || null, units: r.units || 0,
      pallets: pal, containers: air ? 0 : (pal > 0 ? Math.ceil(pal / 20) : 0), air: air,
      fill: realAir ? 'air' : (subPallet ? 'lcl' : ''), pos: r.pos || '', po_count: r.po_count || 0 }; });
    res.json({ ok: true, shipments: out });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
app.post('/api/supply/tpl/upload', async (req, res) => {
  const b = req.body || {};
  if (!TPL_KEYS.includes(b.tpl) || !b.period || (!b.data_base64 && !b.storage_path)) return res.status(400).json({ error: 'tpl, period and data_base64/storage_path required' });
  let up; try { up = resolveUpload(b, { maxInline: 20 * 1024 * 1024 }); } catch (e) { return res.status(e.status || 400).json({ error: e.message }); }
  try {
    // Inline path: client may gzip the base64 (to beat Vercel's ~4.5MB cap) — gunzip to the ORIGINAL bytes. Storage path: no gzip.
    const buf = up.storagePath ? null : (b.gzip ? zlib.gunzipSync(up.buf) : up.buf);
    const byteSize = up.storagePath ? up.byteSize : buf.length;
    const r = await pool.query(`INSERT INTO planner.tpl_invoice_files (tpl, period, filename, content_type, content, storage_path, byte_size, uploaded_by)
      VALUES ($1,$2,$3,$4,$5,$6,$7,$8) RETURNING id`,
      [b.tpl, b.period, b.filename || 'invoice', safeMime(b.mime), buf, up.storagePath, byteSize, b.uploaded_by || null]);
    res.json({ ok: true, id: r.rows[0].id, byte_size: byteSize });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
