app.post('/api/supply/master-po/create', async (req, res) => {
  const b = req.body || {}, childPos = Array.isArray(b.child_pos) ? b.child_pos.filter(Boolean) : [];
  const supplier = String(b.supplier_name || '').trim();
  if (!supplier || childPos.length < 2) return res.status(400).json({ error: 'supplier_name and at least two child_pos required' });
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    // Every child must exist, be the same supplier, and not already be a child or a master.
    const chk = (await client.query(`SELECT p.po, f.supplier_name, p.master_po, coalesce(p.is_master,false) is_master, coalesce(p.status,'') status, coalesce(f.value_est,0)::numeric value_est,
        EXISTS (SELECT 1 FROM planner.inbound_shipments i WHERE i.reference=p.po) has_inbound
      FROM planner.purchase_orders p JOIN planner.v_po_finance f ON f.po=p.po WHERE p.po = ANY($1)`, [childPos])).rows;
    if (chk.length !== childPos.length) { await _rollback(client); return res.status(400).json({ error: 'one or more POs not found' }); }
    const bad = chk.find(r => r.master_po || r.is_master); if (bad) { await _rollback(client); return res.status(409).json({ error: bad.po + (bad.is_master ? ' is already a master' : ' is already in ' + bad.master_po) }); }
    const wrongSup = chk.find(r => String(r.supplier_name || '').trim().toLowerCase() !== supplier.toLowerCase());
    if (wrongSup) { await _rollback(client); return res.status(400).json({ error: wrongSup.po + ' is a different supplier' }); }
    const shipped = chk.find(r => r.has_inbound || /complete/i.test(r.status));   // consolidating a shipped/received PO would drop real in-transit stock or double-count
    if (shipped) { await _rollback(client); return res.status(400).json({ error: shipped.po + (shipped.has_inbound ? ' already has inbound stock — consolidate before shipping' : ' is complete') }); }
    // Biggest child by value_est, ties broken by the order they were passed in.
    const byPo = {}; chk.forEach(r => { byPo[r.po] = r; });
    let big = childPos[0]; childPos.forEach(po => { if (Number(byPo[po].value_est) > Number(byPo[big].value_est)) big = po; });
    const bigStatus = byPo[big].status, childValSum = chk.reduce((a, r) => a + Number(r.value_est || 0), 0);
    // Master number: user override if given, else biggest child's po + '-MASTER' (dedupe if it somehow exists).
    const override = String(b.master_po || '').trim();
    let mpo;
    if (override) {
      if (override.length > 60) { await _rollback(client); return res.status(400).json({ error: 'PO reference too long' }); }
      if ((await client.query(`SELECT 1 FROM planner.purchase_orders WHERE po=$1`, [override])).rowCount) { await _rollback(client); return res.status(409).json({ error: 'PO ' + override + ' already exists — choose another reference' }); }
      mpo = override;
    } else { mpo = big + '-MASTER'; let sfx = 1; while ((await client.query(`SELECT 1 FROM planner.purchase_orders WHERE po=$1`, [mpo])).rowCount) { sfx++; mpo = big + '-MASTER-' + sfx; } }
    // Build the master row by copying the biggest child's header, resetting identity/transactional columns.
    const cols = await poColumns();
    const inv = (b.invoice_total != null && b.invoice_total !== '') ? Number(b.invoice_total) : null;
    // params: $1=big(src) $2=mpo $3=inv $4=childValSum
    const selectList = cols.map(c => {
      if (c === 'po') return '$2';
      if (c === 'is_master') return 'true';
      if (c === 'master_po') return 'NULL';
      if (c === 'supplier_invoice_total') return '$3';
      if (c === 'order_value_estimation') return '$4';
      if (c === 'created_at' || c === 'updated_at') return 'now()';
      if (c === 'starred') return 'false';
      if (MPO_RESET_NULL.has(c)) return 'NULL';
      return 'src.' + c;
    });
    await client.query(`INSERT INTO planner.purchase_orders (${cols.join(',')}) SELECT ${selectList.join(',')} FROM planner.purchase_orders src WHERE src.po=$1`, [big, mpo, inv, childValSum]);
    // Consolidated lines (qty summed, cost = qty-weighted avg). po_sku kept unique per master.
    await client.query(`INSERT INTO planner.purchase_order_lines (po, sku, po_sku, qty, cost_price, carton_qty, po_status)
      SELECT $1, sku, $1||'-'||sku, sum(qty),
             CASE WHEN sum(qty)>0 THEN round(sum(qty*coalesce(cost_price,0))/sum(qty),4) ELSE max(cost_price) END,
             nullif(sum(coalesce(carton_qty,0)),0), $2
      FROM planner.purchase_order_lines WHERE po = ANY($3) GROUP BY sku`, [mpo, bigStatus, childPos]);
    // Link children (they keep their own status; the Child PO tab shows the master's status live).
    await client.query(`UPDATE planner.purchase_orders SET master_po=$1, updated_at=now() WHERE po = ANY($2)`, [mpo, childPos]);
    await client.query('COMMIT');
    invalidateSupplyCaches('po');   // v28.167: scoped
    res.json({ ok: true, master_po: mpo, biggest_child: big });
  } catch (e) { try { await client.query('ROLLBACK'); } catch (_) {} res.status(500).json({ error: e.message }); }
  finally { client.release(); }
});
app.post('/api/supply/master-po/:id/remove-child', async (req, res) => {   // detach ONE child → it becomes a normal PO again; re-sum the master's lines
  const id = req.params.id, po = String((req.body && req.body.po) || '').trim();
  if (!po) return res.status(400).json({ error: 'po required' });
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const m = (await client.query(`SELECT po, coalesce(status,'') status FROM planner.purchase_orders WHERE po=$1 AND coalesce(is_master,false)=true FOR UPDATE`, [id])).rows[0];
    if (!m) { await _rollback(client); return res.status(404).json({ error: 'master not found' }); }
    const ch = (await client.query(`SELECT 1 FROM planner.purchase_orders WHERE po=$1 AND master_po=$2`, [po, id])).rows[0];
    if (!ch) { await _rollback(client); return res.status(400).json({ error: po + ' is not a child of ' + id }); }
    await client.query(`UPDATE planner.purchase_orders SET master_po=NULL, updated_at=now() WHERE po=$1`, [po]);   // back to a normal PO
    // Re-sum the master's consolidated lines from the remaining children (empty if none left).
    await client.query(`DELETE FROM planner.purchase_order_lines WHERE po=$1`, [id]);
    await client.query(`INSERT INTO planner.purchase_order_lines (po, sku, po_sku, qty, cost_price, carton_qty, po_status)
      SELECT $1, sku, $1||'-'||sku, sum(qty),
             CASE WHEN sum(qty)>0 THEN round(sum(qty*coalesce(cost_price,0))/sum(qty),4) ELSE max(cost_price) END,
             nullif(sum(coalesce(carton_qty,0)),0), $2
      FROM planner.purchase_order_lines WHERE po IN (SELECT po FROM planner.purchase_orders WHERE master_po=$1) GROUP BY sku`, [id, m.status]);
    await client.query(`UPDATE planner.purchase_orders SET order_value_estimation=(SELECT coalesce(sum(f.value_est),0) FROM planner.purchase_orders p JOIN planner.v_po_finance f ON f.po=p.po WHERE p.master_po=$1), updated_at=now() WHERE po=$1`, [id]);
    const remaining = (await client.query(`SELECT count(*)::int n FROM planner.purchase_orders WHERE master_po=$1`, [id])).rows[0].n;
    await client.query('COMMIT');
    invalidateSupplyCaches('po');   // v28.167: scoped
    res.json({ ok: true, remaining });
  } catch (e) { try { await client.query('ROLLBACK'); } catch (_) {} res.status(500).json({ error: e.message }); }
  finally { client.release(); }
});
app.post('/api/supply/master-po/:id/dissolve', async (req, res) => {   // undo: remove the master row + lines, free the children
  const id = req.params.id;
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const m = (await client.query(`SELECT po FROM planner.purchase_orders WHERE po=$1 AND coalesce(is_master,false)=true`, [id])).rows[0];
    if (!m) { await _rollback(client); return res.status(404).json({ error: 'master not found' }); }
    await client.query(`UPDATE planner.purchase_orders SET master_po=NULL, updated_at=now() WHERE master_po=$1`, [id]);
    await client.query(`DELETE FROM planner.purchase_order_lines WHERE po=$1`, [id]);
    await client.query(`DELETE FROM planner.purchase_orders WHERE po=$1 AND coalesce(is_master,false)=true`, [id]);
    await client.query('COMMIT');
    invalidateSupplyCaches('po');   // v28.167: scoped
    res.json({ ok: true });
  } catch (e) { try { await client.query('ROLLBACK'); } catch (_) {} res.status(500).json({ error: e.message }); }
  finally { client.release(); }
});

app.post('/api/supply/dtc/review', async (req, res) => {   // per-order note / accept-discrepancy
  const b = req.body || {}, id = b.so_cin7_id; if (!id) return res.status(400).json({ error: 'so_cin7_id required' });
  try { await pool.query(`INSERT INTO planner.dtc_mismatch_review (so_cin7_id,note,accepted,accepted_by,updated_at) VALUES ($1,$2,$3,$4,now())
      ON CONFLICT (so_cin7_id) DO UPDATE SET note=coalesce(excluded.note,planner.dtc_mismatch_review.note), accepted=excluded.accepted, accepted_by=excluded.accepted_by, updated_at=now()`,
      [id, (b.note != null ? String(b.note) : null), !!b.accepted, !!b.accepted ? authUser(req) : null]);
    res.json({ ok: true }); } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// Normalise a sales-order ref for matching: trim, collapse inner whitespace, uppercase.
function _dtcNorm(s) { return String(s == null ? '' : s).trim().replace(/\s+/g, ' ').toUpperCase(); }
// Parse a (possibly packed) Cin7 sales_order_ref into individual normalised refs. Cin7 packs several SO refs into one
// field, e.g. "JLEW11511-59, JLEW11511-63", "A and B", or "A / B". Split on comma/semicolon/slash, the word "and"
// (space-delimited), and runs of 2+ spaces; single spaces inside a ref are preserved ("Smiley - Galleria Order").
function _dtcParseRefs(s) { return String(s == null ? '' : s).split(/\s*[,;\/]\s*|\s+and\s+|\s{2,}/i).map(_dtcNorm).filter(Boolean); }
// The mismatch report: OPEN DTC sales orders (not void, not dispatched) reconciled against their POs. Links come from
// the PO's (possibly packed) sales_order_ref PLUS the in-app planner.dtc_po_so_map (mig 254). Because a PO can serve
// several SOs and an SO several POs, we build the SO<->PO graph and reconcile by CONNECTED COMPONENT (group): grouped
// SO SKU/qty vs grouped PO SKU/qty. Issue 1 = a group with SOs but no PO; Issue 2 = grouped SKU/qty mismatch.
app.get('/api/supply/dtc/mismatch', async (req, res) => {
  const countOnly = !!(req.query && req.query.count);
  // v28.081: the badge (?count=1) is served from a 10-min SWR memo (was a full 9s reconciliation on every page load); the
  // full report still runs live. Any supply edit marks the memo stale (invalidateSupplyCaches → swrStale('sup:')).
  if (countOnly) { try { return res.json(await swrGet('sup:dtc-count', 10 * 60 * 1000, () => _dtcMismatchCompute(true))); } catch (e) { log500(e); return res.status(500).json({ error: e.message }); } }
  try { return res.json(await _dtcMismatchCompute(false)); } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
async function _dtcMismatchCompute(countOnly) {
  {
    const sos = (await pool.query(`SELECT s.cin7_id, s.reference, s.customer_order_no, s.branch_name, s.company, to_char(s.created_date,'DD-Mon-YY') created_date,
        coalesce(r.note,'') note, coalesce(r.accepted,false) accepted, coalesce(r.accepted_by,'') accepted_by
      FROM planner.dtc_sales_orders s LEFT JOIN planner.dtc_mismatch_review r ON r.so_cin7_id=s.cin7_id
      WHERE NOT s.is_void AND s.dispatched_date IS NULL ORDER BY s.created_date DESC NULLS LAST`)).rows;
    if (!sos.length) return { groups: [], unmapped_pos: [], counts: { issues: 0, accepted: 0, ok: 0, unmapped_pos: 0 } };
    const soByRef = {};   // normalised SO ref -> the open SO row
    sos.forEach(s => { const k = _dtcNorm(s.reference); if (k) soByRef[k] = s; });
    const ids = sos.map(s => s.cin7_id);
    const soLineMap = {};
    (await pool.query(`SELECT so_cin7_id, code, sum(qty) qty FROM planner.dtc_sales_order_lines WHERE so_cin7_id = ANY($1) GROUP BY so_cin7_id, code`, [ids])).rows
      .forEach(l => { (soLineMap[l.so_cin7_id] = soLineMap[l.so_cin7_id] || {})[l.code] = Number(l.qty) || 0; });

    // Candidate POs: open DTC-branch POs, plus any PO named in the app map. Parse their refs into SO edges.
    const DTC_BRANCH_NAMES = Object.values(DTC_BRANCHES);
    const candPos = (await pool.query(`
      SELECT p.po, coalesce(p.sales_order_ref,'') sales_order_ref, coalesce(p.supplier_name,'') supplier,
             coalesce(p.branch,'') branch, coalesce(p.country_code,'') country_code, coalesce(p.status,'') status
      FROM planner.purchase_orders p
      WHERE (p.branch = ANY($1) OR p.po IN (SELECT po FROM planner.dtc_po_so_map))
        AND coalesce(p.status,'') NOT ILIKE '%complete%' AND coalesce(p.status,'') NOT ILIKE '%cancel%' AND coalesce(p.status,'') NOT ILIKE '%void%'`,
      [DTC_BRANCH_NAMES])).rows;
    const poMeta = {};
    candPos.forEach(p => { poMeta[p.po] = { supplier: p.supplier, branch: p.branch, country_code: p.country_code, status: p.status }; });
    // App map: link=true adds an edge, link=false suppresses one (lets you correct a wrong Cin7 ref in-app).
    const appRows = (await pool.query(`SELECT po, sales_order_ref, link FROM planner.dtc_po_so_map`)).rows;
    const suppress = new Set(); const appAdd = {};
    appRows.forEach(a => { const k = _dtcNorm(a.sales_order_ref); if (!k) return; if (a.link === false) suppress.add(a.po + '|' + k); else (appAdd[a.po] = appAdd[a.po] || []).push(k); });
    const poToSo = {};   // po -> Set(normalised open-SO ref)
    function addEdge(po, k) { if (!k || !soByRef[k] || suppress.has(po + '|' + k)) return; (poToSo[po] = poToSo[po] || new Set()).add(k); }
    const cin7EdgeSet = new Set();   // "po|ref" edges that came from Cin7's sales_order_ref (vs the app map) — for the "app-mapped" badge
    candPos.forEach(p => { _dtcParseRefs(p.sales_order_ref).forEach(k => { if (soByRef[k] && !suppress.has(p.po + '|' + k)) cin7EdgeSet.add(p.po + '|' + k); addEdge(p.po, k); }); });
    Object.keys(appAdd).forEach(po => { appAdd[po].forEach(k => addEdge(po, k)); });
    // App-mapped POs that weren't candidates (e.g. non-DTC branch) still need metadata for display.
    const missMeta = Object.keys(appAdd).filter(po => !poMeta[po] && poToSo[po]);
    if (missMeta.length) (await pool.query(`SELECT po, coalesce(supplier_name,'') supplier, coalesce(branch,'') branch, coalesce(country_code,'') country_code, coalesce(status,'') status FROM planner.purchase_orders WHERE po = ANY($1)`, [missMeta])).rows
      .forEach(p => { poMeta[p.po] = { supplier: p.supplier, branch: p.branch, country_code: p.country_code, status: p.status }; });

    // Connected components over the bipartite SO<->PO graph. Nodes: 'S:'+ref, 'P:'+po. Every open SO is a node.
    const adj = {};
    function link(a, b) { (adj[a] = adj[a] || new Set()).add(b); (adj[b] = adj[b] || new Set()).add(a); }
    Object.keys(soByRef).forEach(k => { adj['S:' + k] = adj['S:' + k] || new Set(); });
    Object.keys(poToSo).forEach(po => { poToSo[po].forEach(k => link('P:' + po, 'S:' + k)); });
    const seen = new Set(); const comps = [];
    Object.keys(adj).forEach(n => { if (seen.has(n)) return; const stack = [n], comp = []; seen.add(n);
      while (stack.length) { const x = stack.pop(); comp.push(x); adj[x].forEach(y => { if (!seen.has(y)) { seen.add(y); stack.push(y); } }); }
      comps.push(comp); });

    const compPos = new Set(); comps.forEach(c => c.forEach(n => { if (n[0] === 'P') compPos.add(n.slice(2)); }));
    const allPos = Array.from(compPos), poLineByPo = {};
    if (allPos.length) (await pool.query(`SELECT po, sku, sum(qty) qty FROM planner.purchase_order_lines WHERE po = ANY($1) GROUP BY po, sku`, [allPos])).rows
      .forEach(l => { (poLineByPo[l.po] = poLineByPo[l.po] || {})[l.sku] = (poLineByPo[l.po][l.sku] || 0) + (Number(l.qty) || 0); });
    const lastNoteByPo = {}, noteCountByPo = {};
    if (!countOnly && allPos.length) {
      (await pool.query(`SELECT DISTINCT ON (po) po, body, coalesce(author_email,'') author_email, coalesce(author_kind,'') author_kind,
          to_char(created_at,'DD-Mon-YY HH24:MI') at, created_at FROM planner.supplier_notes WHERE po = ANY($1) ORDER BY po, created_at DESC`, [allPos])).rows
        .forEach(n => { lastNoteByPo[n.po] = n; });
      (await pool.query(`SELECT po, count(*)::int n FROM planner.supplier_notes WHERE po = ANY($1) GROUP BY po`, [allPos])).rows
        .forEach(r => { noteCountByPo[r.po] = r.n; });
    }

    let issues = 0, accepted = 0, ok = 0;
    const groups = comps.map(comp => {
      const soKeys = comp.filter(n => n[0] === 'S').map(n => n.slice(2));
      const poIds = comp.filter(n => n[0] === 'P').map(n => n.slice(2));
      const groupSos = soKeys.map(k => soByRef[k]).filter(Boolean);
      const soAgg = {}, poAgg = {};
      groupSos.forEach(s => { const m = soLineMap[s.cin7_id] || {}; Object.keys(m).forEach(sku => { soAgg[sku] = (soAgg[sku] || 0) + m[sku]; }); });
      poIds.forEach(po => { const m = poLineByPo[po] || {}; Object.keys(m).forEach(sku => { poAgg[sku] = (poAgg[sku] || 0) + m[sku]; }); });
      const diffs = []; const skuSet = {}; Object.keys(soAgg).forEach(k => skuSet[k] = 1); Object.keys(poAgg).forEach(k => skuSet[k] = 1);
      const noPo = !poIds.length;   // no-PO group: list ALL the SO's SKUs (even qty 0) so a zero-qty order's contents still show
      Object.keys(skuSet).forEach(sku => { const sq = soAgg[sku] || 0, pq = poAgg[sku] || 0; if (sq !== pq || noPo) diffs.push({ sku, soQty: sq, poQty: pq }); });
      let issue = null; if (noPo) issue = 'no_po'; else if (diffs.length) issue = 'qty_mismatch';
      const allAccepted = groupSos.length > 0 && groupSos.every(s => s.accepted);
      if (allAccepted) accepted++; else if (issue) issues++; else ok++;
      let _ln = null, _lnPo = null, _tlc = 0;
      poIds.forEach(po => { _tlc += (noteCountByPo[po] || 0); const c = lastNoteByPo[po]; if (c && (!_ln || c.created_at > _ln.created_at)) { _ln = c; _lnPo = po; } });
      const po_refs = poIds.map(po => ({ po, supplier: (poMeta[po] && poMeta[po].supplier) || '', app: !soKeys.some(k => cin7EdgeSet.has(po + '|' + k)) }));
      const newest = groupSos.map(s => s.created_date).sort().slice(-1)[0] || '';
      return {
        group_id: (soKeys.slice().sort()[0] || ('P:' + (poIds.slice().sort()[0] || ''))),
        grouped: groupSos.length > 1, newest,
        sos: groupSos.map(s => ({ cin7_id: s.cin7_id, reference: s.reference, branch_name: s.branch_name, company: s.company, created_date: s.created_date, note: s.note, accepted: s.accepted })),
        po_refs, issue, diffs: diffs.slice(0, 80), accepted: allAccepted,
        tl_po: _lnPo || (po_refs[0] && po_refs[0].po) || null,
        tl_last: _ln ? { body: _ln.body, author: _ln.author_email, kind: _ln.author_kind, at: _ln.at } : null, tl_count: _tlc
      };
    }).filter(g => g.sos.length);
    const rank = g => (g.issue && !g.accepted) ? 0 : (g.accepted ? 2 : 1);
    groups.sort((a, b) => (rank(a) - rank(b)) || String(b.newest).localeCompare(String(a.newest)));

    // Reverse view — open DTC POs that resolved to NO open sales order (no parsed Cin7 edge + no app link=true edge).
    const mappedPoSet = new Set(Object.keys(poToSo));
    const unmapped = (await pool.query(`SELECT p.po, coalesce(p.supplier_name,'') supplier, coalesce(p.branch,'') branch, coalesce(p.country_code,'') country_code, coalesce(p.status,'') status,
        coalesce(p.sales_order_ref,'') sales_order_ref, coalesce(r.accepted,false) accepted, coalesce(r.note,'') note, coalesce(r.accepted_by,'') accepted_by
      FROM planner.purchase_orders p LEFT JOIN planner.dtc_po_review r ON r.po=p.po
      WHERE p.branch = ANY($1)
        AND coalesce(p.status,'') NOT ILIKE '%complete%' AND coalesce(p.status,'') NOT ILIKE '%cancel%' AND coalesce(p.status,'') NOT ILIKE '%void%'
      ORDER BY coalesce(r.accepted,false), p.po`, [DTC_BRANCH_NAMES])).rows
      .filter(u => !mappedPoSet.has(u.po));
    const unmappedOpen = unmapped.filter(u => !u.accepted).length;
    if (countOnly) return { groups: [], counts: { issues, accepted, ok, unmapped_pos: unmappedOpen } };
    const unmappedSet = new Set(unmapped.map(u => u.po));
    const all_pos = candPos.map(p => ({ po: p.po, supplier: p.supplier, unmapped: unmappedSet.has(p.po) }));   // every open DTC PO — lets "Map PO" attach an already-mapped PO to another SO (multi-SO grouping)
    return { groups, unmapped_pos: unmapped, counts: { issues, accepted, ok, unmapped_pos: unmappedOpen }, all_pos };
  }
}
// In-app PO<->SO mapping (mig 254). link=true adds an edge, link=false suppresses a wrong Cin7 edge. Both persist in
// HORIZON only (never written to Cin7) and survive n8n resyncs. Reconciliation reads them in /api/supply/dtc/mismatch.
app.post('/api/supply/dtc/map', async (req, res) => {
  const b = req.body || {}; const po = String(b.po || '').trim(); const ref = _dtcNorm(b.sales_order_ref);
  const link = (b.link === false) ? false : true;
  if (!po || !ref) return res.status(400).json({ error: 'po and sales_order_ref required' });
  try {
    await pool.query(`INSERT INTO planner.dtc_po_so_map (po, sales_order_ref, link, created_by, created_at)
        VALUES ($1,$2,$3,$4,now())
        ON CONFLICT (po, sales_order_ref) DO UPDATE SET link=excluded.link, created_by=excluded.created_by, created_at=now()`,
      [po, ref, link, authUser(req)]);
    res.json({ ok: true });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// Remove an in-app mapping row (reverts that PO<->SO edge to the Cin7 default — undoes an add OR a suppress).
app.post('/api/supply/dtc/unmap', async (req, res) => {
  const b = req.body || {}; const po = String(b.po || '').trim(); const ref = _dtcNorm(b.sales_order_ref);
  if (!po || !ref) return res.status(400).json({ error: 'po and sales_order_ref required' });
  try { await pool.query(`DELETE FROM planner.dtc_po_so_map WHERE po=$1 AND sales_order_ref=$2`, [po, ref]); res.json({ ok: true }); }
  catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// v27.797 (Ben): DTC ↔ Fulfil alignment (READ ONLY — Fulfil is the source of truth; Horizon flags divergence, never writes).
// For each Horizon PO↔SO mapping (dtc_po_so_map), show the Fulfil PO's ACTUAL linked sale so misalignment is visible.
app.get('/api/supply/dtc/fulfil-alignment', async (req, res) => {
  try {
    const maps = (await pool.query(`SELECT po, sales_order_ref FROM planner.dtc_po_so_map WHERE link=true ORDER BY po`)).rows;
    const cfg = fulfilConfigFor(await activeFulfilEnv());
    if (!cfg.configured) return res.json({ ok: true, env: cfg.env, rows: maps.map(m => ({ po: m.po, horizon_so: m.sales_order_ref, fulfil_po_id: null, fulfil_so: null, fulfil_client: null, status: 'fulfil-not-configured' })) });
    // v27.799 (review item 7/perf #1): batch the Fulfil lookups — was 2-5 sequential calls PER mapping (timed out at scale).
    const allPos = [...new Set(maps.map(m => m.po))];
    const poById = {};   // fulfil PO id → {po, reference}
    const byNum = await fulfilSearchAll(FULFIL_MAP.poModel, [['number', 'in', allPos]], ['id', 'number', 'reference']);
    (byNum || []).forEach(p => { poById[p.id] = { po: p.number, reference: p.reference }; });
    const foundPos = new Set((byNum || []).map(p => p.number));
    const missNum = allPos.filter(p => !foundPos.has(p));
    if (missNum.length) { const byRef = await fulfilSearchAll(FULFIL_MAP.poModel, [['reference', 'in', missNum]], ['id', 'number', 'reference']); (byRef || []).forEach(p => { poById[p.id] = { po: p.reference, reference: p.reference }; foundPos.add(p.reference); }); }
    // po id → sale, resolved in two batched steps: (a) direct SO-number reference, (b) the purchase-request chain.
    const poSale = {};   // fulfil PO id → {ref, client}
    const poIds = Object.keys(poById).map(Number);
    const directNums = [...new Set(Object.values(poById).map(p => p.reference).filter(r => r && /^SO/i.test(r)))];
    const reqs = poIds.length ? await fulfilSearchAll('purchase.request', [['purchase_line.purchase', 'in', poIds]], ['id', 'purchase_line.purchase']) : [];
    const reqToPo = {}; const reqIds = [];
    (reqs || []).forEach(r => { const pid = r['purchase_line.purchase']; if (pid) { reqToPo[r.id] = pid; reqIds.push(r.id); } });
    if (reqIds.length) {
      const slines = await fulfilSearchAll('sale.line', [['purchase_request', 'in', reqIds]], ['purchase_request', 'sale.number', 'sale.party.name']);
      (slines || []).forEach(sl => { const pid = reqToPo[sl.purchase_request]; if (pid && sl['sale.number'] && !poSale[pid]) poSale[pid] = { ref: sl['sale.number'], client: sl['sale.party.name'] || null }; });
    }
    // fill any PO whose reference IS the SO number but had no request chain, via one sale.sale batch on the direct numbers
    const needDirect = poIds.filter(pid => !poSale[pid] && poById[pid].reference && /^SO/i.test(poById[pid].reference));
    if (needDirect.length) {
      const sales = await fulfilSearchAll('sale.sale', [['number', 'in', [...new Set(needDirect.map(pid => poById[pid].reference))]]], ['number', 'party.name']);
      const saleByNum = {}; (sales || []).forEach(s => { saleByNum[s.number] = { ref: s.number, client: s['party.name'] || null }; });
      needDirect.forEach(pid => { const sm = saleByNum[poById[pid].reference]; if (sm) poSale[pid] = sm; });
    }
    const poIdByName = {}; Object.entries(poById).forEach(([id, p]) => { poIdByName[p.po] = Number(id); });
    const rows = maps.map(m => {
      const fpId = poIdByName[m.po];
      if (fpId == null) return { po: m.po, horizon_so: m.sales_order_ref, fulfil_po_id: null, fulfil_so: null, fulfil_client: null, status: 'po-not-in-fulfil' };
      const sale = poSale[fpId] || null;
      return { po: m.po, horizon_so: m.sales_order_ref, fulfil_po_id: fpId, fulfil_so: sale ? sale.ref : null, fulfil_client: sale ? sale.client : null, status: sale ? 'linked-in-fulfil' : 'no-fulfil-sale-link' };
    });
    res.json({ ok: true, env: cfg.env, rows });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
