    if (!row) return res.status(404).json({ error: 'not found' });
    const isCsv = /\.csv$/i.test(row.filename || '') || /csv/i.test(row.content_type || '');
    // order lines → cost-centre freight/fulfilment (map against the imported Cin7 cache)
