  const cc = m[1].toUpperCase();
  if (cc === 'US') return { market: 'us', pool: 'fba' };
  if (cc === 'UK' || cc === 'GB') return { market: 'uk', pool: 'fba' };
  if (cc === 'AU') return { market: 'au', pool: 'fba' };
  if (_FBA_EU_COUNTRIES.has(cc)) return { market: 'eu', pool: 'fba' };
