// v28.168 (Ben): daily in-flight FBA refresh. POST /api/cron/fba-inflight-refresh (x-webhook-secret = N8N_WEBHOOK_SECRET,
// timing-safe). { dry_run: true } = fetch + preview, no write, no etl_runs row. Each real run records planner.etl_runs job
// 'fba_inflight_refresh' (success: rows_affected = lines written; failure / not configured: status 'error') so the health
// log ETL checks see it. PROD SCHEDULE: n8n daily 06:00 Europe/London. The long-lived local server also runs it daily
// (unref'd timer, first run 10 min after boot; HZ_FBA_INFLIGHT_CRON=0 turns that off).
async function runFbaInflightCron({ dry = false } = {}) {
  let r; try { r = await refreshFbaInflight({ dry }); } catch (e) { r = { ok: false, error: e.message }; }
  if (!dry) {
    const msg = r.ok ? (r.lines + ' line(s), ' + r.units + 'u from ' + r.transfers + ' Fulfil shipment(s), ' + r.pruned + ' pruned (' + r.source + ')') : String(r.error || 'failed').slice(0, 500);
    try { await pool.query(`INSERT INTO planner.etl_runs (job, status, rows_affected, message) VALUES ('fba_inflight_refresh',$1,$2,$3)`, [r.ok ? 'success' : 'error', r.ok ? r.lines : 0, msg]); }
    catch (e) { console.warn('[fba-inflight] etl_runs insert failed: ' + (e && e.message)); r.etl_logged = false; }
  }
  return r;
}
app.post('/api/cron/fba-inflight-refresh', async (req, res) => {
  const secret = process.env.N8N_WEBHOOK_SECRET; if (!secret || !safeEq(req.get('x-webhook-secret'), secret)) return res.status(401).json({ error: 'unauthorized' });
  try { const b = req.body || {}; const r = await runFbaInflightCron({ dry: b.dry_run === true || b.dry_run === 'true' }); res.status(r.ok || r.inert ? 200 : 500).json(r); }   // 500 on a real failure so the n8n error workflow fires
  catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
if (!process.env.VERCEL && process.env.HZ_FBA_INFLIGHT_CRON !== '0') {
  const _fi = () => runFbaInflightCron({}).then(r => console.log('[fba-inflight] ' + (r.ok ? ('refreshed ' + r.lines + ' line(s)') : ('not refreshed: ' + r.error))), e => console.warn('[fba-inflight] failed: ' + (e && e.message)));
  setTimeout(_fi, 600000).unref?.(); setInterval(_fi, 86400000).unref?.();
}
// ── Zalando: baked per-SKU forecast + uploaded stock-on-hand (planner.zalando_stock). Feeds the BUY & MOVE ▸ Zalando tab.
app.get('/api/supply/zalando/data', async (req, res) => {   // /data suffix: single-segment /api/supply/zalando is caught by the :section catch-all
  try {
    const stock = {}; (await pool.query(`SELECT sku, qty FROM planner.zalando_stock`)).rows.forEach(r => { stock[r.sku] = Number(r.qty) || 0; });
    const up = (await pool.query(`SELECT to_char(max(updated_at),'YYYY-MM-DD') d, max(updated_at) ts, count(*)::int n, max(uploaded_by) by FROM planner.zalando_stock`)).rows[0] || {};
    const forecast = await buildZalFc();   // Zalando forecast from the DB (forecast_outputs channel ZAL), not the baked file
    const months = [...new Set(Object.values(forecast).flatMap(m => Object.keys(m)))].sort();
    const skus = Object.keys(forecast); const eans = {};   // SKU → EAN (strip the leading apostrophe Sheets adds) for the ZALANDO_UP (EAN,Quantity) download
    if (skus.length) (await pool.query(`SELECT sku, replace(coalesce(product_ean,''), chr(39), '') ean FROM planner.products WHERE sku = ANY($1)`, [skus])).rows.forEach(r => { if (r.ean) eans[r.sku] = r.ean; });
    res.set('Cache-Control', 'no-store').json({ ok: true, forecast, months, stock, eans, stock_updated: up.d || null, stock_updated_ts: up.ts || null, stock_skus: up.n || 0, stock_updated_by: up.by || null });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// Upload the combined Zalando stock file (csv/xls/xlsx). Flexible: finds the header row with a "Sku" + "…sellable_stock" column.
app.post('/api/supply/zalando/stock-upload', async (req, res) => {
  try {
    const b = req.body || {}; const fn = String(b.filename || '');
    if (!b.content_base64 && !b.storage_path) return res.status(400).json({ error: 'no file supplied' });
    let buf; try { buf = await resolveUploadBytes(b, { base64Field: 'content_base64', maxInline: 20 * 1024 * 1024 }); } catch (e) { return res.status(e.status || 400).json({ error: e.message }); }
    let grid = [];
    if (/\.csv$/i.test(fn)) { const parse = l => { const o = []; let c = '', q = false; for (let i = 0; i < l.length; i++) { const ch = l[i]; if (ch === '"') { if (q && l[i + 1] === '"') { c += '"'; i++; } else q = !q; } else if (ch === ',' && !q) { o.push(c); c = ''; } else c += ch; } o.push(c); return o; }; grid = String(buf.toString('utf8')).split(/\r?\n/).filter(l => l.length).map(parse); }
    else { const ExcelJS = (await import('exceljs')).default; const wb = new ExcelJS.Workbook(); await wb.xlsx.load(buf); const ws = wb.worksheets[0]; if (ws) ws.eachRow({ includeEmpty: false }, r => { const a = []; r.eachCell({ includeEmpty: true }, (c, col) => { a[col - 1] = _tplCellVal(c); }); grid.push(a); }); }
    if (!grid.length) return res.json({ ok: false, error: 'empty file' });
    let hr = -1, si = -1, qi = -1;
    for (let i = 0; i < Math.min(12, grid.length); i++) { const hs = (grid[i] || []).map(x => String(x == null ? '' : x).trim().toLowerCase()); const s = hs.indexOf('sku'); const q = hs.findIndex(h => /sellable[_ ]?stock/.test(h)); if (s >= 0 && q >= 0) { hr = i; si = s; qi = q; break; } }
    if (hr < 0) return res.json({ ok: false, error: 'Could not find the "Sku" and "…sellable_stock" columns in the file.' });
    const rows = []; for (let r = hr + 1; r < grid.length; r++) { const sku = String((grid[r] || [])[si] == null ? '' : grid[r][si]).trim(); if (!sku) continue; const q = _tplNum((grid[r] || [])[qi]); rows.push([sku, q == null ? 0 : q]); }
    if (!rows.length) return res.json({ ok: false, error: 'no stock rows found under the headers' });
    const by = authUser(req);
    // v28.151 (review E7): DELETE + ONE multi-row insert in a single transaction (was DELETE then a per-row INSERT with no
    // txn: a mid-upload failure left the snapshot empty or partial, and N round trips held the pool). Duplicate SKUs in the
    // file collapse to the last row (as the old per-row upsert did).
    const _zm = new Map(); for (const [sku, q] of rows) _zm.set(sku, q);
    const zc = await pool.connect();
    try {
      await zc.query('BEGIN');
      await zc.query(`DELETE FROM planner.zalando_stock`);   // dedicated snapshot table — each upload replaces with the latest
      await zc.query(`INSERT INTO planner.zalando_stock (sku, qty, updated_at, uploaded_by) SELECT u.sku, u.qty, now(), $3 FROM unnest($1::text[], $2::numeric[]) AS u(sku, qty)
        ON CONFLICT (sku) DO UPDATE SET qty=excluded.qty, updated_at=now(), uploaded_by=excluded.uploaded_by`, [[..._zm.keys()], [..._zm.values()], by]);
      await zc.query('COMMIT');
    } catch (e) { await _rollback(zc); throw e; } finally { zc.release(); }
    res.json({ ok: true, count: rows.length });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// Serve the in-flight (not-yet-inbound) FBA transfers for the FBA tab + last-run stamp. Only rows whose
// reference isn't already in inbound_shipments (defensive — the refresh also prunes them).
app.get('/api/supply/fba-transfers/list', async (req, res) => {
  try {
    const rows = (await pool.query(`SELECT cin7_id, sku, qty, reference, market, pool, warehouse, stage, coalesce(source,'cin7') source,
        to_char(eta,'YYYY-MM-DD') eta, to_char(created_date,'YYYY-MM-DD') created, to_char(dispatched_date,'YYYY-MM-DD') dispatched
      FROM planner.fba_pending_transfers t
      WHERE received_date IS NULL AND coalesce(source,'cin7')='fulfil' AND (reference IS NULL OR NOT EXISTS (SELECT 1 FROM planner.inbound_shipments i WHERE i.reference=t.reference))
      ORDER BY created_date DESC, reference, sku`)).rows;
    const lr = (await pool.query(`SELECT value, to_char(updated_at,'YYYY-MM-DD HH24:MI') at FROM planner.app_settings WHERE key='fba_transfers_last_run'`)).rows[0];
    // v28.168 (Ben): shipments from excluded source warehouses are never FBA cover; drop any such row still in the table and
    // return the excluded list (+ the code list) for the drawer's "Excluded" section.
    let excluded = []; try { const x = (await pool.query(`SELECT value FROM planner.app_settings WHERE key='fba_inflight_excluded'`)).rows[0]; if (x && x.value) { const a = JSON.parse(x.value); if (Array.isArray(a)) excluded = a; } } catch (_) {}
    const exRefs = new Set(); excluded.forEach(e => { if (e.reference) exRefs.add(String(e.reference)); if (e.number) exRefs.add(String(e.number)); });
    const kept = exRefs.size ? rows.filter(r => !(r.reference && exRefs.has(String(r.reference)))) : rows;
    res.json({ ok: true, rows: kept, last_run: lr ? (lr.value || lr.at) : null, source: 'fulfil', excluded, excluded_codes: await fbaInflightExcludedCodes() });
  } catch (e) { res.json({ ok: false, error: e.message, rows: [] }); }
});
