// Lifecycle for SUPPLY ▸ Actions (dismiss / snooze / done) by stable key. Absent row = open; restore deletes.
app.post('/api/supply/actions/state', async (req, res) => {
  const b = req.body || {}, key = (b.key || '').trim();
  if (!key) return res.status(400).json({ error: 'key required' });
  res.on('finish', () => { swrStale('sup:realloc'); swrStale('sup:dtc-count'); });   // v28.081: badge memos re-count after a dismiss / snooze / restore
  try {
    if (b.status === 'open' || b.restore) { await pool.query(`DELETE FROM planner.supply_action_state WHERE action_key=$1`, [key]); return res.json({ ok: true }); }
    const indef = !!b.indefinite;   // snooze indefinitely = snoozed with no expiry (snooze_until NULL)
    const days = String(parseInt(b.snooze_days, 10) || 7);
    const who = authUser(req);
    await pool.query(`INSERT INTO planner.supply_action_state (action_key, status, snooze_until, note, snoozed_by, snoozed_at)
      VALUES ($1,$2, CASE WHEN $2!='snoozed' THEN NULL WHEN $6 THEN NULL ELSE current_date + ($3||' days')::interval END, $4, $5, now())
      ON CONFLICT (action_key) DO UPDATE SET status=excluded.status, snooze_until=excluded.snooze_until, note=excluded.note, snoozed_by=excluded.snoozed_by, snoozed_at=excluded.snoozed_at, updated_at=now()`,
      [key, b.status || 'dismissed', days, b.note || null, who || null, indef]);
    res.json({ ok: true });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// Drop the cached Actions build so the next fetch reflects a just-made data edit (the client calls this from
// invalidateDerived after any PO/shipment/payment change). Idle visits still ride the 10-min cache; editors get
// freshness. Kicks a background rebuild so the cache re-warms without blocking the caller.
// Drop ALL user-independent SUPPLY read caches (Actions + po-rows + lookups + order-plan-exceptions) so the next
// fetch reflects a just-made edit; each rebuilds in the background. The client fires this from invalidateDerived.
// v28.167 (Ben): marks stale only (no rebuild here; see _lcGet). If every write this browser made since its last call already
// invalidated its own scope server-side (e.g. a PO date edit: patch() -> 'po-fields') and none is still running, the call is a
// no-op, so the edit stays scoped. Anything else (an uncovered write, a write still in flight, no write at all = a manual
// refresh, no session cookie, another instance) invalidates every cache as before, lazily.
app.post(['/api/supply/cache/invalidate', '/api/supply/actions/invalidate'], (req, res) => {
  const s = _reqStore.getStore(); const me = s && s.sid ? _rwSess.get(s.sid) : null;
  if (me && !me.uncovered && !me.inflight && me.covered > 0 && Date.now() - (me.wroteAt || 0) < 120000) { me.covered = 0; return res.json({ ok: true, scoped: true }); }
  invalidateSupplyCaches(); if (me) { me.uncovered = false; me.covered = 0; }
  res.json({ ok: true });
});
// Ungated demand data-cache rebuild for the in-app "↻ Refresh" button (busts _dataCache + rebuilds _SKU_RAW/
// FC_OUTPUTS from Supabase). Harmless (rebuild only, no write) so it needs no webhook secret — unlike the
// n8n /api/data-cache/invalidate. Lets a user pick up a product/scope change without waiting on the TTL. (v27.327)
app.post('/api/demand/cache/invalidate', async (_req, res) => {
  try { _dataCache = null; const vals = await refreshDataCache(); res.json({ ok: true, rebuilt: Array.isArray(vals) ? vals.length : 0, at: new Date().toISOString() }); }
  catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// n8n post-ETL trigger: after a sales/inventory upload, rebuild the demand-data cache from Supabase ONCE and push it to
// KV so every serverless instance converges — instead of each Vercel cold start re-pulling ~12MB from Supabase. Awaits
// the rebuild so n8n gets a success confirmation (and KV is written) before responding. Webhook-secret gated (if set).
app.post('/api/data-cache/invalidate', async (req, res) => {
  const secret = process.env.N8N_WEBHOOK_SECRET;
  if (!secret || !safeEq(req.get('x-webhook-secret'), secret)) return res.status(401).json({ error: 'unauthorized' });   // v28.116 (review S5): fail CLOSED when the secret is unset
  try { _dataCache = null; const vals = await refreshDataCache(); invalidateBiCache();
    res.json({ ok: true, rebuilt: Array.isArray(vals) ? vals.length : 0, kv: KV_ON, at: new Date().toISOString() }); }
  catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
