// Shipment edit (upsert) — carrier/ref/master/status/notes + the date OVERRIDES that win over the
// POs aboard. Row may not exist yet (a shipment_ref freshly typed onto a PO), so insert-on-conflict.
const SHIP_FIELDS = {
  master_po: 'text', carrier: 'text', carrier_ref: 'text', status: 'text', notes: 'text', mode: 'text',
  starred: 'boolean',   // ⭐ Focus / favourite toggle (migration 082)
  cost_manual: 'numeric', tracked_delivery_date: 'date', tracked_source: 'text',
  departure_date: 'date', landing_date: 'date', delivery_date: 'date', arrival_date: 'date',
  branch: 'text', country_code: 'text',   // shipment-level destination override (inherits from master PO)
  export_port: 'text',   // override; blank = inherit the master PO supplier's export_port
  delivery_notes: 'text',   // shipment-level branch delivery notes override (inherits from the master PO)
};
// Shipment record-of-change: which fields are worth logging on the shipment timeline (mirrors PO_TRACK).
const SHIP_TRACK = { master_po: 'Master PO', carrier: 'Carrier', carrier_ref: 'Carrier ref', status: 'Status', mode: 'Mode',
  cost_manual: 'Freight cost', departure_date: 'Ship / departure date', landing_date: 'Landing date',
  delivery_date: 'Delivery date', arrival_date: 'Arrival date', tracked_delivery_date: 'Tracked delivery date',
  branch: 'Destination branch', export_port: 'Export port' };
async function logShipChange(ref, event, detail, by) {
  try { await pool.query(`INSERT INTO planner.shipment_change_log (shipment_ref, event, detail, changed_by) VALUES ($1,$2,$3,$4)`, [ref, event, detail || null, by || null]); }
  catch (e) { /* table absent pre-migration 165 — non-fatal */ }
}
async function logShipFieldChanges(ref, oldRow, body, by) {
  const numish = (s) => s !== '' && s != null && !isNaN(Number(s));
  for (const k of Object.keys(SHIP_TRACK)) {
    if (body[k] === undefined) continue;
    let nv = (body[k] === '' || body[k] == null) ? '' : String(body[k]).trim();
    let ov = (oldRow[k] == null) ? '' : String(oldRow[k]).trim();
    const isDate = /_date$/.test(k);
    if (isDate) { ov = ov.slice(0, 10); nv = nv.slice(0, 10); }
    if (numish(ov) && numish(nv)) { if (Number(ov) === Number(nv)) continue; } else if (ov === nv) continue;
    let fov = ov, fnv = nv;
    if (isDate) { fov = ov ? ddMonYy(ov) : ''; fnv = nv ? ddMonYy(nv) : ''; const dl = dateDeltaLabel(ov, nv); if (dl) fnv = fnv + ' ' + dl; }
    else if (k === 'cost_manual') { const m = (v) => Number(v).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); if (numish(ov)) fov = m(ov); if (numish(nv)) fnv = m(nv); }
    const f = (v) => v === '' ? '(blank)' : v;
    await logShipChange(ref, SHIP_TRACK[k], f(fov) + ' → ' + f(fnv), by);
  }
}
app.post('/api/supply/shipment/:ref', async (req, res) => {
  const ref = req.params.ref;
  const cols = ['shipment_ref'], vals = [ref], ph = ['$1::text']; let i = 2;
  for (const k of Object.keys(req.body || {})) {
    if (!SHIP_FIELDS[k]) continue;
    cols.push(k); vals.push(req.body[k] === '' ? null : req.body[k]); ph.push(`$${i++}::${SHIP_FIELDS[k]}`);
  }
  const upd = cols.slice(1).map(c => `${c}=excluded.${c}`).join(',') || 'updated_at=now()';
  // Snapshot (pre-change) the shipment's dates + each aboard PO's effective completion (checkin), so we can log the
  // cascade on every PO whose inherited date shifts (record of change extends to shipment-driven date recalcs).
  let _oldShip = null, _preCheckin = {}, _oldShipFull = null;
  try {
    _oldShip = (await pool.query(`SELECT departure_date::text dep, landing_date::text land, delivery_date::text del, arrival_date::text arr, tracked_delivery_date::text trk FROM planner.shipments WHERE shipment_ref=$1`, [ref])).rows[0] || null;
    _oldShipFull = (await pool.query(`SELECT master_po, carrier, carrier_ref, status, mode, cost_manual::text, departure_date::text, landing_date::text, delivery_date::text, arrival_date::text, tracked_delivery_date::text, branch, export_port FROM planner.shipments WHERE shipment_ref=$1`, [ref])).rows[0] || null;
    const _pa = (await pool.query(`SELECT po FROM planner.purchase_orders WHERE shipment_ref=$1 UNION SELECT master_po FROM planner.shipments WHERE shipment_ref=$1 AND coalesce(master_po,'')<>''`, [ref])).rows.map(x => x.po);
    if (_pa.length) (await queryCapped(PO_ROWS_SQL + ' WHERE calc4.po = ANY($1)', [_pa])).rows.forEach(r => { _preCheckin[r.po] = r.checkin ? String(r.checkin).slice(0, 10) : ''; });
  } catch (e) { /* snapshot best-effort */ }
  try {
    const up = await pool.query(`INSERT INTO planner.shipments (${cols.join(',')}) VALUES (${ph.join(',')})
      ON CONFLICT (shipment_ref) DO UPDATE SET ${upd}, updated_at=now() RETURNING (xmax = 0) AS inserted`, vals);
    if (up.rows[0] && up.rows[0].inserted) await noteShipmentCreated(pool, ref, authUser(req));
    // status → Shipping advances the POs on board (same as the "→ set shipping" action / supplier portal)
    if ((req.body || {}).status === 'Shipping') await propagateShippingToPOs(ref);
    // Step 3: a shipment date change cascades to every PO aboard (they inherit the master's effective dates).
    // Return all affected rows recomputed in ONE response so the client repaints them without N separate fetches.
    let rows = [];
    try {
      const aboard = (await pool.query(
        `SELECT po FROM planner.purchase_orders WHERE shipment_ref=$1
         UNION SELECT master_po FROM planner.shipments WHERE shipment_ref=$1 AND coalesce(master_po,'')<>''`, [ref])).rows.map(x => x.po);
      if (aboard.length) rows = (await queryCapped(PO_ROWS_SQL + ' WHERE calc4.po = ANY($1)', [aboard])).rows;
    } catch (e) { /* non-fatal — client falls back to per-PO refresh */ }
    // Record of change: for every aboard PO whose effective completion shifted from the shipment date edit, log it.
    try {
      const DL = { dep: 'ship date', del: 'delivery date', land: 'landing date', arr: 'arrival date', trk: 'tracked delivery date' };
      const FK = { dep: 'departure_date', del: 'delivery_date', land: 'landing_date', arr: 'arrival_date', trk: 'tracked_delivery_date' };
      const changed = _oldShip ? Object.keys(DL).filter(k => (req.body || {})[FK[k]] !== undefined && String(_oldShip[k] || '').slice(0, 10) !== String((req.body[FK[k]] || '')).slice(0, 10)) : [];
      if (changed.length && rows.length) {
        const shipMaster = (await pool.query(`SELECT coalesce(nullif(master_po,''),shipment_ref) m FROM planner.shipments WHERE shipment_ref=$1`, [ref])).rows[0]?.m || ref;
        const dateBits = changed.map(k => DL[k] + ' → ' + (req.body[FK[k]] ? ddMonYy(String(req.body[FK[k]]).slice(0, 10)) : '(cleared)')).join(', ');
        const by = authUser(req);
        for (const r of rows) {
          const oldC = _preCheckin[r.po] || '', newC = r.checkin ? String(r.checkin).slice(0, 10) : '';
          if (oldC !== newC) {
            const delta = dateDeltaLabel(oldC, newC);
            logPoChange(r.po, 'Shipment date', 'Shipment ' + shipMaster + ' ' + dateBits + '. Completion recalculated to ' + (newC ? ddMonYy(newC) : '(none)') + (delta ? ' ' + delta : ''), by);
          }
        }
      }
    } catch (e) { /* cascade log best-effort */ }
    // Record of change on the SHIPMENT's own timeline (field edits: carrier / status / mode / freight / dates).
    try { if (_oldShipFull) await logShipFieldChanges(ref, _oldShipFull, req.body, authUser(req)); } catch (e) { /* best-effort */ }
    res.json({ ok: true, rows });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// Create a new shipment (header only; POs are assigned separately). master_po defaults to the ref.
app.post('/api/supply/shipment-create', async (req, res) => {
  const ref = (req.body && req.body.shipment_ref || '').trim();
  if (!ref) return res.status(400).json({ error: 'shipment_ref required' });
  try {
    const ins = await pool.query(`INSERT INTO planner.shipments (shipment_ref, master_po, carrier, carrier_ref)
      VALUES ($1,$2,$3,$4) ON CONFLICT (shipment_ref) DO NOTHING RETURNING shipment_ref`,
      [ref, (req.body.master_po || ref), req.body.carrier || null, req.body.carrier_ref || null]);
    if (ins.rowCount) await noteShipmentCreated(pool, ref, authUser(req));
    res.json({ ok: true, shipment_ref: ref });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// Delete a now-empty SELF-shipment (its master IS itself) left orphaned when its only PO was reassigned away.
// Guarded: only when no POs reference it AND it has no supplier charges (protects money/claim data). Notes are removed with it.
async function pruneEmptySelfShipment(db, ref) {
  if (!ref) return false;
  const ok = (await db.query(`SELECT 1 FROM planner.shipments s
    WHERE s.shipment_ref=$1 AND coalesce(nullif(s.master_po,''), s.shipment_ref)=s.shipment_ref
      AND NOT EXISTS (SELECT 1 FROM planner.purchase_orders p WHERE p.shipment_ref=$1)
      AND NOT EXISTS (SELECT 1 FROM planner.supplier_charges c WHERE c.source_type='shipment' AND c.source_ref=$1)`, [ref])).rows[0];
  if (!ok) return false;
  await db.query(`DELETE FROM planner.shipment_notes WHERE shipment_ref=$1`, [ref]);
  await db.query(`DELETE FROM planner.shipments WHERE shipment_ref=$1`, [ref]);
  return true;
}
// Assign / unassign a PO to a shipment, and optionally mark it the master (consolidation) PO.
// body: { po, assign:true|false, master:true }. Unassign clears purchase_orders.shipment_ref.
app.post('/api/supply/shipment/:ref/assign', async (req, res) => {
  const ref = req.params.ref, b = req.body || {};
  if (!b.po) return res.status(400).json({ error: 'po required' });
  try {
    const prior = ((await pool.query(`SELECT shipment_ref FROM planner.purchase_orders WHERE po=$1`, [b.po])).rows[0] || {}).shipment_ref;
    if (b.assign === false) {
      await pool.query(`UPDATE planner.purchase_orders SET shipment_ref=NULL WHERE po=$1`, [b.po]);
      await pool.query(`UPDATE planner.shipments SET master_po=NULL, updated_at=now()
        WHERE shipment_ref=$1 AND master_po=$2`, [ref, b.po]);
    } else {
      const ins = await pool.query(`INSERT INTO planner.shipments (shipment_ref, master_po) VALUES ($1,$1)
        ON CONFLICT (shipment_ref) DO NOTHING RETURNING shipment_ref`, [ref]);
      if (ins.rowCount) await noteShipmentCreated(pool, ref, authUser(req));
      await pool.query(`UPDATE planner.purchase_orders SET shipment_ref=$2 WHERE po=$1`, [b.po, ref]);
      if (b.master) await pool.query(`UPDATE planner.shipments SET master_po=$2, updated_at=now()
        WHERE shipment_ref=$1`, [ref, b.po]);
    }
    // the PO's PRIOR shipment may now be an empty self-shipment → clean it up
    if (prior) await pruneEmptySelfShipment(pool, prior);
    res.json({ ok: true });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// Delete a shipment. Unassigns every PO aboard (clears their shipment_ref), removes its timeline notes,
// then deletes the shipment row. POs themselves are left intact.
app.post('/api/supply/shipment/:ref/delete', async (req, res) => {
  const ref = req.params.ref;
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const unassigned = await client.query(`UPDATE planner.purchase_orders SET shipment_ref=NULL WHERE shipment_ref=$1`, [ref]);
    await client.query(`DELETE FROM planner.shipment_notes WHERE shipment_ref=$1`, [ref]);
    const r = await client.query(`DELETE FROM planner.shipments WHERE shipment_ref=$1`, [ref]);
    await client.query('COMMIT');
    res.json({ deleted: r.rowCount, unassigned_pos: unassigned.rowCount });
  } catch (e) { await _rollback(client); log500(e); res.status(500).json({ error: e.message }); }
  finally { client.release(); }
});
// SELF-SHIPMENT mode gate (PO ▸ SHIPMENTS). Picking a mode turns the PO into its own shipment (a planner.shipments
// row whose shipment_ref = the PO, master_po = the PO) so it flows through all the existing shipment machinery
// (portal, freight/duty calc, timeline). Clearing the mode tears the self-shipment down. branch=Manufacturing is
// always FOB. Only applies to the PO's OWN shipment — if it's assigned to a different master, mode is inherited.
app.post('/api/supply/po/:po/ship-mode', async (req, res) => {
  const po = req.params.po;
  let mode = String((req.body || {}).mode || '').trim().toLowerCase();
  if (mode && !['sea', 'air', 'fob'].includes(mode)) return res.status(400).json({ error: 'mode must be sea, air, fob or blank' });
  const client = await pool.connect();
  try {
    const p = (await client.query(`SELECT coalesce(branch,'') branch, coalesce(country_code,'') country_code, shipment_ref FROM planner.purchase_orders WHERE po=$1`, [po])).rows[0];
    if (!p) return res.status(404).json({ error: 'PO ' + po + ' not found' });
    if (p.shipment_ref && p.shipment_ref !== po) return res.status(409).json({ error: 'PO is assigned to shipment ' + p.shipment_ref + ' — its mode is inherited from that shipment, not set here.' });
    const manufacturing = /manufactur/i.test(p.branch);
    if (mode && manufacturing) mode = 'fob';   // Manufacturing branch is always FOB (factory pickup, no transit detail)
    await client.query('BEGIN');
    if (!mode) {
      const others = (await client.query(`SELECT count(*)::int n FROM planner.purchase_orders WHERE shipment_ref=$1 AND po<>$1`, [po])).rows[0].n;
      if (others > 0) { await _rollback(client); return res.status(409).json({ error: 'This shipment has ' + others + ' other PO(s) aboard — manage it as a master shipment instead of clearing the mode here.' }); }
      await client.query(`UPDATE planner.purchase_orders SET shipment_ref=NULL WHERE po=$1 AND shipment_ref=$1`, [po]);
      await client.query(`DELETE FROM planner.shipment_notes WHERE shipment_ref=$1`, [po]);
      await client.query(`DELETE FROM planner.shipments WHERE shipment_ref=$1`, [po]);
      await client.query('COMMIT');
      const row0 = (await queryCapped(PO_ROWS_SQL + ' WHERE calc4.po=$1', [po])).rows[0] || null;
      return res.json({ ok: true, mode: '', is_shipment: false, ship: null, row: row0 });
    }
    const ins = await client.query(`INSERT INTO planner.shipments (shipment_ref, master_po, mode, branch, country_code)
      VALUES ($1,$1,$2,NULLIF($3,''),NULLIF($4,''))
      ON CONFLICT (shipment_ref) DO UPDATE SET mode=$2,
        branch=coalesce(planner.shipments.branch, NULLIF($3,'')),
        country_code=coalesce(planner.shipments.country_code, NULLIF($4,'')),
        updated_at=now()
      RETURNING (xmax=0) created`, [po, mode, p.branch, p.country_code]);
    if (ins.rows[0] && ins.rows[0].created) await noteShipmentCreated(client, po, authUser(req));
    await client.query(`UPDATE planner.purchase_orders SET shipment_ref=$1 WHERE po=$1`, [po]);
    await client.query('COMMIT');
    const ship = await poShipObj(po);   // includes the FINAL calculated dates so the client can fill them silently
    const row1 = (await queryCapped(PO_ROWS_SQL + ' WHERE calc4.po=$1', [po])).rows[0] || null;   // recomputed grid row (ship/landing/delivery dates) so the main PO grid stays bound
    res.json({ ok: true, mode, is_shipment: true, manufacturing, ship, row: row1 });
  } catch (e) { try { await client.query('ROLLBACK'); } catch (_) {} res.status(500).json({ error: e.message }); }
  finally { client.release(); }
});

// ── SCENARIO PLANNER ───────────────────────────────────────────────────────
// Prime Day: inventory by SKU split into FBA / 3PL / AWD per the selected market(s).
// v_product_inventory warehouses are '{country}_{type}' (uk_3pl, us_fba, …), sourced from
// planner.products.inventory_*. AWD (inventory_us_awd) is a separate US pool, added on below.
// SALES PLANNING — per SKU for a country + channel (3pl|fba) + month: current on-hand, projected stock at
// the start of that month, weeks of cover at that date, and whether it's discontinued by then. Numbers come
// from the latest committed SKU-level forecast run. FBA cover pool = FBA + AWD (US); 3PL is returned as a
// separate transferable figure (shown as its own column, NOT in the FBA cover math). Projected = pool
// on-hand + inbound landing before the month − forecast sell-through before the month. Cover = projected
// ÷ (selected month's forecast ÷ 4.33).
app.post('/api/scenario/sales-planning', async (req, res) => {
  const b = req.body || {};
  const country = String(b.country || '').toUpperCase();
  const channel = String(b.channel || '3pl').toLowerCase() === 'fba' ? 'fba' : '3pl';
  const month = String(b.month || '').slice(0, 7);
  if (!/^[A-Z]{2}$/.test(country) || !/^\d{4}-\d{2}$/.test(month)) return res.status(400).json({ error: 'country + month (YYYY-MM) required' });
  const co = country.toLowerCase(), monthStart = month + '-01', isUS = country === 'US';
  const wh3 = co + '_3pl', whF = co + '_fba';
  const pools = channel === 'fba' ? [whF] : [wh3];            // projection pool: FBA (+AWD) for fba, 3PL for 3pl. 3PL is shown as a separate transferable column on the FBA report, not in the cover math.
  const fchs = channel === 'fba' ? ['FBA'] : ['DTC', 'B2B', 'TIK'];  // sales channels the warehouse fulfils (TIK folds into the 3PL pool like DTC)
  const discCol = country === 'AU' ? 'discontinue_date_au_final' : country === 'CA' ? 'discontinue_date_ca' : 'discontinue_date_final';
  try {
    const run = (await pool.query(`SELECT max(run_id) mx FROM planner.forecasts WHERE level='sku'`)).rows[0].mx;
    // SKUs available in this country + channel (3pl ↔ DTC/B2B, fba ↔ FBA)
    const availSkus = (await pool.query(`SELECT DISTINCT sku FROM planner.v_product_availability
        WHERE upper(country)=$1 AND channel = ANY($2) AND is_available`, [country, fchs])).rows.map(r => r.sku);
    if (!availSkus.length) return res.json({ rows: [], country, channel, month });
    // inventory for the pooled warehouses
    const inv = {}; (await pool.query(`SELECT sku, warehouse, available FROM planner.v_product_inventory WHERE warehouse = ANY($1)`, [[wh3, whF]])).rows
      .forEach(r => { (inv[r.sku] || (inv[r.sku] = {}))[r.warehouse] = Number(r.available) || 0; });
    // product meta: name, per-country discontinue, AWD (US)
    const meta = {}; (await pool.query(`SELECT sku, coalesce(product_name,'') name,
        nullif(${discCol},'') disc, coalesce(inventory_us_awd,0)::int awd FROM planner.products WHERE in_planning_scope`)).rows
      .forEach(r => { meta[r.sku] = r; });
    // inbound landing BEFORE the month (real inbound feed + open POs with the same calc ETA as the SUPPLY view)
    const inbBefore = {}; (await pool.query(`SELECT sku, sum(qty)::int q FROM (
        SELECT sku, (quantity-coalesce(received_quantity,0)) qty FROM planner.inbound_shipments
          WHERE coalesce(received_quantity,0) < quantity AND destination_warehouse = ANY($1)
            AND reference NOT IN (${EXCL_REF_LIST})
            AND estimated_delivery_date IS NOT NULL AND to_char(estimated_delivery_date,'YYYY-MM-DD') < $2
        UNION ALL
        SELECT l.sku, l.qty FROM planner.purchase_order_lines l
          JOIN planner.purchase_orders po ON po.po=l.po
          LEFT JOIN planner.branches b ON b.name=po.branch
          LEFT JOIN planner.suppliers s ON s.id=po.supplier_id
          WHERE coalesce(l.qty,0)>0 AND coalesce(po.status,'') NOT ILIKE '%complete%'
            AND (lower(coalesce(nullif(po.country_code,''), b.country_code)) || '_' || (CASE WHEN po.branch ILIKE '%fba%' THEN 'fba' ELSE '3pl' END)) = ANY($1)
            AND NOT EXISTS (SELECT 1 FROM planner.inbound_shipments i WHERE i.reference=po.po)
            AND to_char((coalesce(po.end_production_overide, CASE WHEN po.start_production IS NOT NULL AND s.production_days IS NOT NULL
                  THEN (po.start_production + (s.production_days||' days')::interval)::date END)
                + interval '7 days' + (b.sea_lead_time_days||' days')::interval)::date,'YYYY-MM-DD') < $2
      ) z GROUP BY sku`, [pools, monthStart])).rows.forEach(r => { inbBefore[r.sku] = Number(r.q) || 0; });
    // forecast: demand before the month + the selected month's demand (for the weekly cover rate)
    const fc = {}; (await pool.query(`SELECT sku,
        coalesce(sum(units) FILTER (WHERE to_char(month,'YYYY-MM') >= to_char(CURRENT_DATE,'YYYY-MM') AND to_char(month,'YYYY-MM') < $3),0)::int dem_before,
        coalesce(sum(units) FILTER (WHERE to_char(month,'YYYY-MM') = $3),0)::int dem_month
      FROM planner.forecasts WHERE level='sku' AND run_id=$1 AND upper(country)=$2 AND channel = ANY($4)
      GROUP BY sku`, [run, country, month, fchs])).rows.forEach(r => { fc[r.sku] = r; });
    // trailing velocity + last sale for slow-moving / clearance flags (same basis as the Slow Moving report:
    // units sold in the channel(s) over the last ~13 weeks). SLOW = >26wk trailing cover (or no recent sales);
    // CLEARANCE = discontinued with stock that won't clear by the month, OR a badly overstocked slow mover.
    const VEL_WEEKS = 13, SLOW_WKS = 26, CLR_WKS = 52;
    const vel = {}; (await pool.query(`SELECT sku,
        coalesce(sum(units) FILTER (WHERE month > (SELECT max(month) FROM planner.sales_actuals) - interval '3 months'),0)::numeric sold3,
        to_char(max(month) FILTER (WHERE units>0),'YYYY-MM-DD') last_m
      FROM planner.sales_actuals WHERE upper(country)=$1 AND channel = ANY($2) GROUP BY sku`, [country, fchs]))
      .rows.forEach(r => { vel[r.sku] = r; });
    const nowMs = Date.now();
    const rows = availSkus.map(sku => {
      const m = meta[sku] || {}, iv = inv[sku] || {}, f = fc[sku] || { dem_before: 0, dem_month: 0 }, vv = vel[sku] || {};
      const oh3 = iv[wh3] || 0, ohF = channel === 'fba' ? (iv[whF] || 0) : 0, ohAwd = (channel === 'fba' && isUS) ? (m.awd || 0) : 0;
      const ohTotal = channel === 'fba' ? (ohF + ohAwd) : oh3;   // FBA cover pool = FBA + AWD; 3PL is separate/transferable
      const inb = inbBefore[sku] || 0, demB = Number(f.dem_before) || 0, demM = Number(f.dem_month) || 0;
      const projected = ohTotal + inb - demB;
      const rate = demM / 4.33;   // weekly sell-through in the selected month
      const weeks = rate > 0 ? Math.round(Math.max(0, projected) / rate * 10) / 10 : null;  // null = no forecast → infinite cover
      const discontinued = !!(m.disc && m.disc < monthStart);
      const trailVel = (Number(vv.sold3) || 0) / VEL_WEEKS;
      const trailCover = ohTotal > 0 ? (trailVel > 0 ? Math.round(ohTotal / trailVel) : null) : 0;  // null = has stock, no trailing sales
      const daysSince = vv.last_m ? Math.round((nowMs - Date.parse(vv.last_m)) / 864e5) : null;
      const slowMoving = ohTotal > 0 && (trailVel === 0 || (trailCover != null && trailCover > SLOW_WKS));
      const recClearance = (discontinued && projected > 0) || (slowMoving && (trailVel === 0 || (trailCover != null && trailCover > CLR_WKS)));
      return { sku, name: m.name || '', oh_fba: ohF, oh_awd: ohAwd, oh_3pl: oh3, oh_total: ohTotal,
        inbound_before: inb, dem_before: demB, projected, dem_month: demM, weeks, discontinued,
        trail_cover: trailCover, days_since: daysSince, slow_moving: slowMoving, rec_clearance: recClearance };
    });
    res.json({ rows, country, channel, month, isUS, forecast_run: run });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});

app.post('/api/scenario/prime-day', async (req, res) => {
  const b = req.body || {};
  const skus = Array.isArray(b.skus) ? b.skus.filter(Boolean).map(s => s.trim().toUpperCase()) : [];
  const country = (b.country || '').toLowerCase(); // '' = all markets
  const category = b.category || '';
  const FBA_COS = ['uk', 'us', 'eu', 'au', 'ca'];
  if (country && !FBA_COS.includes(country)) return res.status(400).json({ error: 'unknown market' });
  const where = [], vals = []; let i = 1;
  if (skus.length) { where.push(`upper(p.sku) = ANY($${i++})`); vals.push(skus); }
  if (category) { where.push(`p.category = $${i++}`); vals.push(category); }
  const piOn = country ? ` AND pi.warehouse LIKE $${i++}` : '';
  if (country) vals.push(country + '\\_%');
  const wsql = where.length ? 'WHERE ' + where.join(' AND ') : '';
  const awdApplies = (country === '' || country === 'us'); // AWD is a US warehouse
  const pAwd = i++, pSkuFlag = i; // param indexes for awdApplies + "skus listed" flag
  // v28.213 (Ben): inbound to FBA per country. v28.214 (Ben): SHIPPED stock only, with an ETA and a reference: open (unreceived)
  // inbound shipments, plus in-flight FBA transfers once dispatched and not yet on a shipment. Unshipped POs and AWD are NOT
  // counted (Ben 07-Oct). A shipment of an FBA-branch PO counts as that country's FBA even when it lands at a 3PL first
  // (routed via crossdock). Optional "arriving by" date: only ETAs on or before it.
  const by = /^\d{4}-\d{2}-\d{2}$/.test(String(b.by || '')) ? b.by : null;
  const inbSel = country ? `coalesce(ib.${country},0)` : FBA_COS.map(c => `coalesce(ib.${c},0)`).join('+');
  const pBy = pSkuFlag + 1;   // last param
  try {
    const { rows } = await pool.query(`
      WITH src AS (
        SELECT i.sku, CASE WHEN po.branch ILIKE '%fba%' THEN lower(coalesce(nullif(po.country_code,''), b.country_code)) || '_fba'
                           ELSE i.destination_warehouse END wh,
          (i.quantity-coalesce(i.received_quantity,0)) q, i.estimated_delivery_date::date eta
        FROM planner.inbound_shipments i
        LEFT JOIN planner.purchase_orders po ON po.po=i.reference
        LEFT JOIN planner.branches b ON b.name=po.branch
        WHERE coalesce(i.received_quantity,0) < i.quantity AND i.reference NOT IN (${EXCL_REF_LIST})
          AND coalesce(trim(i.reference),'') <> '' AND i.estimated_delivery_date IS NOT NULL
        UNION ALL
        SELECT t.sku, t.warehouse, t.qty, t.eta::date FROM planner.fba_pending_transfers t
          WHERE t.received_date IS NULL AND t.dispatched_date IS NOT NULL AND t.eta IS NOT NULL AND coalesce(trim(t.reference),'') <> ''
            AND NOT EXISTS (SELECT 1 FROM planner.inbound_shipments s WHERE s.reference=t.reference)),
      inb AS (SELECT sku, ${FBA_COS.map(c => `sum(q) FILTER (WHERE wh='${c}_fba')::int ${c}`).join(', ')} FROM src
        WHERE wh LIKE '%\\_fba' AND ($${pBy}::date IS NULL OR eta <= $${pBy}::date) GROUP BY sku)
      SELECT p.sku, coalesce(p.product_name,'') name, coalesce(p.category,'') category,
        coalesce(sum(pi.available) FILTER (WHERE pi.warehouse LIKE '%\\_fba'),0)::int fba,
        coalesce(sum(pi.available) FILTER (WHERE pi.warehouse LIKE '%\\_3pl'),0)::int three_pl,
        (CASE WHEN $${pAwd} THEN coalesce(p.inventory_us_awd,0)::int ELSE 0 END)::int awd,
        (coalesce(sum(pi.available),0) + CASE WHEN $${pAwd} THEN coalesce(p.inventory_us_awd,0)::int ELSE 0 END)::int total,
        ${FBA_COS.map(c => `coalesce(ib.${c},0)::int inb_${c}`).join(', ')}, (${inbSel})::int inb_fba
      FROM planner.products p
      LEFT JOIN planner.v_product_inventory pi ON pi.sku=p.sku${piOn}
      LEFT JOIN inb ib ON ib.sku=p.sku
      ${wsql}
      GROUP BY p.sku, p.product_name, p.category, p.inventory_us_awd, ${FBA_COS.map(c => 'ib.' + c).join(', ')}
      HAVING coalesce(sum(pi.available),0) > 0 OR coalesce(p.inventory_us_awd,0)::int > 0 OR (${inbSel}) > 0 OR $${pSkuFlag} = true
      ORDER BY total DESC, inb_fba DESC`, [...vals, awdApplies, skus.length > 0, by]);
    const tot = rows.reduce((a, r) => { ['fba', 'three_pl', 'awd', 'total', 'inb_fba', ...FBA_COS.map(c => 'inb_' + c)].forEach(k => { a[k] = (a[k] || 0) + r[k]; }); return a; }, { fba: 0, three_pl: 0, awd: 0, total: 0, inb_fba: 0 });
    res.json({ rows, totals: tot, sku_count: rows.length, awd_available: awdApplies, inb_countries: country ? [country] : FBA_COS, by });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});

// Buy-plan extra stock pools per SKU: AWD (US upstream, inventory_us_awd) + NonGRS on-hand (UK/US). The buy
// plan pools AWD into FBA cover and shows it in its own column; NonGRS is shown as a sub-line under SOH 3PL
// (display only). Defensive on the NonGRS columns so it works if those columns are absent (returns 0 until then).
app.get('/api/buy-extra-stock', async (req, res) => {
  try {
    const cols = (await pool.query(`SELECT column_name FROM information_schema.columns
      WHERE table_schema='planner' AND table_name='products'
        AND column_name IN ('inventory_uk_nongrs','inventory_us_nongrs')`)).rows.map(r => r.column_name);
    const ukn = cols.includes('inventory_uk_nongrs') ? 'coalesce(inventory_uk_nongrs,0)' : '0';
    const usn = cols.includes('inventory_us_nongrs') ? 'coalesce(inventory_us_nongrs,0)' : '0';
    const rows = (await pool.query(`SELECT sku, coalesce(inventory_us_awd,0)::int awd, ${ukn}::int nuk, ${usn}::int nus
      FROM planner.products WHERE in_planning_scope`)).rows;
    const stock = {};
    rows.forEach(r => { if (r.awd || r.nuk || r.nus) stock[r.sku] = { awd: r.awd, nuk: r.nuk, nus: r.nus }; });
    res.json({ stock, has_nongrs: cols.length === 2 });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});

// B2B Allocation — per requested SKU: available stock in the market, recent velocity (cover),
// per-unit weight (airfreight rush), wholesale price (50% of ex-VAT retail) and avg cost (margin).
app.post('/api/scenario/b2b', async (req, res) => {
  const b = req.body || {};
  const skus = (Array.isArray(b.skus) ? b.skus : []).filter(Boolean).map(s => s.trim().toUpperCase());
  const market = (b.market || 'UK').toLowerCase();
  const date = (b.date && /^\d{4}-\d{2}-\d{2}$/.test(b.date)) ? b.date : null;   // required-by date for the B2B order
  if (!skus.length) return res.json({ rows: [] });
  try {
    const { rows } = await pool.query(`
      SELECT p.sku, coalesce(p.product_name,'') name, coalesce(p.category,'') category,
        (coalesce((SELECT sum(available) FROM planner.v_product_inventory pi WHERE pi.sku=p.sku AND pi.warehouse LIKE $2||'\\_%'),0)
         + CASE WHEN $2='us' THEN coalesce(p.inventory_us_awd,0)::int ELSE 0 END)::int available,
        coalesce((SELECT sum(units) FROM planner.sales_actuals sa WHERE sa.sku=p.sku AND lower(sa.country)=$2
                  AND sa.month > (SELECT max(month) FROM planner.sales_actuals) - interval '3 months'),0)::int recent_units,
        p.prod_weight_uk weight,
        (CASE $2 WHEN 'uk' THEN p.uk_rt WHEN 'us' THEN p.us_rt WHEN 'eu' THEN p.eu_rt
                 WHEN 'au' THEN p.au_rt WHEN 'ca' THEN p.ca_rt END) retail,
        (CASE $2 WHEN 'uk' THEN p.cogs_uk_3pl_final WHEN 'us' THEN p.cogs_us_3pl_final WHEN 'eu' THEN p.cogs_eu_3pl_final
                 WHEN 'au' THEN p.cogs_au_3pl_final WHEN 'ca' THEN p.cogs_ca_3pl_final END) cogs,
        (SELECT round(avg(cost_price),2) FROM planner.purchase_order_lines l WHERE l.sku=p.sku AND coalesce(cost_price,0) > 0) avg_cost,
        -- inbound for this market: landing on/before the order date (only when a date is given), plus the next inbound
        coalesce((SELECT sum(ib.quantity - coalesce(ib.received_quantity,0)) FROM planner.inbound_shipments ib
           WHERE ib.sku=p.sku AND ib.destination_warehouse LIKE $2||'\\_%' AND ib.quantity > coalesce(ib.received_quantity,0) AND ib.reference NOT IN (${EXCL_REF_LIST})
             AND $3::date IS NOT NULL AND ib.estimated_delivery_date <= $3::date),0)::int inbound_by_date,
        coalesce((SELECT sum(ib.quantity - coalesce(ib.received_quantity,0)) FROM planner.inbound_shipments ib
           WHERE ib.sku=p.sku AND ib.destination_warehouse LIKE $2||'\\_%' AND ib.quantity > coalesce(ib.received_quantity,0) AND ib.reference NOT IN (${EXCL_REF_LIST})),0)::int inbound_total,
        to_char((SELECT min(ib.estimated_delivery_date) FROM planner.inbound_shipments ib
           WHERE ib.sku=p.sku AND ib.destination_warehouse LIKE $2||'\\_%' AND ib.quantity > coalesce(ib.received_quantity,0) AND ib.reference NOT IN (${EXCL_REF_LIST})
             AND ib.estimated_delivery_date >= CURRENT_DATE),'YYYY-MM-DD') next_inbound_date,
        coalesce((SELECT sum(ib.quantity - coalesce(ib.received_quantity,0)) FROM planner.inbound_shipments ib
           WHERE ib.sku=p.sku AND ib.destination_warehouse LIKE $2||'\\_%' AND ib.quantity > coalesce(ib.received_quantity,0) AND ib.reference NOT IN (${EXCL_REF_LIST})
             AND ib.estimated_delivery_date = (SELECT min(ib2.estimated_delivery_date) FROM planner.inbound_shipments ib2
                WHERE ib2.sku=p.sku AND ib2.destination_warehouse LIKE $2||'\\_%' AND ib2.quantity > coalesce(ib2.received_quantity,0) AND ib2.reference NOT IN (${EXCL_REF_LIST}) AND ib2.estimated_delivery_date >= CURRENT_DATE)),0)::int next_inbound_qty,
        -- in-production stock that could be pulled/expedited: OPEN Production-status POs carrying this SKU, EXCLUDING
        -- Direct-to-Client POs (their units are already committed). Any market — branch shown so a redirect is visible.
        coalesce((SELECT json_agg(json_build_object('po',po2.po,'qty',l2.qty::int,'branch',coalesce(po2.branch,''),
             'supplier',coalesce(po2.supplier_name,''),'prod_no',coalesce(po2.prod_no,''),
             'date', to_char(coalesce(po2.delivery_date_overide,po2.landing_date_overide,po2.end_production_overide),'YYYY-MM-DD'),
             -- market of the PO's branch, and the earliest date this PO could realistically LAND in the ORDER's
             -- market if expedited: today + supplier expedited-production weeks + target-market air lead. The client
             -- only counts a PO toward cover when it is in-market AND exped_land <= the required-by date.
             'po_market', lower(coalesce(brp.country_code,'')),
             'exped_weeks', s2.expedited_production_weeks,
             'exped_land', to_char(CURRENT_DATE + ((coalesce(s2.expedited_production_weeks,4)*7)::numeric
                 + coalesce((SELECT min(air_lead_time_days) FROM planner.branches WHERE lower(country_code)=$2),7))::int, 'YYYY-MM-DD'))
             ORDER BY coalesce(po2.delivery_date_overide,po2.landing_date_overide,po2.end_production_overide) NULLS LAST)
           FROM planner.purchase_order_lines l2 JOIN planner.purchase_orders po2 ON po2.po=l2.po
             LEFT JOIN planner.suppliers s2 ON lower(trim(s2.name))=lower(trim(po2.supplier_name))
             LEFT JOIN planner.branches brp ON brp.name=po2.branch
           WHERE l2.sku=p.sku AND coalesce(l2.qty,0)>0 AND coalesce(po2.status,'') ILIKE 'production%'
             AND coalesce(po2.branch,'') NOT ILIKE '%direct to client%'
             AND coalesce(po2.branch,'') NOT ILIKE '%jlew%' AND coalesce(po2.branch,'') NOT ILIKE '%next%'), '[]'::json) production
      FROM planner.products p WHERE upper(p.sku) = ANY($1)`, [skus, market, date]);
    res.json({ market: market.toUpperCase(), date, rows });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});

