// ═══════════════════════════════════════════════════════════════════════════════════════════════════════════════════
// ── v28.008 (Ben): CLIENT PORTAL — Horizon CLIENT tab (admin) + client-facing portal at /client (migration 306) ──
// Spec: "Dock & Bay Client Portal — Build Spec" (28-Sep-2026). One portal shell for key accounts, distributors, agents and
// direct wholesale, differentiated by config: what they can SEE (visibility modes) and what they can DO (feature toggles).
// Admin surface = the CLIENT top tab (grant: app_permissions.client_access; commissions need app_permissions.commissions).
// Portal auth = magic link → httpOnly cookie `csid` (same mechanism as the supplier portal, separate tables).
// ═══════════════════════════════════════════════════════════════════════════════════════════════════════════════════
const CP_TYPES = ['key_account', 'distributor', 'agent', 'direct_wholesale'];
const CP_FEATURE_DEFAULTS = { order_placement: true, sample_requests: true, view_stock: true, view_line_sheet: true, view_commission: false, messaging: true };
const CP_WAREHOUSES = { uk_3pl: 'UK ILG', us_3pl: 'US Geneva', eu_3pl: 'EU iFulfilment (Bocholt)', au_3pl: 'AU Coghlans', uk_fba: 'UK Amazon FBA', us_fba: 'US Amazon FBA', eu_fba: 'EU Amazon FBA', au_fba: 'AU Amazon FBA', ca_fba: 'CA Amazon FBA' };
const CP_MARKETS = { UK: { currency: 'GBP', wh: 'uk_3pl', dims: 'uk', hs: 'hscode_uk' }, US: { currency: 'USD', wh: 'us_3pl', dims: 'us', hs: 'hscode_us' }, EU: { currency: 'EUR', wh: 'eu_3pl', dims: 'uk', hs: 'hscode_eu' }, AU: { currency: 'AUD', wh: 'au_3pl', dims: 'uk', hs: 'hscode_au' }, CA: { currency: 'CAD', wh: 'ca_fba', dims: 'us', hs: 'hscode_ca' } };
const CP_FULFIL_WH = { uk_3pl: 'ILG', eu_3pl: 'EUIFUL', us_3pl: 'USGENEVA_STD', au_3pl: 'AUCOGHLANS' };   // Horizon warehouse code → Fulfil stock.location code
const CP_CHANNEL_ALIAS = { UKWS: 'dockandbay-uk-ws', USWS: 'dockandbay-us-ws', EUWS: 'dockandbay-eu-ws', AUWS: 'dockandbay-au-ws', UK: 'dockandbay-uk', US: 'dockandbay-us', EU: 'dockandbay-eu', AU: 'dockandbay-au' };
const CP_BANDS_DEFAULT = [{ upto: 20, label: '<20' }, { upto: 100, label: '20+' }, { upto: 300, label: '100+' }, { upto: 500, label: '300+' }, { upto: 1000, label: '500+' }, { upto: null, label: '1000+' }];
function cpParseBands(v) {
  if (Array.isArray(v)) return v.length ? v : CP_BANDS_DEFAULT;
  if (typeof v === 'string' && v.trim()) { try { const j = JSON.parse(v); if (Array.isArray(j) && j.length) return j; } catch (e) {} }
  return CP_BANDS_DEFAULT;
}
async function cpStockBands() { return cpParseBands(await cpSetting('cp_stock_bands', '')); }
function cpBand(n, bands) { n = Number(n) || 0; const B = (bands && bands.length) ? bands : CP_BANDS_DEFAULT; for (const b of B) { if (b.upto == null || b.upto === '' || n < Number(b.upto)) return b.label; } return B[B.length - 1].label; }
function cpSlug(s) { return String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 40); }
function cpJson(v, def) { if (v == null) return def; if (typeof v === 'object') return v; try { return JSON.parse(v); } catch (e) { return def; } }
async function cpAudit(clientId, event, detail, by) { try { await pool.query(`INSERT INTO planner.client_audit (client_id,event,detail,changed_by) VALUES ($1,$2,$3,$4)`, [clientId, event, detail || null, by || null]); } catch (e) {} }
async function cpSetting(key, def) { try { const r = (await pool.query(`SELECT value FROM planner.app_settings WHERE key=$1`, [key])).rows[0]; return (r && r.value != null && r.value !== '') ? r.value : def; } catch (e) { return def; } }
async function cpClientById(id) {
  const r = (await pool.query(`SELECT c.*, rg.name rep_group_name, rg.default_rate rep_default_rate FROM planner.clients c LEFT JOIN planner.rep_groups rg ON rg.id=c.rep_group_id WHERE c.id=$1`, [id])).rows[0];
  if (!r) return null;
  r.visibility = cpJson(r.visibility, {}); r.stock_scope = cpJson(r.stock_scope, { mode: 'default' }); r.features = Object.assign({}, CP_FEATURE_DEFAULTS, cpJson(r.features, {}));
  return r;
}
// ── v28.101 (Ben): computed price tiers ─────────────────────────────────────────────────────────────────────────────
// RT = market retail (planner.products <mkt>_rt, incl tax) · ex-tax = RT ÷ (UK/EU 1.2, AU 1.1, US/CA 1.0) ·
// WS = ex-tax ÷ 2 · Distributor = WS × (1 - discount), discount from planner.distributor_offers per market + method.
const CP_RT_COL = { UK: 'uk_rt', US: 'us_rt', EU: 'eu_rt', AU: 'au_rt', CA: 'ca_rt' };
const CP_TAX_DIV = { UK: 1.2, EU: 1.2, AU: 1.1, US: 1.0, CA: 1.0 };
const CP_DIST_OFFER = { UK: 'UKWS', US: 'USWS', EU: 'EUWS', AU: 'AU', CA: null };   // market → distributor_offers.name
let _distOffers = { at: 0, map: null };
async function cpDistOffers() {
  if (_distOffers.map && Date.now() - _distOffers.at < 300000) return _distOffers.map;
  const map = {}; try { (await pool.query(`SELECT name, fob_discount, exw_discount, threepl_discount FROM planner.distributor_offers`)).rows
    .forEach(r => { map[r.name] = { fob: r.fob_discount, exw: r.exw_discount, '3pl': r.threepl_discount }; }); } catch (e) { /* table absent → no offers */ }
  _distOffers = { at: Date.now(), map }; return map;
}
const _r2 = n => Math.round(n * 100) / 100;
// Compute one tier's price for a product row (with <mkt>_rt columns), given market + tier + method. Returns a number
// or null when the retail price is missing. `offers` is the cpDistOffers() map (pass it so a batch shares one load).
function cpTierPrice(row, market, tier, method, offers) {
  const mkt = String(market || '').toUpperCase(); const col = CP_RT_COL[mkt]; if (!col) return null;
  const retail = Number(row[col]); if (!(retail > 0)) return null;
  const exTax = retail / (CP_TAX_DIV[mkt] || 1.0);
  if (tier === 'rt') return _r2(retail);
  const ws = exTax / 2;
  if (tier === 'ws') return _r2(ws);
  if (tier === 'dist') {
    const offer = (offers || {})[CP_DIST_OFFER[mkt]]; const disc = offer ? offer[method] : null;
    if (disc == null) return _r2(ws);   // no discount configured for this market/method → wholesale
    return _r2(ws * (1 - Number(disc) / 100));
  }
  return null;
}
// Read-only price preview: RT / WS / Distributor(FOB/EXW/3PL) for a client (or an explicit market), across a sample of
// SKUs, so the tier + numbers can be eyeballed before the line sheet is flipped to computed pricing. No live change.
app.get('/api/client/price-preview', async (req, res) => {
  try {
    let market = String(req.query.market || '').toUpperCase();
    if (!market && req.query.client_id) { const c = await cpClientById(req.query.client_id); if (c) market = String(c.market || '').toUpperCase(); }
    if (!CP_RT_COL[market]) return res.status(400).json({ error: 'a valid market (UK/US/EU/AU/CA) or client_id is required' });
    const offers = await cpDistOffers();
    const col = CP_RT_COL[market];
    const rows = (await pool.query(`SELECT sku, coalesce(product_name,'') product_name, ${col}
      FROM planner.products WHERE coalesce(status,'') NOT ILIKE '%discontinued%' AND ${col} IS NOT NULL AND ${col} > 0
      ORDER BY sku LIMIT 30`)).rows;
    const skus = rows.map(r => ({ sku: r.sku, name: r.product_name,
      rt: cpTierPrice(r, market, 'rt', null, offers), ws: cpTierPrice(r, market, 'ws', null, offers),
      dist_fob: cpTierPrice(r, market, 'dist', 'fob', offers), dist_exw: cpTierPrice(r, market, 'dist', 'exw', offers), dist_3pl: cpTierPrice(r, market, 'dist', '3pl', offers) }));
    res.set('Cache-Control', 'no-store').json({ ok: true, market, tax_divisor: CP_TAX_DIV[market], offer: (offers || {})[CP_DIST_OFFER[market]] || null, skus });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// order_origin: before the Cin7 cut-off → cin7 · from the Fulfil start → fulfil · in between → the imported Cin7 list decides.
async function cpOriginRule(cached) {   // v28.175 (Ben): cached = read through the portal settings cache (portal path only; admin stays live)
  const g = cached ? cpSettingC : cpSetting;
  return { cin7Until: await g('cp_cutover_cin7_until', '2026-09-06'), fulfilFrom: await g('cp_cutover_fulfil_from', '2026-10-01') };
}

// ── admin gate: every /api/client/* needs CLIENT access (sandbox = open); /api/client/commission* needs COMMISSIONS ──
async function cpAdminGate(req, res, next) {
  try {
    const me = await permsFor(req);
    if (me.live && !(me.is_admin || me.client_access)) return res.status(403).json({ error: 'CLIENT access required — ask an admin (CONFIG ▸ Admin ▸ Permissions)', code: 'no_client_access' });
    if (/^\/commission/.test(req.path) && me.live && !(me.is_admin || me.commissions)) return res.status(403).json({ error: 'COMMISSIONS access required', code: 'no_commissions' });
    req.me = me; next();
  } catch (e) { res.status(500).json({ error: e.message }); }
}
app.use('/api/client', cpAdminGate);

// ── lookups for the admin forms ──
app.get('/api/client/lookups', async (req, res) => {
  try {
    // v28.086 (Ben): the user-independent reference data (rep groups, key accounts, price lists, and the two
    // fulfil_sales GROUP BYs — the channel/country scans were the ~3s cold cost) is memoised for 5 min (SWR), so the
    // first CLIENT visit / a section switch no longer waits on those. Only `me` stays per-request.
    const base = await swrGet('client:lookups', 5 * 60 * 1000, async () => {
      const [rg, ka, ch, pl, cnt] = await Promise.all([
        pool.query(`SELECT id, name, default_rate, coalesce(xero_contact,'') xero_contact, coalesce(xero_account_code,'') xero_account_code FROM planner.rep_groups WHERE active ORDER BY name`),
        pool.query(`SELECT id, name FROM planner.key_accounts ORDER BY name`),
        pool.query(`SELECT channel, count(*)::int n FROM planner.fulfil_sales WHERE coalesce(channel,'')<>'' GROUP BY 1 ORDER BY 2 DESC`).catch(() => ({ rows: [] })),
        pool.query(`SELECT code, max(label) label, max(market) market, max(currency) currency, count(*)::int skus FROM planner.client_price_lists GROUP BY code ORDER BY code`).catch(() => ({ rows: [] })),
        pool.query(`SELECT country_code, count(*)::int n FROM planner.fulfil_sales WHERE coalesce(country_code,'')<>'' GROUP BY 1 ORDER BY 2 DESC LIMIT 40`).catch(() => ({ rows: [] })),
      ]);
      return { types: CP_TYPES, warehouses: CP_WAREHOUSES, markets: Object.keys(CP_MARKETS), feature_defaults: CP_FEATURE_DEFAULTS,
        rep_groups: rg.rows, key_accounts: ka.rows, channels: ch.rows, countries: cnt.rows, price_lists: pl.rows, channel_alias: CP_CHANNEL_ALIAS };
    });
    res.set('Cache-Control', 'no-store').json(Object.assign({}, base, {
      me: { email: req.me.email, commissions: !!(req.me.is_admin || req.me.commissions || !req.me.live) } }));
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});

// ── clients ──
