app.get('/api/client/clients/:id', async (req, res) => {
  try {
    const c = await cpClientById(req.params.id); if (!c) return res.status(404).json({ error: 'not found' });
    // v28.198 (Ben): header "last login" = latest of a user's portal sign-in and any live session's last_seen_at (migration 335), else its
    // created_at; staff preview sessions (cppv_) excluded. Falls back to sign-ins + session created_at if 335 is not applied yet.
    const lastQ = (seen) => pool.query(`SELECT to_char(GREATEST((SELECT max(u.last_login_at) FROM planner.client_users u WHERE u.client_id=$1),
        (SELECT max(${seen ? 'COALESCE(s.last_seen_at, s.created_at)' : 's.created_at'}) FROM planner.client_sessions s JOIN planner.client_users u ON u.id=s.user_id WHERE u.client_id=$1 AND s.token NOT LIKE 'cppv\\_%')),'YYYY-MM-DD HH24:MI') last_login`, [c.id]);
    const [users, audit, orders, ka, last] = await Promise.all([
      pool.query(`SELECT id, name, email, scope, active, to_char(invited_at,'YYYY-MM-DD') invited_at, to_char(last_login_at,'YYYY-MM-DD HH24:MI') last_login_at FROM planner.client_users WHERE client_id=$1 ORDER BY active DESC, name, email`, [c.id]),
      pool.query(`SELECT to_char(changed_at,'YYYY-MM-DD HH24:MI') at, changed_by, event, detail FROM planner.client_audit WHERE client_id=$1 ORDER BY changed_at DESC LIMIT 60`, [c.id]),
      pool.query(`SELECT id, order_type, status, customer_po, units, total, currency, fulfil_number, error, to_char(created_at,'YYYY-MM-DD HH24:MI') created_at, submitted_by FROM planner.client_orders WHERE client_id=$1 ORDER BY created_at DESC LIMIT 30`, [c.id]),
      c.key_account_id ? pool.query(`SELECT id, name, consignee, contact_person, contact_number, address FROM planner.key_accounts WHERE id=$1`, [c.key_account_id]) : Promise.resolve({ rows: [] }),
      lastQ(true).catch(() => lastQ(false)).catch(() => ({ rows: [] })),
    ]);
    res.set('Cache-Control', 'no-store').json({ client: c, users: users.rows, audit: audit.rows, portal_orders: orders.rows, key_account: ka.rows[0] || null, last_login: (last.rows[0] && last.rows[0].last_login) || null });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
const CP_CLIENT_FIELDS = { name: 'text', type: 'text', owner_email: 'text', market: 'text', currency: 'text', price_list: 'text', price_tier: 'text', price_method: 'text', warehouse_code: 'text', visibility: 'json', stock_scope: 'json', features: 'json', rep_group_id: 'int', key_account_id: 'int', fulfil_party_id: 'int', fulfil_channel: 'text', notes: 'text', active: 'bool' };
app.post('/api/client/clients/:id', async (req, res) => {
  const b = req.body || {}; const sets = [], vals = [], changed = [];
  const before = await cpClientById(req.params.id); if (!before) return res.status(404).json({ error: 'not found' });
  for (const [k, t] of Object.entries(CP_CLIENT_FIELDS)) {
    if (!(k in b)) continue; let v = b[k];
    if (t === 'json') v = JSON.stringify(v == null ? {} : v); else if (t === 'int') v = (v === '' || v == null) ? null : parseInt(v, 10); else if (t === 'bool') v = !!v; else v = (v == null) ? null : String(v);
    if (k === 'type' && !CP_TYPES.includes(v)) continue; if (k === 'market' && !CP_MARKETS[v]) continue;
    vals.push(v); sets.push(k + '=$' + vals.length + (t === 'json' ? '::jsonb' : '')); changed.push(k);
  }
  if (!sets.length) return res.json({ ok: true, unchanged: true });
  vals.push(req.me.email || 'sandbox'); sets.push('updated_by=$' + vals.length); sets.push('updated_at=now()'); vals.push(req.params.id);
  try {
    await pool.query(`UPDATE planner.clients SET ${sets.join(', ')} WHERE id=$${vals.length}`, vals);
    const detail = changed.map(k => { const nv = b[k]; const ov = before[k]; const s = v => (v && typeof v === 'object') ? JSON.stringify(v) : String(v == null ? '' : v); return k + ': ' + s(ov).slice(0, 60) + ' → ' + s(nv).slice(0, 60); }).join(' · ');
    await cpAudit(req.params.id, 'Client updated', detail, req.me.email);
    res.json({ ok: true });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
app.post('/api/client/clients/:id/delete', async (req, res) => {
  try { const c = await cpClientById(req.params.id); if (!c) return res.status(404).json({ error: 'not found' });
    await pool.query(`DELETE FROM planner.clients WHERE id=$1`, [req.params.id]); await cpAudit(null, 'Client deleted', c.name + ' (#' + c.id + ')', req.me.email); res.json({ ok: true });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});

// ── users + magic links ──
const cpToken = () => crypto.randomBytes(24).toString('hex');
function cpBase(req) {
  const proto = req.headers['x-forwarded-proto'] || 'http';
  const host = String(req.headers['x-forwarded-host'] || req.headers.host || '').split(',')[0].trim();
  // v28.104: production dockandbay.com hosts mint client links on the dedicated portal subdomain — an admin
  // copying a magic link from horizon.dockandbay.com still produces a client.dockandbay.com link. Previews
  // (*.vercel.app) and the sandbox keep the request host so their links stay self-contained.
  if (CLIENT_HOST && !IS_SANDBOX && /(^|\.)dockandbay\.com$/i.test(host.split(':')[0])) return 'https://' + CLIENT_HOST;
  return proto + '://' + host;
}
// Admin (HORIZON) deep-links always resolve to the admin host, even when generated while serving a client request.
function adminBase(req) {
  const proto = req.headers['x-forwarded-proto'] || 'http';
  const host = String(req.headers['x-forwarded-host'] || req.headers.host || '').split(',')[0].trim();
  if (ADMIN_HOST && !IS_SANDBOX && /(^|\.)dockandbay\.com$/i.test(host.split(':')[0])) return 'https://' + ADMIN_HOST;
  return proto + '://' + host;
}
async function cpMintLink(userId, req) {
  const tok = cpToken();
  await pool.query(`INSERT INTO planner.client_magic_tokens (token,user_id,expires_at) VALUES ($1,$2, now()+interval '7 days')`, [tokHash(tok), userId]);   // v28.210 (Ben, H2): stored hashed, raw only in the link
  await pool.query(`UPDATE planner.client_users SET invited_at=now() WHERE id=$1`, [userId]);
  return cpBase(req) + '/client?token=' + tok;
}
// v28.097 (Ben): mint a 7-day magic link and RETURN it (do NOT email) — for the "copy magic link" action on the client card.
app.post('/api/client/users/:uid/magic', async (req, res) => {
  try { const u = (await pool.query(`SELECT id, client_id, email FROM planner.client_users WHERE id=$1`, [req.params.uid])).rows[0]; if (!u) return res.status(404).json({ error: 'not found' });
    const url = await cpMintLink(u.id, req);
    try { await cpAudit(u.client_id, 'Magic link minted', u.email + ' (copied, not emailed)', req.me.email); } catch (e) {}
    res.json({ ok: true, url });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
