// SUG-0019 P3: supplier confirms a spec — record a per-supplier acknowledgement for each of their directed names.
app.post('/api/portal/spec-approve', portalAuth, async (req, res) => {
  const specId = (req.body || {}).spec_id; if (!specId) return res.status(400).json({ error: 'spec_id required' });
  try {
    const sp = (await pool.query(`SELECT coalesce(confirm_suppliers,'') cs, confirm_with_supplier FROM planner.product_specs WHERE id=$1 AND active`, [specId])).rows[0];
    if (!sp || !sp.confirm_with_supplier) return res.status(404).json({ error: 'spec not found' });
    const directed = sp.cs.split(',').map(x => x.trim()).filter(Boolean);
    const mine = req.portal.suppliers.filter(n => directed.indexOf(n) >= 0);
    if (!mine.length) return res.status(403).json({ error: 'this spec is not directed to your account' });
    for (const n of mine) await pool.query(`INSERT INTO planner.product_spec_approvals (spec_id, supplier_name, approved_by) VALUES ($1,$2,$3) ON CONFLICT (spec_id, supplier_name) DO NOTHING`, [specId, n, req.portal.email]);
    // sync the legacy column: approved once every directed supplier has acknowledged
    const doneN = (await pool.query(`SELECT count(*)::int n FROM planner.product_spec_approvals WHERE spec_id=$1 AND supplier_name = ANY($2)`, [specId, directed])).rows[0].n;
    await pool.query(`UPDATE planner.product_specs SET approval_status=$2 WHERE id=$1`, [specId, doneN >= directed.length ? 'approved' : 'pending']);
    res.json({ ok: true });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// Serve a spec file to a supplier — only if the spec is relevant to (directed at / covers a product of) their account.
app.get('/api/portal/spec-file/:id', portalAuth, async (req, res) => {
  try {
    const s = (await pool.query(`SELECT filename, mime, data, storage_path, scope_type, coalesce(scope_category,'') scope_category, coalesce(scope_size,'') scope_size, coalesce(scope_skus,'') scope_skus, confirm_with_supplier, coalesce(confirm_suppliers,'') confirm_suppliers FROM planner.product_specs WHERE id=$1 AND active`, [req.params.id])).rows[0];
    if (!s) return res.status(404).send('not found');
    const directed = s.confirm_with_supplier && s.confirm_suppliers.split(',').map(x => x.trim()).some(n => req.portal.suppliers.indexOf(n) >= 0);
    let ok = directed;
    if (!ok) { const ss = await specSupplierSet(s); ok = req.portal.suppliers.some(n => ss.has(n)); }
    if (!ok) return res.status(403).send('forbidden');
    return serveFile(res, s);   // v28.151 (review B1): serveFile = allowlisted mime, nosniff, CSP sandbox, attachment unless image/PDF
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// Portal "recent changes" drawer — key events for THIS supplier, newest first (new PO, payment received, sample).
app.get('/api/portal/recent-activity', portalAuth, async (req, res) => {
  const names = req.portal.suppliers; if (!names.length) return res.json([]);
  try {
    // Payment-confirmed events appear only for a user who has opted in (receive_payment_notification). A payment is
    // "confirmed" when its run carries a bank amount + currency (applied in the Payments Report).
    // v28.175 (Ben): the opt-in check is now part of the one query (EXISTS an active row with the flag on = the old
    // bool_or(...) = true), so the drawer costs one round trip instead of two. Same rows.
    const payUnion = `
        UNION ALL SELECT coalesce(updated_at, run_date::timestamp) ts, 'payment' typ,
          'Payment confirmed — '||to_char(round(paid_amount),'FM999,999,999')||' '||paid_currency||' ('||to_char(run_date,'DD Mon YY')||')' label, '' ref
          FROM planner.payment_fx WHERE supplier = ANY($1) AND paid_amount IS NOT NULL AND coalesce(paid_currency,'')<>''
            AND EXISTS (SELECT 1 FROM planner.supplier_portal_users pu WHERE lower(pu.email)=lower($2) AND pu.active=true AND pu.receive_payment_notification)`;
    res.json((await pool.query(`
      SELECT to_char(ts,'YYYY-MM-DD HH24:MI') at, typ, label, ref FROM (
        -- "New purchase order" fires only once the PO is portal-visible (not FUTURE) — i.e. set to Production —
        -- so we never surface a PO the supplier can't open (matches the portal PO list's own NOT-future filter).
        SELECT created_at ts, 'po_created' typ, 'New purchase order '||po label, po ref
          FROM planner.purchase_orders WHERE created_at IS NOT NULL AND supplier_name = ANY($1)
            AND coalesce(status,'') NOT ILIKE '%future%'
        UNION ALL SELECT supplier_confirmed_at, 'po_confirmed', 'You confirmed order '||po, po
          FROM planner.purchase_orders WHERE supplier_confirmed_at IS NOT NULL AND supplier_name = ANY($1)
        -- "New shipment" fires only when at least one of the supplier's POs aboard it is in production / ready to
        -- ship / shipping (so the shipment is real and relevant to them — not a shell around FUTURE-only POs).
        UNION ALL SELECT sh.created_at, 'shipment_created', 'New shipment '||sh.shipment_ref, sh.shipment_ref
          FROM planner.shipments sh WHERE sh.created_at IS NOT NULL
            AND EXISTS (SELECT 1 FROM planner.purchase_orders po WHERE po.shipment_ref = sh.shipment_ref
                          AND po.supplier_name = ANY($1)
                          AND (po.status ILIKE 'production%' OR po.status ILIKE 'ready%' OR po.status ILIKE 'shipping%'))${payUnion}
        UNION ALL SELECT created_at, 'sample_created', 'New sample request SR-'||id, 'SR-'||id
          FROM planner.sample_requests WHERE created_at IS NOT NULL AND supplier_name = ANY($1)
      ) z ORDER BY at DESC NULLS LAST LIMIT 15`, [names, req.portal.email])).rows);
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// Portal "Inbox" drawer — the actual UNREAD Dock & Bay messages for THIS supplier across every thread type
// (PO, shipment, sample, product), newest first. Each row carries the note id + its thread type/ref so the
// client can render the message, link to the item, and mark it read via the matching read endpoint.
app.get('/api/portal/unread-messages', portalAuth, async (req, res) => {
  const names = req.portal.suppliers; if (!names.length) return res.json([]);
  try {
    // v28.189 (Ben, M2): shipment messages are unread per supplier (shipment_note_reads) and listed for every shipment the supplier is on
    // (master or rider, the v28.186 rule the Shipment Plan uses), so the Inbox matches the Shipment Plan badges.
    const ids = (req.portal.supplierIds || []).map(Number).filter(n => Number.isSafeInteger(n) && n > 0), snOk = ids.length > 0 && await snReadsOk();
    res.json((await pool.query(`
      SELECT type, ref, note_id, author, body, to_char(created_at,'YYYY-MM-DD HH24:MI') at FROM (
        SELECT 'po' type, n.po ref, n.id note_id, coalesce(n.author_email,'') author, n.body, n.created_at
          FROM planner.supplier_notes n JOIN planner.purchase_orders po ON po.po=n.po
          WHERE n.author_kind='internal' AND n.read_at IS NULL AND po.supplier_name = ANY($1)
            AND coalesce(po.status,'') NOT ILIKE '%future%'
        UNION ALL
        SELECT 'shipment', n.shipment_ref, n.id, coalesce(n.author_email,''), n.body, n.created_at
          FROM planner.shipment_notes n
          WHERE n.author_kind='internal' AND ${shipNoteUnreadSql(snOk, 'n', '$2')}
            AND (EXISTS (SELECT 1 FROM planner.purchase_orders po WHERE po.shipment_ref=n.shipment_ref AND po.supplier_name = ANY($1))
              OR EXISTS (SELECT 1 FROM planner.purchase_orders mp WHERE mp.po = coalesce((SELECT nullif(sh.master_po,'') FROM planner.shipments sh WHERE sh.shipment_ref=n.shipment_ref), n.shipment_ref) AND mp.supplier_name = ANY($1)))
        UNION ALL
        SELECT 'sample', sr.ref, n.id, coalesce(n.author_email,''), n.body, n.created_at
          FROM planner.sample_notes n JOIN planner.sample_requests sr ON sr.id=n.sample_id
          WHERE n.author_kind='internal' AND n.read_at IS NULL AND sr.supplier_name = ANY($1)
        UNION ALL
        SELECT 'product', n.po, n.id, coalesce(n.author_email,''), n.body, n.created_at
          FROM planner.supplier_notes n JOIN planner.product_dev_items pdi ON pdi.ref=n.po
          WHERE n.author_kind='internal' AND n.read_at IS NULL AND EXISTS (SELECT 1 FROM planner.product_dev_requests r WHERE r.item_id=pdi.id AND r.supplier_name = ANY($1))
            AND (n.supplier_id IS NULL OR n.supplier_id = ANY($2::bigint[]))   -- v28.191 (Ben, H6): never another supplier's request notes
      ) z ORDER BY created_at DESC NULLS LAST LIMIT 40`, [names, ids])).rows);
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// ── PORTAL PRODUCT (supplier-scoped): timeline view + comment on their assigned product-dev items ──
async function portalOwnsProduct(req, ref) { if (!ref || !req.portal.suppliers.length) return false;
  return (await pool.query(`SELECT 1 FROM planner.product_dev_items i WHERE i.ref=$1 AND EXISTS (SELECT 1 FROM planner.product_dev_requests r WHERE r.item_id=i.id AND r.supplier_name = ANY($2))`, [ref, req.portal.suppliers])).rowCount > 0; }   // v27.749 (P5): ownership via development REQUESTS only (item-level supplier column dropped)
app.get('/api/portal/product-notes/:ref', portalAuth, async (req, res) => { const ref = decodeURIComponent(req.params.ref || '');
  if (!(await portalOwnsProduct(req, ref))) return res.status(403).json({ error: 'not your product' });
  try {
    // v27.860 (Ben): a supplier must only see THEIR request's timeline + product-wide notes — never another supplier's
    // (a development request belongs to one supplier). Scope by the caller's supplier(s); supplier_id NULL = product-wide.
    const sups = (req.portal.suppliers || []).map(x => String(x).toLowerCase().trim());
    const ids = (await pool.query(`SELECT id FROM planner.suppliers WHERE lower(name)=ANY($1)`, [sups.length ? sups : ['']])).rows.map(r => r.id);
    res.json((await pool.query(`SELECT n.id, n.author_kind, coalesce(n.author_email,'') author_email, n.body,
    to_char(n.created_at,'YYYY-MM-DD HH24:MI') created_at, n.read_at IS NOT NULL read,
    n.attachment_id, coalesce(a.filename,'') attachment_name, coalesce(a.mime,'') attachment_mime, coalesce(n.pantone,'[]'::jsonb) pantone,
    n.sample_id, (SELECT ps.version FROM planner.product_dev_samples ps WHERE ps.id=n.sample_id) sample_version
    FROM planner.supplier_notes n LEFT JOIN planner.portal_attachments a ON a.id=n.attachment_id
    WHERE n.po=$1 AND (n.supplier_id IS NULL OR n.supplier_id = ANY($2::bigint[])) ORDER BY n.created_at`, [ref, ids.length ? ids : [-1]])).rows); }   // v27.866 (Ben): pantone + attachment + sample fields so the portal timeline styles like the admin
  catch (e) { log500(e); res.status(500).json({ error: e.message }); } });
app.post('/api/portal/product-note', portalAuth, async (req, res) => { const b = req.body || {}, ref = (b.ref || '').trim();
  if (!(await portalOwnsProduct(req, ref))) return res.status(403).json({ error: 'not your product' });
  if (!String(b.body || '').trim()) return res.status(400).json({ error: 'body required' });
  try { await pool.query(`INSERT INTO planner.supplier_notes (po, supplier_id, author_email, author_kind, body) VALUES ($1,$2,$3,'supplier',$4)`, [ref, await portalMyNoteSupplierId(req, ref), req.portal.email || null, String(b.body).trim()]); res.json({ ok: true }); }   // v28.191 (Ben, H6): scoped to the caller's supplier
  catch (e) { log500(e); res.status(500).json({ error: e.message }); } });
app.post('/api/portal/product-notes-read', portalAuth, async (req, res) => { const ref = ((req.body || {}).ref || '').trim();
  if (!(await portalOwnsProduct(req, ref))) return res.status(403).json({ error: 'not your product' });
  try { await pool.query(`UPDATE planner.supplier_notes SET read_at=now() WHERE po=$1 AND author_kind='internal' AND read_at IS NULL AND (supplier_id IS NULL OR supplier_id = ANY($2::bigint[]))`, [ref, (req.portal.supplierIds || []).map(Number)]); res.json({ ok: true }); }   // v28.191 (Ben, H6): only notes the caller can see
  catch (e) { log500(e); res.status(500).json({ error: e.message }); } });
// v27.761 (Ben): supplier ACCEPTS a product development request. Whole-product grain — marks every request this supplier
// holds for the item as accepted. Plain acknowledgement (no gating). Recorded on the timeline AND the change log.
app.post('/api/portal/product-accept', portalAuth, async (req, res) => { const ref = ((req.body || {}).ref || '').trim();
  if (!(await portalOwnsProduct(req, ref))) return res.status(403).json({ error: 'not your product' });
  try {
    const by = req.portal.email || 'supplier';
    const upd = await pool.query(`UPDATE planner.product_dev_requests r
        SET supplier_accepted_at=now(), supplier_accepted_by=$3, updated_at=now()
        FROM planner.product_dev_items i
        WHERE r.item_id=i.id AND i.ref=$1 AND r.supplier_name = ANY($2) AND r.supplier_accepted_at IS NULL
        RETURNING r.id, r.supplier_name, r.supplier_id`, [ref, req.portal.suppliers, by]);
    if (!upd.rowCount) return res.json({ ok: true, already: true });   // idempotent: nothing left to accept
    const supName = upd.rows[0].supplier_name || (req.portal.suppliers[0] || 'Supplier');
    try { await pool.query(`INSERT INTO planner.supplier_notes (po, supplier_id, author_email, author_kind, body) VALUES ($1,$2,$3,'supplier',$4)`, [ref, upd.rows[0].supplier_id || null, by, 'Accepted the development request']); } catch (e) { /* timeline best-effort */ }   // v27.857 (Ben): scope this note to the accepting supplier
    try { await logProductChange(ref, 'Development request accepted by ' + supName, null, by); } catch (e) { /* change-log best-effort */ }
    res.json({ ok: true, accepted: upd.rowCount, accepted_at: new Date().toISOString().slice(0, 10) });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); } });
// PORTAL product-sample versions (supplier-created, scoped to their assigned products)
app.get('/api/portal/product-samples/:ref', portalAuth, async (req, res) => { const ref = decodeURIComponent(req.params.ref || '');
  if (!(await portalOwnsProduct(req, ref))) return res.status(403).json({ error: 'not your product' });
  try { res.json(await productSampleList(ref, { supplierScope: req.portal.suppliers })); } catch (e) { log500(e); res.status(500).json({ error: e.message }); } });   // v27.848 (Ben): server-enforced — only THIS supplier's sample versions leave the server
// v27.533: the components THIS supplier is responsible for on a product → the portal's "Aspects sampled" list. A component with
// no supplier of its own belongs to the product's main supplier. Spec-linked components are not sampled, so they are left out.
app.get('/api/portal/product-components/:ref', portalAuth, async (req, res) => { const ref = decodeURIComponent(req.params.ref || '');
  if (!(await portalOwnsProduct(req, ref))) return res.status(403).json({ error: 'not your product' });
  try { const sups = (req.portal.suppliers || []).map(x => String(x).toLowerCase().trim());
    const prodMine = (await pool.query(`SELECT 1 FROM planner.product_dev_requests r JOIN planner.product_dev_items i ON i.id=r.item_id WHERE i.ref=$1 AND lower(r.supplier_name)=ANY($2) LIMIT 1`, [ref, sups])).rowCount > 0;   // v27.749 (P5): "my product" = I own a development request on it (item-level supplier dropped)
    const comps = (await pool.query(`SELECT id, name, coalesce(supplier,'') supplier, dimension, coalesce(sampling_mode,'sampled') sampling_mode FROM planner.product_dev_components WHERE item_ref=$1 ORDER BY sort, id`, [ref])).rows;
    const mine = comps.filter(c => c.sampling_mode !== 'spec_linked' && (c.supplier ? sups.includes(c.supplier.toLowerCase().trim()) : prodMine));
    res.json({ components: mine.map(c => ({ key: c.dimension || ('c' + c.id), name: c.name, dimension: c.dimension || null })), total: comps.length });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); } });
