// Barcode label rows — only for SKUs that appear on THIS supplier's POs (intersect with owned SKUs).
// SHIPS-WITH shipment-label fields for one PO — supplier-scoped mirror of /api/supply/ships-with/:po.
app.get('/api/portal/ships-with/:po', portalAuth, async (req, res) => {
  try {
    if (!await portalOwnsPO(req, req.params.po)) return res.status(403).json({ error: 'not your PO' });
    const r = await pool.query(`
      SELECT po.po production_ref, coalesce(po.supplier_name,'') source_supplier,
             coalesce(po.shipment_ref,'') ships_with_po, coalesce(po.branch,'') dest_branch,
             coalesce(nullif(po.country_code,''), b.country_code, '') dest_country,
             coalesce(po.client,'') client, coalesce(po.sales_order_ref,'') sales_order_ref,
             coalesce(mpo.supplier_name,'') ships_with_supplier
      FROM planner.purchase_orders po
      LEFT JOIN planner.branches b ON b.name=po.branch
      LEFT JOIN planner.shipments sh ON sh.shipment_ref=po.shipment_ref
      LEFT JOIN planner.purchase_orders mpo ON mpo.po = coalesce(nullif(sh.master_po,''), sh.shipment_ref)
      WHERE po.po=$1`, [req.params.po]);
    res.json(r.rows[0] || {});
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
app.get('/api/portal/label-data', portalAuth, async (req, res) => {
  try {
    const { po, prod, skus, batch, project } = req.query, names = req.portal.suppliers;
    let requested = [], proj = null;
    if (project) {   // v27.570: custom-barcode project download — only with its linked PO, only that PO's SKUs, only the custom numbers
      if (!po) return res.status(400).json({ error: 'po required with project' });
      proj = (await pool.query(`SELECT id, name, coalesce(batch,'') batch, coalesce(overrides,'{}'::jsonb) overrides, coalesce(pos,'{}'::text[]) pos FROM planner.barcode_projects WHERE id=$1::bigint`, [project])).rows[0];
      if (!proj || !proj.pos.includes(String(po))) return res.status(403).json({ error: 'that barcode project is not linked to this PO' });
      if (!await portalOwnsPO(req, po)) return res.status(403).json({ error: 'not your PO' });
      requested = Object.keys(proj.overrides || {});   // v27.572: the project's SKUs (owned-supplier filter below still applies), not only this PO's lines
    }
    if (proj) { /* requested already set from the project */ }
    else if (skus) requested = String(skus).split(',').map(s => s.trim()).filter(Boolean);
    else if (po) { if (!await portalOwnsPO(req, po)) return res.status(403).json({ error: 'not your PO' });
      requested = (await pool.query(`SELECT sku FROM planner.purchase_order_lines WHERE po=$1`, [po])).rows.map(r => r.sku); }
    else if (prod) requested = (await pool.query(`SELECT DISTINCT l.sku FROM planner.purchase_order_lines l JOIN planner.purchase_orders p ON p.po=l.po WHERE p.prod_no=$1 AND p.supplier_name = ANY($2)`, [prod, names])).rows.map(r => r.sku);
    else if (batch) requested = (await pool.query(`SELECT DISTINCT l.sku FROM planner.purchase_order_lines l JOIN planner.purchase_orders p ON p.po=l.po WHERE p.batch_id=$1 AND p.supplier_name = ANY($2)`, [batch, names])).rows.map(r => r.sku);
    else return res.status(400).json({ error: 'po/prod/skus/batch required' });
    if (!requested.length) return res.json([]);
    const owned = new Set((await pool.query(`SELECT DISTINCT l.sku FROM planner.purchase_order_lines l JOIN planner.purchase_orders p ON p.po=l.po WHERE p.supplier_name = ANY($1)`, [names])).rows.map(r => r.sku));
    const finalSkus = requested.filter(s => owned.has(s));
    if (!finalSkus.length) return res.json([]);
    const rows = (await pool.query(`
      SELECT sl.sku, sl.barcode_sku_name, sl.barcode_carton_name, sl.barcode_inner_name,
        sl.size, coalesce(p.size_short, sl.size_short, '') size_short, sl.category, coalesce(nullif(p.carton_qty::text,''), sl.carton_qty::text) carton_qty,
        sl.product_barcode, sl.carton_barcode, sl.inner_barcode, sl.grs_material, coalesce(p.colour_swatch_url, sl.swatch_url) swatch_url, coalesce(p.size_long,'') size_long, coalesce((SELECT s.code FROM planner.suppliers s WHERE lower(s.name)=lower(p.main_supplier_final) LIMIT 1),'') supplier_code,
        sl.uk_carton_l, sl.uk_carton_w, sl.uk_carton_h, sl.uk_carton_wt,
        coalesce(p.supplier_multiple_all,'') supplier_multiple, p.uk_rt, p.us_rt, p.eu_rt, coalesce(p.product_name,'') product_name
      FROM planner.v_sku_attrs sl LEFT JOIN planner.products p ON p.sku=sl.sku
      WHERE sl.sku = ANY($1) AND coalesce(sl.variant_type,'') NOT ILIKE 'set'
        AND coalesce(sl.product_barcode, sl.carton_barcode, sl.inner_barcode) IS NOT NULL
      ORDER BY sl.sku`, [finalSkus])).rows;
    // Stamp the batch + its production date on each row so the label can print BATCH / DATE OF PRODUCTION.
    // Resolve the batch from the explicit ?batch, else from the single PO's batch_id.
    let batchCode = batch || (proj && proj.batch) || null;
    if (!batchCode && po) { try { batchCode = (await pool.query(`SELECT batch_id FROM planner.purchase_orders WHERE po=$1`, [po])).rows[0]?.batch_id || null; } catch (e) {} }
    // v27.697: the PO card's "Download barcodes for <production>" passes ?batch_po=<that PO> → stamp THAT PO's batch
    // (Ben: the batch number must come from the PO; ?prod alone never stamped one → BATCH / DATE OF PRODUCTION blank).
    // Fallback for a bare ?prod: the single batch shared by this supplier's POs in the production, if unambiguous.
    const batchPo = req.query.batch_po ? String(req.query.batch_po) : '';
    if (!batchCode && batchPo && await portalOwnsPO(req, batchPo)) { try { batchCode = (await pool.query(`SELECT batch_id FROM planner.purchase_orders WHERE po=$1`, [batchPo])).rows[0]?.batch_id || null; } catch (e) {} }
    if (!batchCode && prod && !po) { try { const bs = (await pool.query(`SELECT DISTINCT batch_id FROM planner.purchase_orders WHERE prod_no=$1 AND supplier_name = ANY($2) AND coalesce(batch_id,'')<>''`, [prod, names])).rows.map(r => r.batch_id); if (bs.length === 1) batchCode = bs[0]; } catch (e) {} }
    if (batchCode) {
      let bd = null;
      try { bd = (await pool.query(`SELECT to_char(batch_date,'YYYY-MM-DD') d FROM planner.batches WHERE batch=$1`, [batchCode])).rows[0]?.d || null; } catch (e) {}
      rows.forEach(r => { r.batch = batchCode; r.batch_date = bd; });
    }
    if (proj) {   // same rule as the admin Customise drawer (bcItems): custom number on the ticked type(s), other types blanked, unmatched SKUs dropped
      const out = [];
      rows.forEach(r => { const v = proj.overrides[r.sku]; if (v == null) return;
        let num, t, pn = '', desc = ''; if (typeof v === 'object') { num = String(v.num || ''); t = v.types || {}; pn = v.pn ? String(v.pn) : ''; desc = v.desc ? String(v.desc) : ''; } else { num = String(v); t = { product: true }; }
        if (!num) return; if (!t.product && !t.carton && !t.inner) t = { product: true };
        const cl = Object.assign({}, r, { product_barcode: t.product ? num : '', carton_barcode: t.carton ? num : '', inner_barcode: t.inner ? num : '', pn: pn, desc: desc, custom_project: proj.name });   // v27.660 part number + v27.665 description onto the label row
        out.push(cl); });
      return res.json(out);
    }
    res.json(rows);
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});

