app.post('/api/portal/submit', portalAuth, async (req, res) => {
  const b = req.body || {}; if (!b.po) return res.status(400).json({ error: 'po required' });
  if (!await portalOwnsPO(req, b.po)) return portalDeny(res);
  if (b.invoice_value != null && String(b.invoice_value).trim() !== '' && sanitiseMoney(b.invoice_value) == null) return res.status(400).json({ error: 'Invoice value must be a number (no currency symbols or letters).' });
  // v28.191 (Ben, deep dive M7): every input is checked BEFORE the first write (a bad production status used to come back as a 400 after
  // the completion date, invoice, notes, emails and tracking had already been saved, and the 400 skipped the cache refresh).
  if (b.production_status != null && String(b.production_status).trim() !== '' && !PROD_STATUSES.includes(String(b.production_status).trim())) return res.status(400).json({ error: 'That production status is not one of the options. Please refresh the page and choose again.' });
  if (b.completion_date != null && b.completion_date !== '' && !(/^\d{4}-\d{2}-\d{2}$/.test(String(b.completion_date)) && !isNaN(Date.parse(String(b.completion_date))))) return res.status(400).json({ error: 'The completion date is not a valid date.' });
  const sid = req.portal.supplierIds[0] || null, by = req.portal.email, out = { staged: [], applied: [] }; let _invoiceSubmit = null;
  try {
    if (!await portalAttachmentOk(req, b.invoice_attachment_id)) return res.status(403).json({ error: 'that attachment is not on your account' });   // v28.186 (Ben, M8)
    const stage = async (kind, value, attId) => {
      if (value == null || value === '') return;
      await pool.query(`UPDATE planner.supplier_submissions SET status='superseded' WHERE po=$1 AND kind=$2 AND status='pending'`, [b.po, kind]);
      await pool.query(`INSERT INTO planner.supplier_submissions (supplier_id,po,kind,value,attachment_id,status,submitted_by) VALUES ($1,$2,$3,$4,$5,'pending',$6)`,
        [sid, b.po, kind, String(value), attId || null, by]);
      out.staged.push(kind);
      // invoice / completion info → visible unread timeline note (+ email for invoices)
      if (kind === 'invoice_value' || kind === 'completion_date') await postSupplierSubmitNote(pool, b.po, kind, value, by);
      if (kind === 'invoice_value') _invoiceSubmit = String(value);
    };
    await stage('completion_date', b.completion_date);
    await stage('invoice_value', b.invoice_value == null ? null : sanitiseMoney(b.invoice_value), b.invoice_attachment_id);
    if ((b.tracking != null && b.tracking !== '') || (b.carrier != null && b.carrier !== '')) {
      const sh = (await pool.query(`SELECT shipment_ref FROM planner.purchase_orders WHERE po=$1`, [b.po])).rows[0];
      // v28.151 (review C2): a client-sent shipment_ref is honoured only if the caller owns that shipment (else the PO's own shipment);
      // stops a supplier overwriting another supplier's carrier / tracking by naming their shipment ref.
      // v28.186 (Ben, H3): carrier / tracking are shipment-level fields, so they apply directly only for the MASTER (consolidating)
      // supplier; a rider's entry is staged as a pending submission for Dock & Bay instead of overwriting the shared shipment.
      const _cref = String(b.shipment_ref || '').trim();
      const ref0 = (_cref && await portalOwnsShipmentRef(req, _cref)) ? _cref : (sh && sh.shipment_ref);
      const ref = (ref0 && (await portalShipmentRole(req, ref0)) === 'master') ? ref0 : null;
      if (ref) {
        const sets = [], vals = []; let i = 1;
        if (b.tracking != null && b.tracking !== '') { sets.push(`carrier_ref=$${i++}`); vals.push(b.tracking); }
        if (b.carrier != null && b.carrier !== '') { sets.push(`carrier=$${i++}`); vals.push(b.carrier); }
        vals.push(ref);
        await pool.query(`UPDATE planner.shipments SET ${sets.join(',')}, updated_at=now() WHERE shipment_ref=$${i}`, vals);
        await pool.query(`INSERT INTO planner.supplier_submissions (supplier_id,po,shipment_ref,kind,value,status,submitted_by,applied_by,applied_at) VALUES ($1,$2,$3,'tracking',$4,'applied',$5,$5,now())`,
          [sid, b.po, ref, JSON.stringify({ tracking: b.tracking || null, carrier: b.carrier || null }), by]);
        out.applied.push('tracking → ' + ref);
      } else {
        await pool.query(`INSERT INTO planner.supplier_submissions (supplier_id,po,shipment_ref,kind,value,status,submitted_by,note) VALUES ($1,$2,$3,'tracking',$4,'pending',$5,$6)`,
          [sid, b.po, ref0 || null, JSON.stringify({ tracking: b.tracking || null, carrier: b.carrier || null }), by, ref0 ? 'shared shipment: set by the consolidating supplier' : 'no shipment assigned yet']);
        out.staged.push('tracking');
      }
    }
    // supplier production status — '' clears it. Applied directly (like the internal preview handler).
    if (b.production_status != null) {
      const st = String(b.production_status).trim();
      if (st !== '' && !PROD_STATUSES.includes(st)) return res.status(400).json({ error: 'bad production_status' });
      await pool.query(`UPDATE planner.purchase_orders SET production_status=$2,
        production_confirmed_at=CASE WHEN $2='' THEN NULL ELSE now() END WHERE po=$1`, [b.po, st]);
      out.applied.push('production status → ' + (st || 'cleared'));
      // master PO marked shipped → its shipment advances to Shipping (master POs only)
      if (st === 'shipped') { const shref = await shipmentShippingFromMasterPO(pool, b.po); if (shref) out.applied.push('shipment ' + shref + ' → Shipping'); }
    }
    // v28.151 (review C1): PO confirmation from the portal (Confirm order / Approve / Approve all). Ported from the admin preview route
    // (/api/supply/portal-submit); this route had no branch for it, so portal confirms returned 200 but never persisted (live had 0
    // supplier confirmations ever). Ownership is enforced above by portalOwnsPO; confirmed_by = the signed-in portal user, never the client's submitted_by.
    if (b.po_confirmed != null) {
      if (b.po_confirmed) { await pool.query(`UPDATE planner.purchase_orders
          SET supplier_confirmed_at=now(), supplier_confirmed_by=$2,
              approved_lines=(SELECT jsonb_object_agg(sku, qty) FROM planner.purchase_order_lines WHERE po=$1 AND coalesce(qty,0)>0)
          WHERE po=$1`, [b.po, by]); out.applied.push('PO confirmed'); }   // snapshot the SKUs/qtys the supplier approved, diffed on re-approval
      else { await pool.query(`UPDATE planner.purchase_orders SET supplier_confirmed_at=NULL, supplier_confirmed_by=NULL WHERE po=$1`, [b.po]); out.applied.push('PO confirmation cleared'); }
    }
    if (_invoiceSubmit != null && !(await invoiceSubmitIsRepeat(b.po, _invoiceSubmit))) await emailInvoiceSubmit(b.po, _invoiceSubmit, by).catch(() => {});   // skip duplicate emails from repeated Submit clicks with the same amount
    res.json(out);
  } catch (e) { log500(e);
    // v28.191 (Ben, M7): if part of it was already saved, say exactly what (and refresh the caches for it) instead of a bare error
    const done = out.staged.concat(out.applied);
    if (done.length) { try { invalidateSupplyCaches('portal-po'); } catch (_) {} return res.status(409).json({ error: 'Only part of this was saved (' + done.join(', ') + '). Please refresh the page, check it, and send the rest again.', partial: out }); }
    res.status(500).json({ error: e.message }); }
});

// Local dev: listen. On Vercel (serverless) the platform imports `app` instead.
if (!process.env.VERCEL) {
  // DHL tracking in-app poller (long-lived server only; on Vercel the n8n schedule hits /api/tracking/poll).
  // Inert without DHL_API_KEY. Runs hourly; the poller itself honours per-number staleness vs the config interval.
  if (!process.env.VERCEL) {
    const tick = () => getDhlConfig().then(c => (c.enabled && c.key_present) ? pollTracking({ reason: 'timer' }) : null).catch(() => {});
    setTimeout(() => { tick(); setInterval(tick, 60 * 60 * 1000).unref?.(); }, 60 * 1000).unref?.();
    // v27.738: Fulfil PO mirror import (drift). Inert unless the Fulfil env is configured. n8n hits /api/supply/fulfil/import-pos in prod.
    const fimport = () => fulfilImportPOs().catch(() => {});
    setTimeout(() => { fimport(); setInterval(fimport, 6 * 60 * 60 * 1000).unref?.(); }, 90 * 1000).unref?.();
  }
  // v28.151 (review B4): loopback only by default (no gate locally and CIN7_AUTH is live, so the LAN must not reach it).
  // cloudflared tunnels still work (they connect to localhost). HOST=0.0.0.0 to opt back in; PORT for parallel dev servers.
  const _port = Number(process.env.PORT) || 8124, _host = process.env.HOST || '127.0.0.1';
  app.listen(_port, _host, () => console.log('rehost (live DATA + FC_CURRENT + save) on ' + _host + ':' + _port));
}
export default app;
